    local FB = ""
    local A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, 64 do map[A:byte(i)] = i - 1 end
    local pad = FB:sub(-2) == "==" and 2 or (FB:sub(-1) == "=" and 1 or 0)
    local out, n = {}, 0
    for i = 1, #FB, 4 do
        local v = (map[FB:byte(i)] or 0) * 262144 + (map[FB:byte(i + 1)] or 0) * 4096 + (map[FB:byte(i + 2)] or 0) * 64 + (map[FB:byte(i + 3)] or 0)
        n = n + 1
        out[n] = string.char(math.floor(v / 65536) % 256, math.floor(v / 256) % 256, v % 256)
    end
    local bin = table.concat(out)
    bin = bin:sub(1, #bin - pad)
    if writefile and getcustomasset then
        writefile("aspen_font.ttf", bin)
        writefile("aspen_font.json", game:GetService("HttpService"):JSONEncode({name = "AspenSans", faces = {{name = "Regular", weight = 400, style = "normal", assetId = getcustomasset("aspen_font.ttf")}}}))
