local function make(class, props, parent)
local o = Instance.new(class)
local isText = class == "TextLabel" or class == "TextButton" or class == "TextBox"
for k, v in pairs(props) do
if isText and (k == "FontFace" or k == "Font") then
if k == "Font" then k = "FontFace" end
v = (typeof(v) == "Font") and v or Core.Body
end
if k == "TextSize" and type(v) == "number" and (props.FontFace or isText) then local raw = v; v = math.floor(v * Core.Scale + 0.5); if raw < 20 then v = math.min(v, Core.BodyMax) end end
o[k] = v
end
if isText and props.FontFace == nil and props.Font == nil then
o.FontFace = Core.Body
end
if isText and (class == "TextLabel" or class == "TextButton") and o.TextColor3 == T.Text then
local tg = Instance.new("UIGradient")
tg.Name = "NoTheme"
tg.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(226, 212, 255))
tg.Parent = o
end
if parent then o.Parent = parent end
return o
end

-- ===================== SPIDER THEME: web drawing + intro cutscene =====================
function Core.line(parent, x1, y1, x2, y2, th, tr, col, z)
    local dx, dy = x2 - x1, y2 - y1
    local len = math.sqrt(dx * dx + dy * dy)
    local f = Instance.new("Frame")
    f.BorderSizePixel = 0
    f.BackgroundColor3 = col or Color3.new(1, 1, 1)
    f.BackgroundTransparency = math.clamp(tr or 0, 0, 1)
    f.AnchorPoint = Vector2.new(0.5, 0.5)
    f.Position = UDim2.fromOffset((x1 + x2) / 2, (y1 + y2) / 2)
    f.Size = UDim2.fromOffset(len, th)
    f.Rotation = math.deg(math.atan2(dy, dx))
    f.ZIndex = z or 1
    f.Active = false
    f.Parent = parent
    return f
end
function Core.drawWeb(parent, cx, cy, R, a0, a1, spokes, rings, th, tr, col, z)
    local out, pts = {}, {}
    for i = 0, spokes - 1 do
        local a = math.rad(a0 + (a1 - a0) * i / math.max(spokes - 1, 1))
        local rr = R * (0.8 + 0.2 * ((i * 7) % 5) / 4)
        pts[i] = {math.cos(a), math.sin(a), rr}
        out[#out + 1] = Core.line(parent, cx, cy, cx + math.cos(a) * rr, cy + math.sin(a) * rr, th, tr, col, z)
    end
    for r = 1, rings do
        local f = r / rings
        for i = 0, spokes - 2 do
            local p, q = pts[i], pts[i + 1]
            local x1, y1 = cx + p[1] * p[3] * f, cy + p[2] * p[3] * f
            local x2, y2 = cx + q[1] * q[3] * f, cy + q[2] * q[3] * f
            local mx = (x1 + x2) / 2 + (cx - (x1 + x2) / 2) * 0.14
            local my = (y1 + y2) / 2 + (cy - (y1 + y2) / 2) * 0.14
            out[#out + 1] = Core.line(parent, x1, y1, mx, my, th, tr + 0.08, col, z)
            out[#out + 1] = Core.line(parent, mx, my, x2, y2, th, tr + 0.08, col, z)
        end
    end
    return out
end
function Core.webIntro(gui, onFade)
    local TS = game:GetService("TweenService")
    local ov
    local ok, err = pcall(function()
        local cam = workspace.CurrentCamera
        local vp = cam and cam.ViewportSize or Vector2.new(1280, 720)
        local W, H = vp.X, vp.Y
        local cx, cy = W / 2, H / 2 + 24
        local function tw(o, t, p, st, dr)
            local tr = TS:Create(o, TweenInfo.new(t, st or Enum.EasingStyle.Quad, dr or Enum.EasingDirection.Out), p)
            tr:Play(); return tr
        end
        ov = Instance.new("CanvasGroup")
        ov.Name = "AspenIntro"; ov.BackgroundTransparency = 1; ov.BorderSizePixel = 0
        ov.Size = UDim2.fromScale(1, 1); ov.ZIndex = 2000; ov.Active = false; ov.GroupTransparency = 0
        ov.Parent = gui
        local back = Instance.new("Frame")
        back.BackgroundColor3 = Color3.fromRGB(6, 6, 6); back.BackgroundTransparency = 1; back.BorderSizePixel = 0
        back.Size = UDim2.fromScale(1, 1); back.ZIndex = 1; back.Active = false; back.Parent = ov
        tw(back, 0.35, {BackgroundTransparency = 0.38})
        -- rope (thick, twisted, frayed) revealed by a clip that grows from the right edge
        local L = W - cx + 70
        local clip = Instance.new("Frame")
        clip.BackgroundTransparency = 1; clip.BorderSizePixel = 0; clip.ClipsDescendants = true
        clip.AnchorPoint = Vector2.new(1, 0.5); clip.Position = UDim2.fromOffset(W + 70, cy)
        clip.Size = UDim2.fromOffset(0, 220); clip.ZIndex = 3; clip.Active = false; clip.Parent = ov
        local rope = Instance.new("Frame")
        rope.BackgroundTransparency = 1; rope.BorderSizePixel = 0
        rope.AnchorPoint = Vector2.new(1, 0.5); rope.Position = UDim2.fromScale(1, 0.5)
        rope.Size = UDim2.fromOffset(L, 220); rope.ZIndex = 3; rope.Active = false; rope.Parent = clip
        local rng = Random.new(math.floor(os.clock() * 1000) % 99991)
        local N, H0 = 24, 110
        local P = {}
        for i = 0, N do
            local t = i / N
            P[i] = Vector2.new(L - L * t, H0 + math.sin(t * 9.5) * (6 + 12 * t) + rng:NextNumber(-3.5, 3.5) + t * t * 24)
        end
        for i = 0, N - 1 do
            local a, b = P[i], P[i + 1]
            local t = i / N
            local d = (b - a); local mag = math.max(d.Magnitude, 0.001)
            local nx, ny = -d.Y / mag, d.X / mag
            local torn = rng:NextNumber() < 0.14
            local th = rng:NextNumber(5, 9.5) * (1 - 0.35 * t)
            local seg = Core.line(rope, a.X, a.Y, b.X + 1.5, b.Y, th, torn and 0.5 or rng:NextNumber(0, 0.08), Color3.fromRGB(250, 250, 252), 4)
            local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(0.5, 0); uc.Parent = seg
            local o1, o2 = math.sin(i * 1.7) * 3.6, math.cos(i * 1.3) * 3.6
            Core.line(rope, a.X + nx * o1, a.Y + ny * o1, b.X + nx * o2, b.Y + ny * o2, 2.4, 0.12, Color3.fromRGB(150, 152, 158), 5)
            Core.line(rope, a.X - nx * o2, a.Y - ny * o2, b.X - nx * o1, b.Y - ny * o1, 1.8, 0.25, Color3.fromRGB(215, 217, 222), 5)
            if rng:NextNumber() < 0.65 then
                local base = math.atan2(d.Y, d.X) + (rng:NextNumber() < 0.5 and 1 or -1) * math.rad(rng:NextNumber(22, 62))
                local fl = rng:NextNumber(10, 30)
                Core.line(rope, a.X, a.Y, a.X + math.cos(base) * fl, a.Y + math.sin(base) * fl, 1.2, 0.3, Color3.fromRGB(228, 230, 236), 5)
            end
        end
        -- ripped, frayed end
        local tip = P[N]
        for k = 1, 7 do
            local ang = math.pi + math.rad(rng:NextNumber(-65, 65))
            local l1, l2 = rng:NextNumber(10, 22), rng:NextNumber(8, 20)
            local mx, my = tip.X + math.cos(ang) * l1, tip.Y + math.sin(ang) * l1
            local ang2 = ang + math.rad(rng:NextNumber(-28, 28))
            Core.line(rope, tip.X, tip.Y, mx, my, 2.6 - k * 0.15, 0.08, Color3.fromRGB(240, 240, 244), 6)
            Core.line(rope, mx, my, mx + math.cos(ang2) * l2, my + math.sin(ang2) * l2, 1.2, 0.2, Color3.fromRGB(235, 236, 240), 6)
        end
        task.wait(0.25)
        tw(clip, 0.55, {Size = UDim2.fromOffset(L, 220)}, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        task.wait(0.5)
        -- impact: little sticky web splat at the tip + wobble
        local splat = Instance.new("Frame")
        splat.BackgroundTransparency = 1; splat.BorderSizePixel = 0; splat.Size = UDim2.fromOffset(0, 0)
        splat.Position = UDim2.fromOffset(cx, cy + tip.Y - H0); splat.ZIndex = 2; splat.Active = false; splat.Parent = ov
        local sc = Instance.new("UIScale"); sc.Scale = 0.15; sc.Parent = splat
        Core.drawWeb(splat, 0, 0, 64, 0, 360, 11, 3, 1.4, 0.3, Color3.fromRGB(235, 235, 240), 2)
        tw(sc, 0.45, {Scale = 1}, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        for _, a in ipairs({0.9, -0.6, 0.3, 0}) do
            tw(rope, 0.09, {Rotation = a}, Enum.EasingStyle.Sine)
            task.wait(0.09)
        end
        -- brand text above the web
        local lbl = Instance.new("TextLabel")
        lbl.BackgroundTransparency = 1; lbl.AnchorPoint = Vector2.new(0.5, 0.5)
        lbl.Position = UDim2.fromOffset(cx, cy - 112 + 14); lbl.Size = UDim2.fromOffset(460, 64)
        lbl.Text = "aspen.gg"; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 48
        lbl.TextColor3 = Color3.fromRGB(255, 255, 255); lbl.TextTransparency = 1; lbl.ZIndex = 8; lbl.Parent = ov
        local ul = Instance.new("Frame")
        ul.BackgroundColor3 = Color3.fromRGB(170, 170, 176); ul.BorderSizePixel = 0; ul.AnchorPoint = Vector2.new(0.5, 0.5)
        ul.Position = UDim2.fromOffset(cx, cy - 112 + 40); ul.Size = UDim2.fromOffset(0, 1); ul.ZIndex = 8; ul.Parent = ov
        tw(lbl, 0.55, {TextTransparency = 0, Position = UDim2.fromOffset(cx, cy - 112)})
        tw(ul, 0.7, {Size = UDim2.fromOffset(190, 1)}, Enum.EasingStyle.Quint)
        task.wait(1.55)
        if onFade then pcall(onFade) end
        tw(ov, 0.5, {GroupTransparency = 1})
        task.wait(0.52)
    end)
    if not ok then warn("[Aspen] intro failed: " .. tostring(err)) if onFade then pcall(onFade) end end
    if ov and ov.Parent then ov:Destroy() end
end
local function corner(o, r)
local sz = o.Size
if sz.X.Scale == 0 and sz.Y.Scale == 0 and sz.X.Offset > 0 and sz.Y.Offset > 0
and r * 2 >= math.min(sz.X.Offset, sz.Y.Offset) - 1 then
return make("UICorner", {CornerRadius = UDim.new(1, 0)}, o)
end
return make("UICorner", {CornerRadius = UDim.new(0, 4)}, o)
end
local function stroke(o, c, th, tr)
return make("UIStroke", {Color = c, Thickness = th or 1, Transparency = tr or 0,
ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o)
end
local function padding(o, t, r, b, l)
return make("UIPadding", {PaddingTop = UDim.new(0, t or 0), PaddingRight = UDim.new(0, r or 0),
PaddingBottom = UDim.new(0, b or 0), PaddingLeft = UDim.new(0, l or 0)}, o)
end
local DUMMY_TW = {Completed = {Connect = function(_, f) task.defer(f); return {Disconnect = function() end} end, Wait = function() task.wait(0.1) end},
Play = function() end, Cancel = function() end, Pause = function() end}
Core.reduceMotion = false
local activeTweens = setmetatable({}, {__mode = "k"})
local function tween(o, t, props, style, dir)
    if Core.reduceMotion or not o or not o.Parent then
        for k, v in pairs(props) do pcall(function() o[k] = v end) end
        return DUMMY_TW
    end
    -- Keep interface motion direct; avoid elastic/back/bounce easing.
    if style == nil or style == Enum.EasingStyle.Back or style == Enum.EasingStyle.Bounce
        or style == Enum.EasingStyle.Elastic or style == Enum.EasingStyle.Quint then
        style = Enum.EasingStyle.Quad
    end
    local info = TweenInfo.new(math.clamp(t or 0.16, 0.08, 0.24), style, dir or Enum.EasingDirection.Out)
    local per = activeTweens[o]
    if not per then per = {}; activeTweens[o] = per end
    local first
    for k, v in pairs(props) do
        local prev = per[k]
        if prev then pcall(function() prev:Cancel() end) end
        local ok, tw = pcall(function() return TweenService:Create(o, info, {[k] = v}) end)
        if ok and tw then
            per[k] = tw
            tw.Completed:Connect(function() if per[k] == tw then per[k] = nil end end)
            tw:Play()
            first = first or tw
        else
            pcall(function() o[k] = v end)
        end
    end
    return first or DUMMY_TW
end
local function ripple(parent, x, y)
