function Core.migKey(k)
if type(k) ~= "string" then return k end
local oldConfigPrefix = "Settings.Config Profiles."
if k:sub(1, #oldConfigPrefix) == oldConfigPrefix then
return "Configs.Config Profiles." .. k:sub(#oldConfigPrefix + 1)
end
local MIG = {
{"Player.Slide.", false},
{"Player.Movement.Other.Noclip", "Player.Movement.Physics.Noclip"},
{"Player.Movement.Other.Auto Strafe", "Player.Movement.Air Control.Auto Strafe"},
{"Player.Movement.Speed.Custom Walk Speed", "Player.Movement.Ground.Custom Walk Speed"},
{"Player.Movement.Speed.Walk Speed Multiplier", "Player.Movement.Ground.Walk Speed Multiplier"},
{"Player.Movement.Speed.Custom Jump Power", "Player.Movement.Jump Power.Custom Jump Power"},
{"Player.Movement.Speed.Jump Power Multiplier", "Player.Movement.Jump Power.Jump Power Multiplier"},
{"Player.Movement.Speed.Custom Gravity", "Player.Movement.Physics.Custom Gravity"},
{"Player.Movement.Speed.Gravity", "Player.Movement.Physics.Gravity"},
{"Player.Movement.Air.Infinite Jump", "Player.Movement.Jump Power.Infinite Jump"},
{"Player.Movement.Air.Bunny Hop", "Player.Movement.Jump Power.Bunny Hop"},
{"Player.Movement.Air.Auto Strafe", "Player.Movement.Air Control.Auto Strafe"},
{"Player.Movement.Air.Auto Strafe Speed", "Player.Movement.Air Control.Auto Strafe Speed"},
{"Player.Movement.Collision.Noclip", "Player.Movement.Physics.Noclip"},
}
if k:sub(1, 7) ~= "Player." then return k end
for _, m in ipairs(MIG) do
