        local halo = make("ImageLabel", {Name = "BackgroundSnowHalo", BackgroundTransparency = 1,
            Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = Color3.new(1, 1, 1),
            ImageTransparency = rng:NextNumber(0.72, 0.86), AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(rng:NextNumber(), rng:NextNumber()),
            Size = UDim2.fromOffset(sz * rng:NextNumber(2.2, 3.2), sz * rng:NextNumber(2.2, 3.2)),
            ZIndex = 1, Active = false}, bgSnow)
        local dot = make("Frame", {Name = "BackgroundSnowflake", BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = rng:NextNumber(0.02, 0.18), BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0.5, 0.5), Position = halo.Position,
            Size = UDim2.fromOffset(sz, sz), ZIndex = 2, Active = false}, bgSnow)
        make("UICorner", {CornerRadius = UDim.new(1, 0)}, dot)
        flakes[#flakes + 1] = {dot = dot, halo = halo, x = rng:NextNumber(),
            y = rng:NextNumber(-0.1, 1), speed = rng:NextNumber(0.07, 0.13),
            wind = rng:NextNumber(0.035, 0.085), drift = rng:NextNumber(0.008, 0.026),
            phase = rng:NextNumber(0, 6.28)}
    end
    -- The hub window is created immediately after this layer; bind visibility once it exists.
    local hubWindow
    task.spawn(function()
        repeat task.wait() until not bgSnow.Parent or gui:FindFirstChild("Holder")
        local h = gui:FindFirstChild("Holder")
        hubWindow = h and h:FindFirstChild("Window")
        if not hubWindow then return end
        local function syncVisibility()
            bgSnow.Visible = hubWindow.Visible and hubWindow.GroupTransparency < 0.95
        end
        hubWindow:GetPropertyChangedSignal("Visible"):Connect(syncVisibility)
        hubWindow:GetPropertyChangedSignal("GroupTransparency"):Connect(syncVisibility)
        syncVisibility()
    end)
    track(RunService.RenderStepped:Connect(function(dt)
        if not bgSnow.Parent then return end
        if not hubWindow or not hubWindow.Visible or hubWindow.GroupTransparency >= 0.95 then
            bgSnow.Visible = false
            return
        end
        bgSnow.Visible = true
        local t = os.clock()
        local gust = math.sin(t * 0.45) * 0.035 + math.sin(t * 1.1) * 0.018
        for _, f in ipairs(flakes) do
            f.y = f.y + f.speed * math.min(dt, 0.05)
            f.x = f.x + (f.wind + gust) * math.min(dt, 0.05)
            if f.y > 1.04 then f.y = -0.04; f.x = rng:NextNumber(-0.08, 0.88) end
            if f.x > 1.08 then f.x = -0.08 end
            local sway = math.sin(t * 1.1 + f.phase) * f.drift
            local pos = UDim2.fromScale(math.clamp(f.x + sway, -0.10, 1.10), f.y)
            f.dot.Position = pos
            f.halo.Position = pos
        end
    end))
end
