local function decorate(o)
    if not o or not o.Parent or o:GetAttribute("Frosted") then return end
    local cls = o.ClassName
    local isBtn = cls == "TextButton"
    local isRow = cls == "Frame" and o:GetAttribute("SecId") ~= nil
    if not (isBtn or isRow) then return end
    if o.BackgroundTransparency > 0.6 or o.ZIndex >= 50 then return end
    for _, c in ipairs(o:GetChildren()) do if c:IsA("UIGridStyleLayout") then return end end
    if o.AbsoluteSize.Y > 90 then return end
    local sz = o.Size
    if sz.X.Scale == 0 and sz.X.Offset > 0 and sz.X.Offset < 24 then return end
    if sz.Y.Scale == 0 and sz.Y.Offset > 0 and (sz.Y.Offset < 16 or sz.Y.Offset > 90) then return end
    local p, d = o.Parent, 0
    while p and p ~= gui and d < 14 do
        if p.Name == "AspenStyle" or p.Name == "ThemeFX" or p.Name == "AspenWebs" then return end
        p = p.Parent; d = d + 1
    end
    o:SetAttribute("Frosted", true)
    local ov = Instance.new("Frame")
    ov.Name = "AspenStyle"; ov.BackgroundTransparency = 1; ov.BorderSizePixel = 0
    ov.Size = UDim2.fromScale(1, 1); ov.Active = false; ov.ZIndex = 20
    local cr = o:FindFirstChildOfClass("UICorner")
    local uc = Instance.new("UICorner"); uc.CornerRadius = cr and cr.CornerRadius or UDim.new(0, 4); uc.Parent = ov
    local st = Instance.new("UIStroke")
    st.Color = WHITE; st.Thickness = 1; st.Transparency = 0.7; st.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; st.Parent = ov
    local gl = Instance.new("Frame")
    gl.BackgroundColor3 = WHITE; gl.BorderSizePixel = 0; gl.Size = UDim2.fromScale(1, 0.5); gl.Active = false; gl.ZIndex = 20
    local gg = Instance.new("UIGradient"); gg.Rotation = 90
    gg.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.9), NumberSequenceKeypoint.new(1, 1)}); gg.Parent = gl
    local gc = Instance.new("UICorner"); gc.CornerRadius = uc.CornerRadius; gc.Parent = gl
    gl.Parent = ov
    ov.Parent = o
end
track(gui.DescendantAdded:Connect(function(o) task.defer(decorate, o) end))
for _, d in ipairs(gui:GetDescendants()) do task.defer(decorate, d) end
end
