        local dot = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1),
            BackgroundTransparency = snowRng:NextNumber(0.25, 0.48), BorderSizePixel = 0,
            AnchorPoint = Vector2.new(0.5, 0.5), Position = glow.Position,
            Size = UDim2.fromOffset(size, size), ZIndex = 81, Active = false}, snowLayer)
        make("UICorner", {CornerRadius = UDim.new(1, 0)}, dot)
        flakes[#flakes + 1] = {
