end
local function ornament(px, py, L, D)
local kinds = {"ball", "ball", "stripe", "gem", "star", "bell", "flake", "ball"}
local kind = kinds[ri(1, #kinds)]
local col = (kind == "bell" or kind == "star") and C3(246, 200, 76) or OC[ri(1, #OC)]
local S = 2 * (L + D) + 24
local c = make("Frame", {BackgroundTransparency = 1, AnchorPoint = V2(0.5, 0.5), Position = UD(px, py), Size = UD(S, S), ZIndex = 65, Active = false, BorderSizePixel = 0}, deco)
local cy = L + D * 0.5
local rope = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BorderSizePixel = 0, AnchorPoint = V2(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UD(3, L), ZIndex = 65, Active = false}, c)
make("UIGradient", {Name = "NoTheme", Rotation = 0, Color = GOLD}, rope)
make("Frame", {BackgroundColor3 = C3(255, 240, 190), BorderSizePixel = 0, AnchorPoint = V2(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, 0), Size = UD(9, 9), ZIndex = 65, Active = false}, c)
local halo = make("ImageLabel", {BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = col, ImageTransparency = 0.5, AnchorPoint = V2(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, cy), Size = UD(D * 3, D * 3), ZIndex = 64, Active = false}, c)
local function shade(f)
make("UIGradient", {Name = "NoTheme", Rotation = 55, Color = ColorSequence.new({K(0, col:Lerp(SNOW, 0.6)), K(0.4, col), K(1, col:Lerp(C3(0, 0, 0), 0.5))})}, f)
make("UIStroke", {Color = col:Lerp(C3(0, 0, 0), 0.55), Thickness = 1.2, Transparency = 0.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, f)
end
local function body(size, rot, r)
local b = make("Frame", {BackgroundColor3 = col, BorderSizePixel = 0, AnchorPoint = V2(0.5, 0.5), Position = UDim2.new(0.5, 0, 0.5, cy), Size = size, Rotation = rot or 0, ZIndex = 66, Active = false}, c)
make("UICorner", {CornerRadius = r or UDim.new(0.5, 0)}, b)
shade(b)
return b
end
