local searchBox = make("TextBox", {BackgroundTransparency = 1, Position = UDim2.fromOffset(10, 0), Size = UDim2.new(1, -36, 1, 0),
Text = "", PlaceholderText = "search features", PlaceholderColor3 = T.Dim, FontFace = F_BOLD, TextSize = 14,
TextColor3 = T.Text, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ZIndex = 6}, searchWrap)
track(UIS.InputBegan:Connect(function(i, gp)
    if gp then return end
    local ctrl = UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)
    if i.KeyCode == Enum.KeyCode.Escape and searchBox:IsFocused() then
        searchBox.Text = ""
        searchBox:ReleaseFocus()
        return
    end
    if ctrl and i.KeyCode == Enum.KeyCode.F and not UIS:GetFocusedTextBox() then
        if searchBox:IsDescendantOf(gui) then searchBox:CaptureFocus() end
        return
    end
    if i.KeyCode == Enum.KeyCode.Slash and not UIS:GetFocusedTextBox() then
        if not searchBox:IsDescendantOf(gui) then return end
        searchBox:CaptureFocus()
        task.defer(function() searchBox.Text = "" end)
    end
end))
searchBox.Focused:Connect(function() tween(searchStroke, 0.15, {Color = Anim.Gold, Transparency = 0}); tween(searchWrap, 0.22, {Size = UDim2.fromOffset(260, 28)}, Enum.EasingStyle.Quad) end)
searchBox.FocusLost:Connect(function() tween(searchStroke, 0.15, {Color = T.Border, Transparency = 0.4}); tween(searchWrap, 0.2, {Size = UDim2.fromOffset(210, 28)}) end)
