local filterPage
local function pageRows(page)
local out = {}
local function walk(p)
for _, c in ipairs(p:GetChildren()) do
if c:GetAttribute("ColFrame") then walk(c) else out[#out + 1] = c end
end
end
walk(page)
return out
end
Core.pageRows = pageRows
filterPage = function(page)
if not page then return end
local q = string.lower(searchBox.Text or "")
local rows = pageRows(page)
for _, c in ipairs(rows) do
if c:IsA("GuiObject") then
if c:GetAttribute("Hid") then
c.Visible = false
elseif c:GetAttribute("Sec") then
c.Visible = (q == "")
else
local sx = c:GetAttribute("S")
if sx then
if q == "" then c.Visible = true
else c.Visible = string.find(sx, q, 1, true) ~= nil end
end
end
end
end
local holder = page:FindFirstChild("Cols")
if holder then
local pl = page:FindFirstChildOfClass("UIListLayout")
local shown = 0
for _, col in ipairs(holder:GetChildren()) do
if col:GetAttribute("ColFrame") then
for _, card in ipairs(col:GetChildren()) do
if card:GetAttribute("IsCard") then
local any = false
for _, r in ipairs(card:GetChildren()) do
if r:IsA("GuiObject") and r.Visible and (r:GetAttribute("S") or r:GetAttribute("Sec")) then any = true; break end
end
card.Visible = any
if any then shown = shown + (1) end
local cl = card:FindFirstChildOfClass("UIListLayout")
if cl and pl then pcall(function() cl.HorizontalAlignment = pl.HorizontalAlignment end) end
end
end
end
end
local c1, c2 = holder:FindFirstChild("Col1"), holder:FindFirstChild("Col2")
if c1 and c2 then
if shown <= 1 then c1.Size = UDim2.new(1, 0, 0, 0); c2.Visible = false
else c1.Size = UDim2.new(0.5, -7, 0, 0); c2.Visible = true end
end
end
end
do
local raw = filterPage
filterPage = function(page)
raw(page)
local q = string.lower(searchBox.Text or "")
local any = false
if page and q ~= "" then
for _, c in ipairs(pageRows(page)) do
if c:IsA("GuiObject") and c.Visible and c:GetAttribute("S") then any = true; break end
end
end
emptyLbl.Visible = (page ~= nil and q ~= "" and not any)
if emptyLbl.Visible then emptyLbl.Text = "Nothing matches \"" .. searchBox.Text .. "\"" end
end
end
searchBox:GetPropertyChangedSignal("Text"):Connect(function() filterPage(activeSub and activeSub.page) end)
local GLOW_T = 1
local function flash(b)
if true then return end
local fl = make("Frame", {BackgroundColor3 = T.AccentHi, BackgroundTransparency = 0.55, Size = UDim2.fromScale(1, 1), BorderSizePixel = 0, ZIndex = 6}, b)
make("UICorner", {CornerRadius = UDim.new(0, 4)}, fl)
tween(fl, 0.45, {BackgroundTransparency = 1}, Enum.EasingStyle.Quad)
task.delay(0.5, function() pcall(function() fl:Destroy() end) end)
end
local function selectSub(m, s)
if activeSub == s then return end
if not s or not s.page or not s.btn then return end
if activeSub then
pcall(function()
activeSub.page.Visible = false
tween(activeSub.btn, 0.2, {BackgroundTransparency = 1})
tween(activeSub.btn, 0.2, {TextColor3 = T.Text}); activeSub.btn.TextSize = Core.SubSize; activeSub.btn.TextStrokeTransparency = 1; if activeSub.icon then activeSub.icon.Size = UDim2.fromOffset(14, 14) end
if activeSub.icon then tween(activeSub.icon, 0.2, {ImageColor3 = T.Text}) end
if activeSub.stroke then tween(activeSub.stroke, 0.2, {Transparency = 1}) end
if activeSub.glow then tween(activeSub.glow, 0.2, {ImageTransparency = 1}) end
if activeSub.line then tween(activeSub.line, 0.2, {BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0, 3)}) end
end)
end
activeSub = s
m.lastSub = s
s.page.Visible = true
s.page.CanvasPosition = Vector2.new(0, 0)
s.page.Position = UDim2.fromOffset(0, 14); tween(s.page, 0.4, {Position = UDim2.fromOffset(0, 0)}, Enum.EasingStyle.Quint)
filterPage(s.page)
descLabel.Text = ""
crumb.Text = string.upper(m.display or m.name) .. "   >   " .. string.upper(s.name)
crumb.Position = UDim2.new(0.5, 44, 0.5, 1); tween(crumb, 0.4, {Position = UDim2.new(0.5, 24, 0.5, 1)}, Enum.EasingStyle.Quint)
tween(s.btn, 0.28, {BackgroundTransparency = 0.82})
tween(s.btn, 0.28, {TextColor3 = Color3.new(1, 1, 1)}); s.btn.TextSize = Core.SubSizeSel; s.btn.TextStrokeTransparency = 1; if s.icon then s.icon.Size = UDim2.fromOffset(14, 14) end
if s.icon then tween(s.icon, 0.28, {ImageColor3 = T.AccentHi}) end
s.btn.FontFace = F_HEAVY
if s.stroke then s.stroke.Enabled = true; tween(s.stroke, 0.3, {Transparency = 0.3}) end
if s.glow then tween(s.glow, 0.35, {ImageTransparency = 0.32}) end
if s.line then s.line.BackgroundTransparency = 0; s.line.Size = UDim2.new(0, 0, 0, 3); tween(s.line, 0.4, {Size = UDim2.new(1, -14, 0, 3)}, Enum.EasingStyle.Quint) end
return true
end
local function selectMain(m)
if activeMain == m then return end
if activeMain then
activeMain.bar.scroll.Visible = false
tween(activeMain.item, 0.2, {BackgroundTransparency = 1})
tween(activeMain.itemBar, 0.2, {BackgroundTransparency = 1, Size = UDim2.fromOffset(6, 3)})
if activeMain.icon then tween(activeMain.icon, 0.2, {ImageColor3 = T.Text, ImageTransparency = 0, Size = UDim2.fromOffset(18, 18)}) end
pcall(function() tween(activeMain.glow, 0.2, {ImageTransparency = 1}); tween(activeMain.selStroke, 0.2, {Transparency = 1}) end)
tween(activeMain.itemLbl, 0.2, {TextColor3 = T.Text})
activeMain.itemLbl.TextStrokeTransparency = 1
activeMain.itemLbl.FontFace = F_BOLD
if activeSub then
pcall(function()
activeSub.page.Visible = false
tween(activeSub.btn, 0.2, {BackgroundTransparency = 1})
tween(activeSub.btn, 0.2, {TextColor3 = T.Text}); activeSub.btn.TextSize = Core.SubSize; activeSub.btn.TextStrokeTransparency = 1; if activeSub.icon then activeSub.icon.Size = UDim2.fromOffset(14, 14) end
if activeSub.icon then tween(activeSub.icon, 0.2, {ImageColor3 = T.Text}) end
if activeSub.glow then tween(activeSub.glow, 0.2, {ImageTransparency = 1}) end
if activeSub.line then tween(activeSub.line, 0.2, {BackgroundTransparency = 1, Size = UDim2.new(0, 0, 0, 3)}) end
end)
activeSub = nil
end
end
activeMain = m
m.bar.scroll.Visible = true
m.bar.scroll.Position = UDim2.fromOffset(10, 14); tween(m.bar.scroll, 0.4, {Position = UDim2.fromOffset(10, 4)}, Enum.EasingStyle.Quint)
tween(m.item, 0.28, {BackgroundTransparency = m.icon and 0.78 or 1})
m.itemBar.Visible = true
m.itemBar.BackgroundTransparency = 0; m.itemBar.Size = UDim2.fromOffset(6, 3); tween(m.itemBar, 0.12, {Size = UDim2.new(1, 0, 0, 1)})
if m.icon then tween(m.icon, 0.28, {ImageColor3 = T.AccentHi, ImageTransparency = 0}); m.icon.Size = UDim2.fromOffset(11, 11); tween(m.icon, 0.5, {Size = UDim2.fromOffset(18, 18)}, Enum.EasingStyle.Back) end
pcall(function() tween(m.glow, 0.35, {ImageTransparency = 0.3}); tween(m.selStroke, 0.3, {Transparency = 0.35}) end)
tween(m.itemLbl, 0.28, {TextColor3 = Color3.new(1, 1, 1)})
m.itemLbl.TextStrokeTransparency = 1
m.itemLbl.FontFace = F_HEAVY
if m.subs[1] then
local okS = pcall(selectSub, m, m.lastSub or m.subs[1])
if not okS then pcall(selectSub, m, m.subs[1]) end
end
end
do
local tip
function Core.showTip(item, text)
if true then return end
if not tip then
tip = make("Frame", {BackgroundColor3 = T.Panel, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0.5),
AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 30), ZIndex = 60, Visible = false}, win)
corner(tip, 2); stroke(tip, T.Border, 1, 0.2); padding(tip, 0, 10, 0, 10)
make("TextLabel", {Name = "L", BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.new(0, 0, 1, 0),
Text = "", FontFace = F_HEAVY, TextSize = 14, TextColor3 = T.Text, ZIndex = 61}, tip)
end
tip.L.Text = text
local s = math.max(sidebar.AbsoluteSize.X / SIDE_W, 0.01)
tip.Position = UDim2.fromOffset((sidebar.AbsolutePosition.X - win.AbsolutePosition.X) / s - 6,
(item.AbsolutePosition.Y - win.AbsolutePosition.Y) / s + item.AbsoluteSize.Y / s / 2)
