end
function Core.hideTip() if tip then tip.Visible = false end end
end
local function addMain(name, desc, iconKind)
local m = {name = name, desc = desc, subs = {}}
local hasIc = Core.ICONS_ON and Core.ICONS[name] ~= nil
local tabButtonSize = UDim2.new(0, hasIc and 46 or (#name * 9 + 22), 1, 0)
local item = make("TextButton", {BackgroundColor3 = T.Accent, BackgroundTransparency = 1, Selectable = false, Size = tabButtonSize,
Text = "", AutoButtonColor = false, LayoutOrder = sideOrder + 1, ZIndex = 3}, ddList)
sideOrder = sideOrder + (1)
corner(item, 2)
local itemBar = make("Frame", {BackgroundColor3 = T.Accent, BackgroundTransparency = 1, Size = UDim2.fromOffset(6, 3),
AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -1), BorderSizePixel = 0, ZIndex = 4}, item)
corner(itemBar, 2)
local itemLbl = make("TextLabel", {BackgroundTransparency = 1, Position = UDim2.fromOffset(hasIc and 30 or 0, 0),
Size = UDim2.new(1, hasIc and -34 or 0, 1, 0), Visible = not hasIc, Text = name, FontFace = F_BOLD, TextSize = 15, TextColor3 = T.Sub,
TextXAlignment = hasIc and Enum.TextXAlignment.Left or Enum.TextXAlignment.Center, ZIndex = 4}, item)
m.item, m.itemBar, m.itemLbl = item, itemBar, itemLbl
if Core.ICONS_ON and Core.ICONS[name] then
m.icon = Core.mkIcon(item, name, 18, T.Text, 0)
local uc_ = item:FindFirstChildOfClass("UICorner"); if uc_ then uc_.CornerRadius = UDim.new(0, 4) end
m.icon.AnchorPoint = Vector2.new(0.5, 0.5); m.icon.Position = UDim2.fromScale(0.5, 0.5)
end
item.Selectable = false; itemBar.Visible = true; itemBar.Size = UDim2.fromOffset(6, 3)
do
m.glow = make("ImageLabel", {Name = "TabGlow", BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = T.Accent,
ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, 40, 1, 34), ZIndex = 2, Active = false}, item)
onAccent(function() m.glow.ImageColor3 = T.Accent end)
m.selStroke = make("UIStroke", {Name = "TabSel", Color = T.AccentHi, Thickness = 1.2, Transparency = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, item)
onAccent(function() m.selStroke.Color = T.AccentHi end)
end
if false then
local ic = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -30, 0.5, 0), Size = UDim2.fromOffset(16, 16), ZIndex = 4}, item)
local function ring(sz, w) local f = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = sz, ZIndex = 4}, ic); corner(f, 2); local st = make("UIStroke", {Thickness = w, Color = T.Accent}, f); onAccent(function() st.Color = T.Accent end); return f end
if iconKind == "eye" then
ring(UDim2.fromOffset(16, 9), 1.5)
local p = make("Frame", {BackgroundColor3 = T.Accent, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(5, 5), BorderSizePixel = 0, ZIndex = 5}, ic); corner(p, 2)
onAccent(function() p.BackgroundColor3 = T.Accent end)
elseif iconKind == "globe" then
ring(UDim2.fromOffset(15, 15), 1.5); ring(UDim2.fromOffset(7, 15), 1)
local l = make("Frame", {BackgroundColor3 = T.Accent, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 1), BorderSizePixel = 0, ZIndex = 5}, ic)
onAccent(function() l.BackgroundColor3 = T.Accent end)
end
end
onAccent(function()
item.BackgroundColor3 = T.Accent; itemBar.BackgroundColor3 = T.Accent
end)
local scroll = make("ScrollingFrame", {BackgroundTransparency = 1, Position = UDim2.fromOffset(10, 4),
Size = UDim2.new(1, -20, 0, SUB_H - 2), Visible = false, BorderSizePixel = 0, ScrollBarThickness = 0,
ScrollingDirection = Enum.ScrollingDirection.X, CanvasSize = UDim2.new(),
AutomaticCanvasSize = Enum.AutomaticSize.X, ZIndex = 3}, subBarHolder)
make("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 0),
SortOrder = Enum.SortOrder.LayoutOrder, VerticalAlignment = Enum.VerticalAlignment.Center}, scroll)
padding(scroll, 0, 2, 0, 2)
m.bar = {scroll = scroll}
item.MouseEnter:Connect(function()
if activeMain ~= m then hoverSfx(); tween(itemLbl, 0.15, {TextColor3 = T.Text}) end
end)
item.MouseLeave:Connect(function()
if activeMain ~= m then tween(item, 0.15, {BackgroundTransparency = 1}); tween(itemLbl, 0.15, {TextColor3 = T.Sub}) end
end)
item.MouseButton1Click:Connect(function() if activeMain ~= m then switchSfx(); selectMain(m) end end)
if m.icon then
item.MouseEnter:Connect(function()
if activeMain ~= m then m.icon.ImageColor3 = T.AccentHi; item.BackgroundTransparency = 0.9 end
Core.showTip(item, name)
end)
item.MouseLeave:Connect(function()
if activeMain ~= m then m.icon.ImageColor3 = T.Text; item.BackgroundTransparency = 1 end
Core.hideTip()
end)
end
table.insert(mains, m)
ddFullH = ddFullH + (Core.ITEM_H + 1)
-- (ddList sizes itself horizontally)
return m
end
