local gname = Core.TabMerge[m.name .. "|" .. name]
m.groups = m.groups or {}
local lead = gname and m.groups[gname] or nil
local btn, line, selStroke, page, colF, colH, host, curCol
if lead then
btn, line, selStroke, page, colF, colH = lead.btn, lead.line, lead.stroke, lead.page, lead.colF, lead.colH
host = page
s.btn, s.line, s.stroke, s.glow, s.icon, s.page, s.joined = lead.btn, lead.line, lead.stroke, lead.glow, lead.icon, lead.page, lead
else
if gname then s.group = gname; s.desc = Core.TabDesc[gname] or desc end
btn = make("TextButton", {BackgroundTransparency = 1, Size = UDim2.new(0, 0, 1, -8), AutomaticSize = Enum.AutomaticSize.X,
Text = gname or name, FontFace = F_BOLD, TextSize = 14, TextColor3 = T.Text, AutoButtonColor = false, Selectable = false,
BackgroundColor3 = T.Accent, BackgroundTransparency = 1, LayoutOrder = #m.subs + 1, ZIndex = 4}, m.bar.scroll)
local iconName = (gname and Core.TabIcon[gname]) or name
if Core.ICONS_ON and Core.ICONS[iconName] then
padding(btn, 0, 10, 0, 10 + 20 + 4)
s.icon = Core.mkIcon(btn, iconName, 14, T.Text, 0)
s.icon.AnchorPoint = Vector2.new(0, 0.5); s.icon.Position = UDim2.new(0, -25, 0.5, 0)
else
padding(btn, 0, 12, 0, 12)
end
btn.FontFace = F_HEAVY
btn.TextXAlignment = Enum.TextXAlignment.Center; btn.TextYAlignment = Enum.TextYAlignment.Center; btn.TextSize = Core.SubSize
corner(btn, 2)
do local uc_ = btn:FindFirstChildOfClass("UICorner"); if uc_ then uc_.CornerRadius = UDim.new(0, 4) end end
onAccent(function() btn.BackgroundColor3 = T.Accent end)
selStroke = make("UIStroke", {Name = "SubSel", Enabled = false, Color = T.AccentHi, Thickness = 1, Transparency = 1,
ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, btn)
onAccent(function() selStroke.Color = T.AccentHi end)
line = make("Frame", {BackgroundColor3 = T.Accent, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, 0),
Size = UDim2.new(0, 0, 0, 2), BorderSizePixel = 0, ZIndex = 5}, btn)
corner(line, 2)
line.BackgroundColor3 = Anim.W
do
local lg = make("UIGradient", {Name = "NoTheme"}, line)
onAccent(function() lg.Color = ColorSequence.new({ColorSequenceKeypoint.new(0, T.Accent), ColorSequenceKeypoint.new(0.5, Anim.Gold), ColorSequenceKeypoint.new(1, T.Accent)}) end)
end
s.btn, s.line, s.stroke = btn, line, selStroke
s.glow = make("ImageLabel", {Name = "SubGlow", BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = T.Accent,
ImageTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, 44, 1, 20), ZIndex = 3, Active = false}, btn)
onAccent(function() s.glow.ImageColor3 = T.Accent end)
btn.Selectable = false; line.Visible = true
page = make("ScrollingFrame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Visible = false,
BorderSizePixel = 0, ScrollBarThickness = 2, ScrollBarImageColor3 = T.Accent, CanvasSize = UDim2.new(),
AutomaticCanvasSize = Enum.AutomaticSize.Y, ZIndex = 2}, pagesHolder)
padding(page, 4, 10, 12, 10)
make("UIListLayout", {Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder}, page)
local colsHolder = make("Frame", {Name = "Cols", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(1, 0, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 100000000, ZIndex = 2}, page)
colsHolder:SetAttribute("ColFrame", true)
make("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 10), SortOrder = Enum.SortOrder.LayoutOrder,
VerticalAlignment = Enum.VerticalAlignment.Top}, colsHolder)
colF, colH, host, curCol = {}, {0, 0}, page, nil
for i = 1, 2 do
colF[i] = make("Frame", {Name = "Col" .. i, BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.new(0.5, -7, 0, 0),
AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = i, ZIndex = 2}, colsHolder)
colF[i]:SetAttribute("ColFrame", true)
