local keys, sw = {"Accent", "AccentHi", "Bg", "Element", "Text"}, {}
for i, k in ipairs(keys) do
local s = make("Frame", {BackgroundColor3 = T[k], AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -10 - (#keys - i) * 30, 0.5, 0),
Size = UDim2.fromOffset(24, 22), BorderSizePixel = 0, ZIndex = 5}, f)
corner(s, 2); stroke(s, T.Border, 1, 0.3)
sw[i] = s
end
