if drag == "L" then lo = math.min(v, hi) elseif drag == "H" then hi = math.max(v, lo)
else drag = (math.abs(v - lo) <= math.abs(v - hi)) and "L" or "H"; if drag == "L" then lo = math.min(v, hi) else hi = math.max(v, lo) end end
refresh(false); markDirty()
end
