local seen, out = {}, {}
for name, c in pairs(Cosmetics) do
local w = type(c) == "table" and c.ItemName
if type(c) == "table" and c.Type == "Skin" and type(w) == "string" and w ~= "" and not isPlaceholder(w)
and not isPlaceholder(name) and not seen[w] then
seen[w] = true
out[#out + 1] = w
end
end
table.sort(out)
weaponCache = out
