mv.Section("Movement Utilities")
local hyperflashBusy = false
local function performHyperflash()
    if not P.hyperflash or hyperflashBusy then return end
    local h, r = hum(), root()
    if not h or not r or h.Health <= 0 then return end
    local direction = h.MoveDirection
    if direction.Magnitude < 0.05 then direction = r.CFrame.LookVector end
    direction = Vector3.new(direction.X, 0, direction.Z)
    if direction.Magnitude < 0.05 then return end
    direction = direction.Unit
    hyperflashBusy = true
    task.spawn(function()
        local started = os.clock()
        while P.hyperflash and os.clock() - started < P.hyperflashDuration do
            if not r.Parent or h.Health <= 0 then break end
            local current = r.AssemblyLinearVelocity
            r.AssemblyLinearVelocity = Vector3.new(direction.X * P.hyperflashForce, current.Y, direction.Z * P.hyperflashForce)
            RunService.RenderStepped:Wait()
        end
        hyperflashBusy = false
    end)
end

local mobileSlideConnection
local function disconnectMobileSlide()
    if mobileSlideConnection then
        pcall(function() mobileSlideConnection:Disconnect() end)
        mobileSlideConnection = nil
    end
end
local function bindMobileSlide()
    disconnectMobileSlide()
    local playerGui = lp:FindFirstChildOfClass("PlayerGui")
    local touchGui = playerGui and playerGui:FindFirstChild("TouchGui")
    local touchFrame = touchGui and touchGui:FindFirstChild("TouchControlFrame")
    local slideButton = touchFrame and (touchFrame:FindFirstChild("CrouchButton") or touchFrame:FindFirstChild("DynamicSlideButton"))
    if slideButton and slideButton:IsA("GuiButton") then
        mobileSlideConnection = slideButton.Activated:Connect(performHyperflash)
    end
end
addMovementToggle("Hyperflash", "hyperflash", function(enabled)
