        task.spawn(function()
            for _ = 1, 20 do
                if not P.hyperflash or mobileSlideConnection then break end
                bindMobileSlide()
                if mobileSlideConnection then break end
                task.wait(0.25)
            end
        end)
    else
        disconnectMobileSlide()
    end
end)
