local function inputMatchesBind(input, bind)
    if type(bind) ~= "string" or bind == "" or bind == "None" then return false end
    if input.UserInputType == Enum.UserInputType.Keyboard then
        return input.KeyCode.Name == bind
    end
    return input.UserInputType.Name == bind
end

local function nearWall(h, r)
    local character = lp.Character
    if not character then return false end
    local params = RaycastParams.new()
    params.FilterDescendantsInstances = {character, wallPlatform}
    params.FilterType = Enum.RaycastFilterType.Exclude
    local directions = {r.CFrame.LookVector, -r.CFrame.LookVector, r.CFrame.RightVector, -r.CFrame.RightVector}
    for _, direction in ipairs(directions) do
        local flat = Vector3.new(direction.X, 0, direction.Z)
        if flat.Magnitude > 0.05 then
            local hit = Workspace:Raycast(r.Position, flat.Unit * P.wallslideDistance, params)
            if hit and hit.Instance and hit.Instance.CanCollide then return true end
        end
    end
    return false
end

local function tryWallslide(h, r)
    if not h or not r or not P.wallslide or wallPlatform or os.clock() < wallCooldownUntil then return end
    if h.FloorMaterial ~= Enum.Material.Air then return end
    local velocity = r.AssemblyLinearVelocity
    if Vector3.new(velocity.X, 0, velocity.Z).Magnitude < 2 then return end
    if not nearWall(h, r) then return end
    local platform = Instance.new("Part")
    platform.Name = "AspenWallslideSupport"
    platform.Size = Vector3.new(1.5, 0.01, 1.5)
    platform.Transparency = 1
    platform.CanCollide = true
    platform.Anchored = true
    platform.CanTouch = false
    platform.CanQuery = false
    platform.CFrame = CFrame.new(r.Position.X, r.Position.Y - 3.4, r.Position.Z)
    platform.Parent = Workspace
    wallPlatform = platform
    task.delay(P.wallslideDuration, function()
        if wallPlatform == platform then
            removeWallPlatform()
            wallCooldownUntil = os.clock() + 0.3
        end
    end)
end

local lastBhopAt = 0
local airJumpUsed = false
track(UIS.InputBegan:Connect(function(input, processed)
    if processed or UIS:GetFocusedTextBox() then return end
    if P.hyperflash and (inputMatchesBind(input, hyperflashKey:Get())
        or input.KeyCode == Enum.KeyCode.LeftControl or input.KeyCode == Enum.KeyCode.ButtonB) then
        performHyperflash()
    end
    if P.wallslide and inputMatchesBind(input, wallslideKey:Get()) then
        tryWallslide(hum(), root())
    end
end))

track(UIS.TouchTapInWorld:Connect(function()
    if P.wallslide then tryWallslide(hum(), root()) end
end))

track(UIS.JumpRequest:Connect(function()
    if not P.airJump then return end
    local h, r = hum(), root()
    if h and r and h.FloorMaterial == Enum.Material.Air and not airJumpUsed then
        airJumpUsed = true
        local current = r.AssemblyLinearVelocity
        r.AssemblyLinearVelocity = Vector3.new(current.X, math.max(current.Y, P.airJumpVelocity), current.Z)
        h:ChangeState(Enum.HumanoidStateType.Jumping)
    end
end))

track(RunService.PreSimulation:Connect(function()
    if Core.unloaded then return end
    local h, r = hum(), root()
    if not h or not r or h.Health <= 0 then
        wasAirborne = false
        airJumpUsed = false
        removeWallPlatform()
        return
    end

    local airborne = h.FloorMaterial == Enum.Material.Air
    if not airborne then
        airJumpUsed = false
        if wallPlatform then removeWallPlatform() end
    end

    if P.spamSlide and mechanicsController and mechanicsController._is_sliding then
        if mechanicsController._sliding_cooldown and mechanicsController._sliding_cooldown > 0 then
            mechanicsController._sliding_cooldown = 0
        end
        local direction = h.MoveDirection
        if direction.Magnitude < 0.05 then direction = r.CFrame.LookVector end
        direction = Vector3.new(direction.X, 0, direction.Z)
        if direction.Magnitude > 0.05 then
            direction = direction.Unit
            local current = r.AssemblyLinearVelocity
            r.AssemblyLinearVelocity = Vector3.new(direction.X * P.slideVelocity, current.Y, direction.Z * P.slideVelocity)
        end
    end

    if airborne then
        wasAirborne = true
    elseif wasAirborne then
        if not P.bhop then
            wasAirborne = false
        elseif not P.bhopMove or h.MoveDirection.Magnitude > 0.05 then
            local now = os.clock()
            if now - lastBhopAt >= P.bhopDelay then
                lastBhopAt = now
                wasAirborne = false
                h.Jump = true
                h:ChangeState(Enum.HumanoidStateType.Jumping)
                if P.bhopVelocity > 0 then
                    local moveDirection = h.MoveDirection
                    if moveDirection.Magnitude < 0.05 then moveDirection = r.CFrame.LookVector end
                    local direction = Vector3.new(moveDirection.X, 0, moveDirection.Z)
                    if direction.Magnitude > 0.05 then
                        direction = direction.Unit
                        local current = r.AssemblyLinearVelocity
                        r.AssemblyLinearVelocity = Vector3.new(direction.X * P.bhopVelocity, current.Y, direction.Z * P.bhopVelocity)
                    end
                end
            end
        end
    end
end))

Core.restoreMovementHooks = function()
    P.ws, P.jp, P.bhop, P.hyperflash, P.spamSlide, P.wallslide, P.airJump = false, false, false, false, false, false, false
    disconnectMobileSlide()
    removeWallPlatform()
    restoreSpeedJumpHooks()
end

track(lp.CharacterAdded:Connect(function()
    wasAirborne = false
    airJumpUsed = false
    removeWallPlatform()
    task.delay(2, function()
        if P.ws or P.jp or P.spamSlide then ensureHooks() end
        if P.hyperflash then bindMobileSlide() end
    end)
end))
end, function(e) warn("[Aspen] player tab failed: " .. tostring(e)) end)

