    fogColorOn = false, fogC = hx("#C6CCD8"), outAmb = false, outAmbC = hx("#7F7F7F")}
local orig = {}
local function save(k) if orig[k] == nil then orig[k] = Lighting[k] end end
local function restore(...) for _, k in ipairs({...}) do if orig[k] ~= nil then pcall(function() Lighting[k] = orig[k] end) end end end
local fxOff = {}
