    return inst:IsA("ParticleEmitter") or inst:IsA("Trail") or inst:IsA("Beam")
        or inst:IsA("Fire") or inst:IsA("Smoke") or inst:IsA("Sparkles")
end
local function applyWorldVisibility(inst)
    if not inst then return end
    if hideParticles and isParticleEffect(inst) then
        if particleOriginal[inst] == nil then particleOriginal[inst] = inst.Enabled end
        pcall(function() inst.Enabled = false end)
