local function mk(class, props, parent)
local o = Instance.new(class)
for k, v in pairs(props) do o[k] = v end
o.Parent = parent
return o
end
local FONT = Enum.Font.Code
local function shineSeq(c)
local lt = c:Lerp(WHITE, 0.7)
return ColorSequence.new({ColorSequenceKeypoint.new(0, c), ColorSequenceKeypoint.new(0.38, c), ColorSequenceKeypoint.new(0.5, lt), ColorSequenceKeypoint.new(0.62, c), ColorSequenceKeypoint.new(1, c)})
end
