local function newObj(plr)
local o = {hp = 1, ph = math.random() * 6.28, gv = -1, sk = {}, skB = {}, skT = 0, wt = 0, wpnTxt = ""}
o.root = mk("Frame", {Name = plr.Name, BackgroundTransparency = 1, BorderSizePixel = 0, Visible = false}, espGui)
o.glow = mk("ImageLabel", {BackgroundTransparency = 1, Image = "rbxasset://textures/ui/Glow.png", ImageColor3 = WHITE, ImageTransparency = 0.4, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.new(1, 56, 1, 56), ZIndex = 1, Visible = false}, o.root)
o.fill = mk("Frame", {BackgroundColor3 = WHITE, BackgroundTransparency = 0.65, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 1, Visible = false}, o.root)
o.fg = mk("UIGradient", {Enabled = false, Rotation = 90}, o.fill)
o.outer = mk("Frame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 2, Visible = false}, o.root)
mk("UIStroke", {Thickness = 2, Color = Color3.new(0, 0, 0), Transparency = 0.3, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o.outer)
o.box = mk("Frame", {BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 3, Visible = false}, o.root)
o.bs = mk("UIStroke", {Thickness = 1, Color = WHITE, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o.box)
o.cor = {}
for c = 1, 4 do
local ax, ay = (c - 1) % 2, math.floor((c - 1) / 2)
for k = 1, 2 do
local fr = mk("Frame", {BorderSizePixel = 0, BackgroundColor3 = WHITE, AnchorPoint = Vector2.new(ax, ay), Position = UDim2.fromScale(ax, ay), ZIndex = 3, Visible = false}, o.root)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.4, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, fr)
o.cor[#o.cor + 1] = fr
end
end
o.name = mk("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 0, -2), Size = UDim2.fromOffset(200, 13),
Font = FONT, TextSize = 12, TextStrokeTransparency = 1, TextColor3 = WHITE, Text = "", ZIndex = 4, Visible = false}, o.root)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual}, o.name)
o.ng = mk("UIGradient", {}, o.name)
o.dist = mk("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 1, 2), Size = UDim2.fromOffset(120, 11),
Font = FONT, TextSize = 10, TextStrokeTransparency = 1, TextColor3 = WHITE, Text = "", ZIndex = 4, Visible = false}, o.root)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual}, o.dist)
o.dg = mk("UIGradient", {}, o.dist)
o.wpn = mk("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 1, 2), Size = UDim2.fromOffset(160, 11),
Font = FONT, TextSize = 10, TextStrokeTransparency = 1, TextColor3 = WHITE, Text = "", ZIndex = 4, Visible = false}, o.root)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.2, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual}, o.wpn)
o.hpBg = mk("Frame", {BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.25, BorderSizePixel = 0, AnchorPoint = Vector2.new(1, 0),
Position = UDim2.new(0, -4, 0, 0), Size = UDim2.new(0, 4, 1, 0), ZIndex = 3, Visible = false}, o.root)
o.hpFill = mk("Frame", {BackgroundColor3 = GREEN_, BorderSizePixel = 0, AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 1, 1, -1),
Size = UDim2.new(1, -2, 1, -2), ZIndex = 4}, o.hpBg)
o.tr = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 2, Visible = false}, espGui)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.5, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o.tr)
mk("UIGradient", {Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.85), NumberSequenceKeypoint.new(0.6, 0.25), NumberSequenceKeypoint.new(1, 0)})}, o.tr)
o.td = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(7, 7), ZIndex = 3, Visible = false}, espGui)
mk("UIStroke", {Thickness = 1, Color = Color3.new(0, 0, 0), Transparency = 0.3, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, o.td)
