local GREEN, YELLOW, RED = Color3.fromRGB(85, 214, 114), Color3.fromRGB(214, 188, 77), Color3.fromRGB(214, 77, 77)
local function hpColor(f) return f > 0.5 and YELLOW:Lerp(GREEN, (f - 0.5) * 2) or RED:Lerp(YELLOW, f * 2) end
local function hideAll(o) o.root.Visible = false; o.tr.Visible = false; if o.td then o.td.Visible = false end
for _, l in ipairs(o.sk) do l.Visible = false end end
local function dropObj(plr)
local o = objs[plr]; if o then pcall(function() o.root:Destroy(); o.tr:Destroy(); o.td:Destroy(); for _, l in ipairs(o.sk) do l:Destroy() end end); objs[plr] = nil end
local h = chamObjs[plr]; if h then pcall(function() h:Destroy() end); chamObjs[plr] = nil end
end
track(Players.PlayerRemoving:Connect(dropObj))
local tb, tc = 0, 0
local anyCham = false
local FC_, fcTry = nil, 0
local function weaponOf(plr, char)
if not FC_ and os.clock() > fcTry then
fcTry = os.clock() + 2
pcall(function()
local ps = player:FindFirstChild("PlayerScripts")
local cs = ps and ps:FindFirstChild("Controllers")
local m = cs and cs:FindFirstChild("FighterController")
if m then FC_ = require(m) end
end)
end
if type(FC_) == "table" then
local ok, nm = pcall(function()
local f
local objs2 = rawget(FC_, "Objects")
if type(objs2) == "table" then
for _, ob in pairs(objs2) do
if type(ob) == "table" and rawget(ob, "Player") == plr then f = ob; break end
end
end
if not f and type(FC_.GetFighter) == "function" then f = FC_:GetFighter(plr) end
local eq = type(f) == "table" and rawget(f, "EquippedItem")
if type(eq) ~= "table" then return nil end
local n = rawget(eq, "Name")
local info = rawget(eq, "Info")
if type(n) ~= "string" and type(info) == "table" then n = info.Name end
return type(n) == "string" and n or nil
end)
if ok and nm and nm ~= "" then return nm end
end
local tool = char and char:FindFirstChildOfClass("Tool")
return tool and tool.Name or nil
end
local BODY = {Head = true, Torso = true, UpperTorso = true, LowerTorso = true, LeftUpperLeg = true, LeftLowerLeg = true, LeftFoot = true,
RightUpperLeg = true, RightLowerLeg = true, RightFoot = true, LeftUpperArm = true, LeftLowerArm = true, LeftHand = true,
RightUpperArm = true, RightLowerArm = true, RightHand = true, LeftLeg = true, RightLeg = true, LeftArm = true, RightArm = true}
local function buildBones(char)
local bones, seen = {}, {}
local function add(a, b)
if a and b and a ~= b and BODY[a.Name] and BODY[b.Name] then
local k = a.Name .. ">" .. b.Name
if not seen[k] then seen[k] = true; bones[#bones + 1] = {a, b} end
end
end
for _, d in ipairs(char:GetDescendants()) do
if d:IsA("Motor6D") then add(d.Part0, d.Part1)
elseif d:IsA("AnimationConstraint") then
local a0, a1 = d.Attachment0, d.Attachment1
add(a0 and a0.Parent, a1 and a1.Parent)
end
end
return bones
end
local function espStep(dt)
dt = math.min(dt, 0.1)
local cam = Workspace.CurrentCamera
local anyEsp = S.box or S.name or S.hp or S.dist or S.tracer or S.skel or S.weapon
tb = tb + (dt * S.gspeed); tc = tc + (dt * S.cspeed)
if not cam then return end
if not S.cham and anyCham then
for _, h in pairs(chamObjs) do pcall(function() h:Destroy() end) end
table.clear(chamObjs); anyCham = false
end
if not anyEsp and not S.cham then
for _, o in pairs(objs) do hideAll(o) end
return
end
local camPos = cam.CFrame.Position
local visibleRP = RaycastParams.new()
visibleRP.FilterType = Enum.RaycastFilterType.Exclude
visibleRP.FilterDescendantsInstances = {player.Character, cam}
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local o = objs[plr]
local char = plr.Character
local hrp = char and char:FindFirstChild("HumanoidRootPart")
local head = char and char:FindFirstChild("Head")
local hum = char and char:FindFirstChildOfClass("Humanoid")
local ok = hrp and head and hum and hum.Health > 0
if ok and S.team and Core.sameTeam(plr) then ok = false end
local dist = 0
if ok then dist = (camPos - hrp.Position).Magnitude; if dist > S.maxd then ok = false end end
local espVisible = true
if ok and anyEsp and S.visibleOnly then
    local ray = Workspace:Raycast(camPos, head.Position - camPos, visibleRP)
    if ray and not ray.Instance:IsDescendantOf(char) then espVisible = false end
end
local hl = chamObjs[plr]
if ok and S.cham then
if not hl or hl.Parent ~= char then
if hl then pcall(function() hl:Destroy() end) end
hl = Instance.new("Highlight"); hl.Name = "AspenCham"; hl.Adornee = char; hl.Parent = char
chamObjs[plr] = hl; anyCham = true
end
hl.Enabled = true
hl.DepthMode = S.walls and Enum.HighlightDepthMode.AlwaysOnTop or Enum.HighlightDepthMode.Occluded
hl.OutlineColor = S.chamOut; hl.OutlineTransparency = 0
if S.cfill then
local col, ft = S.chamCol, 0.45
if S.cgrad then
local ph = (o and o.ph) or (plr.UserId % 628) / 100
local p
if S.cmode == "Pulse" then p = 0.5 + 0.5 * math.sin(tc * 3); ft = 0.55 - 0.2 * p
elseif S.cmode == "Wave" then p = 0.5 + 0.5 * math.sin(tc * 2 + dist * 0.08 + ph)
else local fr = (tc * 0.35 + ph) % 1; p = 1 - math.abs(2 * fr - 1) end
col = sampleGrad(S.cA, S.cB, S.cS, S.cE, p)
end
hl.FillColor = col; hl.FillTransparency = ft
else hl.FillTransparency = 1 end
elseif hl then hl.Enabled = false end
local shown = false
if ok and anyEsp and espVisible then
if not o then o = newObj(plr); objs[plr] = o end
shown = true
local vp = cam.ViewportSize
local cpos = hrp.Position - Vector3.new(0, 0.25, 0)
local c = cam:WorldToViewportPoint(cpos)
local front = c.Z > 0
local h = 0
if front then
local u = cam:WorldToViewportPoint(cpos + cam.CFrame.UpVector * 2.75)
h = math.min(math.sqrt((u.X - c.X) ^ 2 + (u.Y - c.Y) ^ 2) * 2, 3000)
end
if S.tracer and dist <= (S.tracerMax or 600) then
local org
local oc = S.tracerOrigin
if oc == "Center" then org = Vector2.new(vp.X / 2, vp.Y / 2)
elseif oc == "Top" then org = Vector2.new(vp.X / 2, 0)
elseif oc == "Mouse" then org = game:GetService("UserInputService"):GetMouseLocation()
else org = Vector2.new(vp.X / 2, vp.Y) end
local tx, ty
local inView = false
if front then
tx, ty = c.X, c.Y + h / 2
inView = tx >= 0 and tx <= vp.X and ty >= 0 and ty <= vp.Y
else
local rel = cam.CFrame:PointToObjectSpace(hrp.Position)
local dir = Vector2.new(rel.X, -rel.Y)
if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
dir = dir.Unit
tx, ty = org.X + dir.X * 4000, org.Y + dir.Y * 4000
end

local dx, dy = tx - org.X, ty - org.Y
local tmax = 1
if dx > 0 then tmax = math.min(tmax, (vp.X - org.X) / dx) elseif dx < 0 then tmax = math.min(tmax, (0 - org.X) / dx) end
if dy > 0 then tmax = math.min(tmax, (vp.Y - org.Y) / dy) elseif dy < 0 then tmax = math.min(tmax, (0 - org.Y) / dy) end
tmax = math.max(tmax, 0)
tx, ty = org.X + dx * tmax, org.Y + dy * tmax
dx, dy = tx - org.X, ty - org.Y
local len = math.sqrt(dx * dx + dy * dy)
if len < 2 then
o.tr.Visible = false; o.td.Visible = false
else
o.tr.Size = UDim2.fromOffset(math.floor(len), S.tracerThick)
o.tr.Position = UDim2.fromOffset((org.X + tx) / 2, (org.Y + ty) / 2)
o.tr.Rotation = math.deg(math.atan2(dy, dx))
local tcol = S.tracerCol
local tf = math.clamp(dist / (S.tracerMax or 600), 0, 1)
if S.tracerMode == "Distance" then tcol = S.tracerCol:Lerp(S.tracerFar or Color3.new(1, 1, 1), tf)
elseif S.tracerMode == "Pulse" then tcol = S.tracerCol:Lerp(S.tracerFar or Color3.new(1, 1, 1), (math.sin(os.clock() * 3) + 1) / 2) end
o.tr.BackgroundColor3 = tcol
o.tr.BackgroundTransparency = math.clamp((1 - (S.tracerOpa or 1)) + (S.tracerFade and tf * 0.7 or 0), 0, 1)
o.tr.Visible = true
o.td.Position = UDim2.fromOffset(tx, ty)
o.td.BackgroundColor3 = tcol
o.td.BackgroundTransparency = inView and 0 or 0.5
o.td.Visible = S.tracerDot
end
else
o.tr.Visible = false; o.td.Visible = false
end
if S.skel then
local t0 = os.clock()
if o.skChar ~= char or (#o.skB < 3 and t0 > o.skT) then o.skChar = char; o.skB = buildBones(char); o.skT = t0 + 1 end
local n = 0
for _, b in ipairs(o.skB) do
local pa, pb = b[1], b[2]
if pa.Parent and pb.Parent then
local A, B = cam:WorldToViewportPoint(pa.Position), cam:WorldToViewportPoint(pb.Position)
if A.Z > 0 and B.Z > 0 then
n = n + 1
local ln = o.sk[n]
if not ln then
ln = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 2, Visible = false}, espGui)
o.sk[n] = ln
end
local dx, dy = B.X - A.X, B.Y - A.Y
ln.Size = UDim2.fromOffset(math.floor(math.sqrt(dx * dx + dy * dy) + 0.5), S.skelThick)
ln.Position = UDim2.fromOffset((A.X + B.X) / 2, (A.Y + B.Y) / 2)
ln.Rotation = math.deg(math.atan2(dy, dx))
ln.BackgroundColor3 = S.skelCol
ln.Visible = true
end
end
end
for i = n + 1, #o.sk do o.sk[i].Visible = false end
else
for _, l in ipairs(o.sk) do l.Visible = false end
end
if front and h >= 6 then
local w = h * 0.5
o.root.Position = UDim2.fromOffset(math.floor(c.X - w / 2), math.floor(c.Y - h / 2))
o.root.Size = UDim2.fromOffset(math.floor(w), math.floor(h))
o.root.Visible = true
local full, cor = S.box and S.boxStyle == "Box", S.box and S.boxStyle == "Corner"
o.box.Visible = full; o.outer.Visible = full
if full then o.bs.Color = S.boxCol end
local gl = S.boxGlow == true
o.glow.Visible = gl
if gl then
local gp = S.glowSize or 28
o.glow.Size = UDim2.new(1, gp * 2, 1, gp * 2)
o.glow.ImageColor3 = S.glowCol or S.boxCol
o.glow.ImageTransparency = 1 - math.clamp(S.glowAmt or 0.6, 0, 1) -- strength only changes brightness
end
local L = math.max(5, math.floor(math.min(w, h) * 0.3))
for i, fr in ipairs(o.cor) do
fr.Visible = cor
if cor then
fr.BackgroundColor3 = S.boxCol
fr.Size = (i % 2 == 1) and UDim2.fromOffset(L, 1) or UDim2.fromOffset(1, L)
end
end
local showFill = S.box and S.fill
o.fill.Visible = showFill
if showFill then
if S.grad then
o.fill.BackgroundColor3 = WHITE
o.fg.Enabled = true
if o.gv ~= gver then o.gv = gver; o.fg.Color = gradSeq(S.gA, S.gB, S.gS, S.gE) end
local m = S.gmode
if m == "Pulse" then o.fg.Rotation = 90; o.fg.Offset = Vector2.new(0, 0); o.fill.BackgroundTransparency = math.clamp(S.fillT + 0.12 - 0.3 * (0.5 + 0.5 * math.sin(tb * 3 + o.ph)), 0, 1)
elseif m == "Wave" then o.fg.Rotation = 90; o.fg.Offset = Vector2.new(0, math.sin(tb * 2 + o.ph) * 0.5); o.fill.BackgroundTransparency = math.clamp(S.fillT - 0.1, 0, 1)
else o.fg.Rotation = (tb * 120 + o.ph * 57) % 360; o.fg.Offset = Vector2.new(0, 0); o.fill.BackgroundTransparency = math.clamp(S.fillT - 0.1, 0, 1) end
else
o.fg.Enabled = false; o.fill.BackgroundColor3 = S.boxCol; o.fill.BackgroundTransparency = math.clamp(S.fillT + 0.05, 0, 1)
end
end
local now = os.clock()
o.name.Visible = S.name
if S.name then
o.name.Text = plr.DisplayName
o.ng.Enabled = false; o.name.TextColor3 = S.nameCol
end
o.dist.Visible = S.dist
if S.dist then
o.dist.Text = math.floor(dist) .. "m"
o.dg.Enabled = false; o.dist.TextColor3 = S.distCol
end
o.wpn.Visible = S.weapon
if S.weapon then
if now > o.wt then o.wt = now + 0.25; o.wpnTxt = weaponOf(plr, char) or "" end
o.wpn.Text = o.wpnTxt
o.wpn.Position = UDim2.new(0.5, 0, 1, 2 + (S.dist and 12 or 0))
o.wpn.TextColor3 = S.weaponCol
end
o.hpBg.Visible = S.hp
if S.hp then
local target = math.clamp(hum.Health / math.max(1, hum.MaxHealth), 0, 1)
o.hp = o.hp + ((target - o.hp) * math.min(1, dt * 9))
o.hpFill.Size = UDim2.new(1, -2, o.hp, -2)
o.hpFill.BackgroundColor3 = hpColor(o.hp)
if not o.hpTxt then o.hpTxt = mk("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Size = UDim2.fromOffset(24, 10), Font = FONT, TextSize = 9, TextColor3 = WHITE, TextStrokeTransparency = 0.3, ZIndex = 5}, o.hpBg) end
o.hpTxt.Text = tostring(math.floor(o.hp * 100 + 0.5)); o.hpTxt.Position = UDim2.new(0, -3, math.clamp(1 - o.hp, 0.08, 0.92), 0); o.hpTxt.TextColor3 = hpColor(o.hp)
end
else
o.root.Visible = false
end
end
if o and not shown then hideAll(o) end
end
end
end
