local aimGui = Instance.new("ScreenGui")
aimGui.Name = "AspenAim"; aimGui.ResetOnSpawn = false; aimGui.IgnoreGuiInset = true
aimGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling; aimGui.DisplayOrder = 51
aimGui.Parent = PG
local function holding(char, plr, needle)
for _, c in ipairs(char:GetChildren()) do
if (c:IsA("Tool") or c:IsA("Model")) and string.find(string.lower(c.Name), needle, 1, true) then return true end
end
for _, src in ipairs({char, plr}) do
for _, v in pairs(src:GetAttributes()) do
if type(v) == "string" and string.find(string.lower(v), needle, 1, true) then return true end
end
end
return false
end
local baseFov = 70
local function hasAimState(obj)
    if not obj then return false end
    for _, key in ipairs({"IsAiming", "Aiming", "Scoped", "IsScoped", "ADS", "IsADS"}) do
        local ok, value = pcall(function() return obj:GetAttribute(key) end)
        if ok and value == true then return true end
        local child = obj:FindFirstChild(key)
        if child and child:IsA("BoolValue") and child.Value then return true end
    end
    return false
end
local function isScoped(cam)
    if not cam then return false end
    local f = cam.FieldOfView
    if f > baseFov then baseFov = f end
    local ch = player.Character
    return f < baseFov * 0.94
        or hasAimState(player)
        or hasAimState(ch)
        or UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)
        or UIS:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonL2)
end
do
local SA = {
on = false, act = "Always", chance = 100, part = "Head", point = "Center", radius = 150, follow = false,
fov = true, fovCol = hexc("#FFA0BE"), ffill = false, fgrad = false, fmode = "Pulse", fspeed = 1,
fA = hexc("#FFA0BE"), fB = hexc("#FFD6E6"), fS = 0, fE = 1,
held = false, toggled = false, fillT = 0.6, rs = {}, tScreen = nil, hooked = nil, dead = false,
}
local sver, sgfr = 0, nil
local SFR = {}
local function refreshSFov()
local f, ff, fg = SA.fov, SA.fov and SA.ffill, SA.fov and SA.ffill and SA.fgrad
for _, r in ipairs(SFR.g1 or {}) do setRow(r, f) end
setRow(SFR.fill, f)
setRow(SFR.grad, ff)
for _, r in ipairs(SFR.g3 or {}) do setRow(r, fg) end
end

local sa = addSub(mCombat, "Silent Aim", "Kicia-style silent aim: shot rewrite, manipulation and targeting.")
function SA.active() return false end

SA.hbClass = "Auto"
function SA.small()
local m = SA.hbClass
if m == "Small" then return true elseif m == "Standard" then return false end
local ok, r = pcall(function()
local f = Core.myFighter and Core.myFighter()
local eq = f and rawget(f, "EquippedItem")
if type(eq) ~= "table" then return false end
local nm = rawget(eq, "Name")
local inf = rawget(eq, "Info")
if type(nm) ~= "string" and type(inf) == "table" then nm = inf.Name end
return type(nm) == "string" and nm:lower():find("sniper") ~= nil
end)
return ok and r == true
end
function SA.hb(char, kind)
local small = SA.small()
local nm = (kind == "Head") and (small and "HitboxHeadSmall" or "HitboxHead") or (small and "HitboxBodySmall" or "HitboxBody")
local p = char:FindFirstChild(nm)
if p then return p end
p = char:FindFirstChild((kind == "Head") and (small and "HitboxHead" or "HitboxHeadSmall") or (small and "HitboxBody" or "HitboxBodySmall"))
if p then return p end
if kind == "Head" then return char:FindFirstChild("Head") end
return char:FindFirstChild("UpperTorso") or char:FindFirstChild("Torso")
end
function SA.parts(char, plr, sel)
local head = SA.hb(char, "Head")
local torso = SA.hb(char, "Torso")
local hrp = torso or char:FindFirstChild("HumanoidRootPart")
local list = {}
if sel == "Head" then if head then list[1] = head end
elseif sel == "Torso" then if torso then list[1] = torso end
elseif sel == "HumanoidRootPart" then if hrp then list[1] = hrp end
else
if head then list[#list + 1] = head end
if torso then list[#list + 1] = torso end
if hrp then list[#list + 1] = hrp end
if sel == "Random" and #list > 0 then
local rs = SA.rs
if rs.plr ~= plr or not rs.part or not rs.part.Parent then
rs.plr, rs.part = plr, list[math.random(1, #list)]
end
return {rs.part}
end
end
return list
end
local saRP = RaycastParams.new()
saRP.FilterType = Enum.RaycastFilterType.Exclude
function SA.visible(cam, part, char)
local ign = {player.Character, char, cam}
local from = cam.CFrame.Position
local dir = part.Position - from
for _ = 1, 16 do
saRP.FilterDescendantsInstances = ign
local r = Workspace:Raycast(from, dir, saRP)
if not r then return true end
local h = r.Instance
if h:IsDescendantOf(char) then return true end
if h.CanCollide == false or h.CanQuery == false or h.Transparency >= 0.95 or h:HasTag("OutOfBoundsPart") then
ign[#ign + 1] = h
else
return false
end
end
return false
end
local function cfEnc(cf)
local rx, ry, rz = cf:ToOrientation()
return {["\0"] = cf.X, ["\1"] = cf.Y, ["\2"] = cf.Z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz}
end
local function cfDec(t)
if type(t) ~= "table" then return nil end
local a, b, c, d, e, f = t["\0"], t["\1"], t["\2"], t["\3"], t["\4"], t["\5"]
if type(a) ~= "number" or type(b) ~= "number" or type(c) ~= "number" or type(d) ~= "number" or type(e) ~= "number" or type(f) ~= "number" then return nil end
return CFrame.new(a, b, c) * CFrame.fromOrientation(d, e, f)
end
local hitRP = RaycastParams.new()
hitRP.FilterType = Enum.RaycastFilterType.Include
local function hitLocal(from, part, tp)
hitRP.FilterDescendantsInstances = {part}
local r = Workspace:Raycast(from, tp - from, hitRP)
if not r then return nil end
local l = part.CFrame:PointToObjectSpace(r.Position)
if l == Vector3.zero then return nil end
return l
end
SA.mm = {back = false, range = false, rangeV = 10}
function SA.install()
    if type(SA.hook) == "function" then return SA.hook() end
    return false
end
gui.Destroying:Connect(function() SA.dead = true; SA.on = false end)



do
-- ===================================================================================================
-- Aimbot + Silent Aim, rebuilt from Kiciahook's logic:
--   * shared target engine (filters, allowed hitboxes, closest-to-crosshair / weighted-random hitbox, centre / closest-point aim point)
--   * reaction + switch delay acquisition, activation modes + rules, target lock (toggle / auto / manual)
--   * Aimbot = camera aim using Kiciahook's aim types (Lock / Linear / Humanized / Spring) + smooth release after a kill
--   * Silent Aim = rewrites the game's own StartShooting packet (origin, look, hit part, local hit offset), optional "Manipulate"
--     (finds a shot origin up to 9.9 studs away from which the target is visible, same search pattern Kicia uses)
-- ===================================================================================================
local TAU = math.pi * 2
local AB = {on = false, mode = "Hold", held = false, toggled = false, showName = true, aimType = "Linear", spd = {Linear = 0.5, Humanized = 0.5, Spring = 0.5}, svx = 0, svy = 0,
    radius = 150, fov = true, fovCol = hexc("#FFA0BE"), fovThick = 1.5, ffill = 0}
local TL = {on = false, mode = "Toggle Lock", plr = nil}

local function baseCfg(c)
    c.filters = {Visible = true, Vulnerable = true, NotDeflecting = true, NotShielded = true, WithinFov = true}
    c.rules = {NotReloading = true, ScopedIn = false}
    c.hitboxes = {Head = true, Body = true}
    c.hsel, c.headPct, c.ptype, c.surfRed, c.keepDepth = "Closest to Crosshair", 50, "Center", 0, false
    c.react, c.swDelay = 0, 0
    c.acq = {cur = nil, pend = nil, since = 0}
    return c
end
baseCfg(AB)
baseCfg(SA)
SA.mode, SA.chance = "Always", 100
AB.team, SA.team = true, true
SA.manip, SA.manipMode, SA.manipRange, SA.manipInd = false, "On Best Target", 9.9, true
SA.fovThick = 1.5

-- ---------------------------------------------------------------- helpers
local function toSet(arr)
    local s = {}
    for _, v in ipairs(arr or {}) do s[v] = true end
    return s
end
local function kmatch(obj, i)
    local b = obj and obj.Get and obj.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b
        or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
local function keyDown(obj)
    local b = obj and obj.Get and obj.Get()
    if not b or b == "None" then return false end
    if b == "MouseButton2" or b == "MouseButton3" then return UIS:IsMouseButtonPressed(Enum.UserInputType[b]) end
    local ok, r = pcall(function() return UIS:IsKeyDown(Enum.KeyCode[b]) end)
    return ok and r == true
end
local function actOn(c)
    if not c.on then return false end
    if c.mode == "Always" then return true end
    if c.mode == "Hold" then return c.held or keyDown(c.key) end
    return c.toggled
end
local function curGun()
    local f = Core.myFighter and Core.myFighter()
    local eq = f and rawget(f, "EquippedItem")
    if type(eq) ~= "table" then return nil end
    local info = rawget(eq, "Info")
    if type(info) ~= "table" or info.Type == "Melee" or info.Type == "Throwable" then return nil end
    return eq
end
local function blocked(c, eq, cam)
    if c.rules.NotReloading then
        local ok, r = pcall(function() return type(eq.IsReloading) == "function" and eq:IsReloading() end)
        if ok and r == true then return true end
    end
    if c.rules.ScopedIn and not isScoped(cam) then return true end
    return false
end
local function deflecting(ch)
    local k = ch:FindFirstChild("Katana")
    local d = k and k:FindFirstChild("Deflecting")
    return d ~= nil and d.Value == true
end
local function riotBlocks(root, from)
    local ch = root.Parent
    local sh = ch and (ch:FindFirstChild("Riot Shield") or ch:FindFirstChild("Shield"))
    if not sh then return false end
    return root.CFrame.LookVector:Dot((from - root.Position).Unit) < -0.2
end
local visRP = RaycastParams.new()
visRP.FilterType = Enum.RaycastFilterType.Exclude
local function visFrom(from, part, char, cam)
    local ign = {player.Character, char, cam}
    local dir = part.Position - from
    for _ = 1, 16 do
        visRP.FilterDescendantsInstances = ign
        local r = Workspace:Raycast(from, dir, visRP)
        if not r then return true end
        local h = r.Instance
        if h:IsDescendantOf(char) then return true end
        if h.CanCollide == false or h.CanQuery == false or h.Transparency >= 0.95 or h:HasTag("OutOfBoundsPart") then
            ign[#ign + 1] = h
        else
            return false
        end
    end
    return false
end
-- Kiciahook's manipulation search: the origin itself, a point pushed towards the target, then a ring of points around the line of fire
local function manipOrigin(from, part, char, cam, range)
    if visFrom(from, part, char, cam) then return from end
    local dir = part.Position - from
    local dist = dir.Magnitude
    if dist < 0.1 then return nil end
    local u = dir / dist
    local reach = math.min(range, dist - part.Size.Magnitude / 2)
    local pushed = false
    if reach > 0 then
        local p = from + u * reach
        pushed = true
        if visFrom(p, part, char, cam) then return p end
    end
    local up = math.abs(u:Dot(Vector3.yAxis)) > 0.99 and Vector3.xAxis or Vector3.yAxis
    local a = u:Cross(up).Unit
    local b = a:Cross(u).Unit
    local n = pushed and 6 or 7
    for k = 0, n - 1 do
        local th = TAU * k / n
        local p = from + (a * math.cos(th) + b * math.sin(th)) * range
        if visFrom(p, part, char, cam) then return p end
    end
    return nil
end

local HB = {Head = function(ch) return SA.hb(ch, "Head") end, Body = function(ch) return SA.hb(ch, "Torso") end}
local function aimPoint(c, cam, part)
    if c.ptype ~= "Closest Point" then return part.Position end
    local vp = cam.ViewportSize / 2
    local ray = cam:ViewportPointToRay(vp.X, vp.Y)
    local cf = part.CFrame
    local half = part.Size * 0.5 * (1 - c.surfRed / 100)
    local t = math.max((cf.Position - ray.Origin):Dot(ray.Direction), 0)
    local function clampL(l) return Vector3.new(math.clamp(l.X, -half.X, half.X), math.clamp(l.Y, -half.Y, half.Y), math.clamp(l.Z, -half.Z, half.Z)) end
    local p = cf:PointToWorldSpace(clampL(cf:PointToObjectSpace(ray.Origin + ray.Direction * t)))
    if c.keepDepth then
        local d = (cf.Position - ray.Origin):Dot(ray.Direction)
        local pd = (p - ray.Origin):Dot(ray.Direction)
        p = cf:PointToWorldSpace(clampL(cf:PointToObjectSpace(p + ray.Direction * (d - pd))))
    end
    return p
end

-- ---------------------------------------------------------------- target engine
local function candidates(c, cam, lockPlr, allowManip)
    local list = {}
    local center = cam.ViewportSize / 2
    local camPos = cam.CFrame.Position
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and (not lockPlr or plr == lockPlr) and not (c.team ~= false and Core.sameTeam(plr)) and sameMatch(plr) then
            local ch = plr.Character
            local hum = ch and ch:FindFirstChildOfClass("Humanoid")
            local root = ch and ch:FindFirstChild("HumanoidRootPart")
            if hum and root and hum.Health > 0 then
                local f = c.filters
                local ok = true
                if f.Vulnerable and shielded(plr, ch) then ok = false end
                if ok and f.NotDeflecting and deflecting(ch) then ok = false end
                if ok and f.NotShielded and riotBlocks(root, camPos) then ok = false end
                if ok then
                    for name, on in pairs(c.hitboxes) do
                        local part = on and HB[name] and HB[name](ch)
                        if part then
                            local pt = aimPoint(c, cam, part)
                            local sp = cam:WorldToViewportPoint(pt)
                            if sp.Z > 0 then
                                local scr = Vector2.new(sp.X, sp.Y)
                                local d = (scr - center).Magnitude
                                if lockPlr or not f.WithinFov or d <= c.radius then
                                    local entry = {plr = plr, char = ch, part = part, kind = name, point = pt, dist = d, screen = scr}
                                    if not f.Visible or visFrom(camPos, part, ch, cam) then
                                        list[#list + 1] = entry
                                    elseif allowManip then
                                        entry.needManip = true
                                        list[#list + 1] = entry
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return list
end
local function selectBest(c, cam, lockPlr)
    local allowManip = c.manip == true and c.filters.Visible
    local list = candidates(c, cam, lockPlr, allowManip)
    if #list == 0 then return nil end
    local camPos = cam.CFrame.Position
    if allowManip then
        -- On Best Target: only the single best candidate may be manipulated, the rest must be visible. On All Targets: any of them.
        local bestAny
        for _, e in ipairs(list) do if not bestAny or e.dist < bestAny.dist then bestAny = e end end
        local keep = {}
        for _, e in ipairs(list) do
            if not e.needManip then
                keep[#keep + 1] = e
            elseif c.manipMode == "On All Targets" or e == bestAny then
                local o = manipOrigin(camPos, e.part, e.char, cam, c.manipRange)
                if o then e.org = o; keep[#keep + 1] = e end
            end
        end
        list = keep
        if #list == 0 then return nil end
    end
    local bestP, bestD
    for _, e in ipairs(list) do
        if not bestD or e.dist < bestD then bestD, bestP = e.dist, e.plr end
    end
    local curP = c.acq and c.acq.cur
    if curP and curP ~= bestP then
        for _, e in ipairs(list) do
            if e.plr == curP and e.dist <= bestD * 1.45 + 6 then bestP = curP; break end
        end
    end
    local pick
    if c.hsel == "Weighted Random" then
        local now = os.clock()
        local roll = c.roll
        if not roll or roll.plr ~= bestP or now > roll.t then
            roll = {plr = bestP, t = now + 0.35, head = math.random() * 100 < c.headPct}
            c.roll = roll
        end
        local want = roll.head and "Head" or "Body"
        for _, e in ipairs(list) do if e.plr == bestP and e.kind == want then pick = e; break end end
    end
    if not pick then
        for _, e in ipairs(list) do
            if e.plr == bestP and (not pick or e.dist < pick.dist) then pick = e end
        end
    end
    if pick then
        local tn = os.clock()
        if c.lastPlr == pick.plr and c.lastKind and pick.kind ~= c.lastKind and tn - (c.lastKT or 0) < 0.4 then
            for _, e in ipairs(list) do if e.plr == pick.plr and e.kind == c.lastKind then pick = e; break end end
        end
        if c.lastPlr ~= pick.plr or c.lastKind ~= pick.kind then c.lastPlr, c.lastKind, c.lastKT = pick.plr, pick.kind, tn end
    end
    return pick
end
local function acquire(c, now, plr)
    local a = c.acq
    if a.cur == plr then a.pend = nil; return true end
    local need = (a.cur == nil) and c.react or c.swDelay
    if a.pend ~= plr then a.pend, a.since = plr, now end
    if now - a.since >= need then a.cur, a.pend = plr, nil; return true end
    return false
end
local function resetAcq(c) c.acq.cur, c.acq.pend = nil, nil end

-- ---------------------------------------------------------------- input
track(UIS.InputBegan:Connect(function(i, gp)
    if gp and i.UserInputType ~= Enum.UserInputType.MouseButton2 and i.UserInputType ~= Enum.UserInputType.MouseButton3 then return end
    if kmatch(AB.key, i) then AB.held = true; AB.toggled = not AB.toggled end
    if kmatch(SA.key, i) then SA.held = true; SA.toggled = not SA.toggled end
    if kmatch(TL.key, i) and TL.on then
        if TL.plr then TL.plr = nil
        elseif AB.pick then TL.plr = AB.pick.plr end
    end
end))
track(UIS.InputEnded:Connect(function(i)
    if kmatch(AB.key, i) then AB.held = false end
    if kmatch(SA.key, i) then SA.held = false end
end))

-- ---------------------------------------------------------------- FOV circles
local function mkCircle(name)
    local f = Instance.new("Frame")
    f.Name = name; f.AnchorPoint = Vector2.new(0.5, 0.5); f.BackgroundColor3 = Color3.new(1, 1, 1); f.BackgroundTransparency = 1
    f.BorderSizePixel = 0; f.Visible = false; f.ZIndex = 4
    local cr = Instance.new("UICorner"); cr.CornerRadius = UDim.new(1, 0); cr.Parent = f
    local s = Instance.new("UIStroke"); s.Thickness = 1.5; s.Color = Color3.new(1, 1, 1); s.Parent = f
    local g = Instance.new("UIGradient"); g.Name = "NoTheme"; g.Enabled = false; g.Parent = f
    f.Parent = aimGui
    return f, s, g
end
AB.cf, AB.cs = mkCircle("AimbotFov")
SA.cf, SA.cs, SA.cg = mkCircle("SilentFov")
function AB.style()
    AB.cs.Color = AB.fovCol; AB.cs.Thickness = AB.fovThick
    AB.cf.BackgroundColor3 = AB.fovCol; AB.cf.BackgroundTransparency = 1 - AB.ffill
end
function SA.style()
    SA.cs.Color = SA.fovCol; SA.cs.Thickness = SA.fovThick or 1.5
    SA.cf.BackgroundTransparency = SA.ffill and (SA.fillT or 0.6) or 1
    if SA.ffill and SA.fgrad then
        SA.cf.BackgroundColor3 = Color3.new(1, 1, 1); SA.cg.Enabled = true; SA.cg.Color = gradSeq(SA.fA, SA.fB, SA.fS, SA.fE)
    else SA.cg.Enabled = false; SA.cf.BackgroundColor3 = SA.fovCol end
end
local manipLbl = Instance.new("TextLabel")
manipLbl.Name = "Manipulated"; manipLbl.BackgroundTransparency = 1; manipLbl.AnchorPoint = Vector2.new(0.5, 0)
manipLbl.Position = UDim2.new(0.5, 0, 0.5, 34); manipLbl.Size = UDim2.fromOffset(160, 18); manipLbl.Text = "Manipulated"
manipLbl.Font = Enum.Font.Code; manipLbl.TextSize = 14; manipLbl.TextColor3 = Color3.new(1, 1, 1); manipLbl.Visible = false
manipLbl.ZIndex = 5; manipLbl.Parent = aimGui
local function drawFov(cam, dt)
    local vp = cam.ViewportSize
    local show = AB.on and AB.fov
    AB.cf.Visible = show
    if show then AB.cf.Position = UDim2.fromOffset(vp.X / 2, vp.Y / 2); AB.cf.Size = UDim2.fromOffset(AB.radius * 2, AB.radius * 2) end
    local sshow = SA.on and SA.fov
    SA.cf.Visible = sshow
    if sshow then
        local goal = (SA.follow and SA.tScreen) or Vector2.new(vp.X / 2, vp.Y / 2)
        SA.fp = SA.fp and SA.fp:Lerp(goal, math.clamp(dt * (SA.follow and SA.tScreen and 18 or 40), 0, 1)) or goal
        SA.cf.Position = UDim2.fromOffset(SA.fp.X, SA.fp.Y); SA.cf.Size = UDim2.fromOffset(SA.radius * 2, SA.radius * 2)
        if SA.ffill and SA.fgrad then
            local t, sp = os.clock(), SA.fspeed or 1
            if SA.fmode == "Spin" then SA.cg.Rotation = (t * 60 * sp) % 360
            elseif SA.fmode == "Wave" then SA.cg.Offset = Vector2.new(((t * 0.3 * sp) % 2) - 1, 0)
            else SA.cg.Offset = Vector2.new(math.sin(t * 2 * sp) * 0.3, 0) end
        end
    end
    manipLbl.Visible = SA.on and SA.manip and SA.manipInd and SA.cur ~= nil and SA.cur.org ~= nil
end

-- ---------------------------------------------------------------- Aimbot (Kicia aim types: Lock / Linear / Humanized / Spring)
-- Port of Kiciahook's aim applier. Every type turns the screen-space gap between the aim origin (where the camera Rotation
-- points) and the target point into a delta, and the delta becomes a camera Rotation change using Kicia's radians-per-pixel
-- (rad(FOV) / ViewportSize.Y). On top of that: a target that dies / drops out is released smoothly (momentum glide-out),
-- and after a kill there is a short pause + ease-in before the next target is taken, so the camera never snaps away.
local GLIDE_TAU, KILL_PAUSE, EASE_IN, GLIDE_CAP = 0.10, 0.30, 0.45, 12

function AB.resetMotion()
    AB.svx, AB.svy, AB.glide = 0, 0, nil
end
function AB.reset()
    resetAcq(AB); AB.pick = nil; AB.curPlr = nil; AB.killT = nil; AB.resetMotion()
end
-- the game's CameraController rebuilds the camera from its own Rotation (pitch, yaw) every frame, so writing cam.CFrame fights it and jitters.
-- Like Kicia, we read / write that Rotation directly and the game turns it into the camera itself.
local CCtl = {}
local function ccInit()
    if CCtl.ok then return true end
    if os.clock() - (CCtl.at or -10) < 5 then return false end
    CCtl.at = os.clock()
    pcall(function()
        local ctrls = player.PlayerScripts:FindFirstChild("Controllers")
        local node = ctrls and ctrls:FindFirstChild("CameraController")
        local m = node and require(node)
        local mt = m and getmetatable(m)
        local idx = type(mt) == "table" and rawget(mt, "__index")
        local set = type(idx) == "table" and rawget(idx, "SetRotation")
        if type(set) == "function" and typeof(rawget(m, "Rotation")) == "Vector2" then CCtl.m, CCtl.set, CCtl.ok = m, set, true end
    end)
    return CCtl.ok == true
end
-- fallback only (CameraController not reachable): keeps the viewmodel glued to the camera when we have to write cam.CFrame
local function syncViewModel(delta, cam)
    local models = {}
    pcall(function()
        local eq = curGun()
        local vm = eq and rawget(eq, "ViewModel")
        local m = vm and rawget(vm, "Model")
        if typeof(m) == "Instance" and m:IsA("Model") then models[1] = m end
    end)
    if #models == 0 then
        local root = cam:FindFirstChild("ViewModels") or Workspace:FindFirstChild("ViewModels") or cam:FindFirstChild("ViewModel")
        if root then
            if root:IsA("Model") then models[1] = root
            else for _, c in ipairs(root:GetChildren()) do if c:IsA("Model") then models[#models + 1] = c end end end
        end
    end
    for _, m in ipairs(models) do pcall(function() m:PivotTo(delta * m:GetPivot()) end) end
end
local function rotGet(cam, forceCF)
    if not forceCF and ccInit() then
        local ok, r = pcall(rawget, CCtl.m, "Rotation")
        if ok and typeof(r) == "Vector2" then return r end
    end
    local rx, ry = cam.CFrame:ToOrientation()
    return Vector2.new(rx, ry)
end
local function rotSet(cam, v, forceCF)
    if CCtl.ok and not forceCF then
        local ok = pcall(function() coroutine.wrap(CCtl.set)(CCtl.m, v) end)
        if ok then return end
    end
    local old = cam.CFrame
    local new = CFrame.new(old.Position) * CFrame.fromOrientation(v.X, v.Y, 0)
    cam.CFrame = new
    syncViewModel(new * old:Inverse(), cam)
end
-- Kicia: screen point the camera Rotation currently points at
local function aimOrigin(cam, rot)
    local look = CFrame.fromOrientation(rot.X, rot.Y, 0).LookVector
    local v = cam:WorldToViewportPoint(cam.CFrame.Position + look * 1000)
    return Vector2.new(v.X, v.Y)
end
local function toScreen(cam, wp)
    local v = cam:WorldToViewportPoint(wp)
    local p = Vector2.new(v.X, v.Y)
    if v.Z < 0 then -- behind the camera: the projection is mirrored, so push the point out the opposite way
        local c = cam.ViewportSize / 2
        local d = c - p
        if d.Magnitude < 1 then d = Vector2.new(1, 0) end
        return c + d.Unit * 4000
    end
    return p
end
-- Kicia's Spring type: critically damped spring (SmoothDamp)
local function smoothDamp(cur, goal, vel, smooth, dt)
    local w = 2 / smooth
    local x = w * dt
    local e = 1 / (1 + x + 0.48 * x * x + 0.235 * x * x * x)
    local ch = cur - goal
    local tmp = (vel + w * ch) * dt
    local nv = (vel - w * tmp) * e
    local out = goal + (ch + tmp) * e
    if (goal - cur > 0) == (out > goal) then out, nv = goal, 0 end
    return out, nv
end
-- Kicia's four aim types. Lock = full gap in one go, Linear = constant pixel step toward the target (speed * 10 px / frame),
-- Humanized = Linear with a human feel (ease-in on a new target, slows near the target, tiny sideways wobble), Spring = SmoothDamp.
local function aimDelta(o, tp, dt)
    local t = AB.aimType
    local speed = math.clamp(AB.spd[t] or 0.5, 0.01, 1)
    if t == "Lock" then
        AB.svx, AB.svy = 0, 0
        return tp - o
    elseif t == "Spring" then
        local T = math.max(dt * 2, 14 / speed / 1000)
        local nx, vx = smoothDamp(o.X, tp.X, AB.svx or 0, T, dt)
        local ny, vy = smoothDamp(o.Y, tp.Y, AB.svy or 0, T, dt)
        AB.svx, AB.svy = vx, vy
        return Vector2.new(nx, ny) - o
    end
    AB.svx, AB.svy = 0, 0
    local gap = tp - o
    local m = gap.Magnitude
    if m < 1 then return nil end
    local u = gap.Unit
    -- frame-rate independent exponential ease: big gaps close fast, the last pixels glide in (no stepping / overshoot)
    local k = 4 + speed * 38
    local f = 1 - math.exp(-k * math.min(dt, 0.05))
    if t == "Humanized" then
        local now = os.clock()
        local engage = math.clamp((now - (AB.engT or now)) / 0.35, 0, 1)
        local wob = Vector2.new(-u.Y, u.X) * (math.noise(now * 1.3, 5.1) * math.min(m * 0.04, 1.5))
        return gap * (f * (0.4 + 0.6 * engage)) + wob * f
    end
    local minStep = speed * 10 * math.min(dt * 60, 3) * 0.25
    return u * math.min(m, math.max(m * f, minStep))
end
local function moveBy(cam, rot, d, forceCF)
    local k = math.rad(cam.FieldOfView) / cam.ViewportSize.Y
    rotSet(cam, Vector2.new(rot.X - d.Y * k, rot.Y - d.X * k), forceCF)
end
local function targetDead(plr)
    if not plr or not plr.Parent then return true end
    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
    return not hum or hum.Health <= 0
end
-- smooth release: leftover motion fades out instead of the aim stopping dead / snapping elsewhere
local function glideOut(cam, dt)
    local g = AB.glide
    if not g then return end
    g = g * math.exp(-dt / GLIDE_TAU)
    if g.Magnitude < 0.15 then AB.glide = nil; return end
    if g.Magnitude > GLIDE_CAP then g = g.Unit * GLIDE_CAP end
    AB.glide = g
    moveBy(cam, rotGet(cam), g)
end
function AB.step(dt)
    if AB.gone then return end
    local cam = Workspace.CurrentCamera
    if not cam then return end
    drawFov(cam, dt)
    dt = math.clamp(dt, 1 / 240, 0.1)
    if not actOn(AB) then AB.reset(); if TL.plr and not AB.on then TL.plr = nil end return end
    local eq = curGun()
    if not eq or blocked(AB, eq, cam) then AB.reset(); return end
    if TL.plr then
        local ch = TL.plr.Character
        local hum = ch and ch:FindFirstChildOfClass("Humanoid")
        if not (hum and hum.Health > 0) or not TL.plr.Parent then TL.plr = nil end
    end
    local now = os.clock()
    if AB.killT and now - AB.killT < KILL_PAUSE then glideOut(cam, dt); return end -- just killed someone: don't grab the next target yet
    local lockPlr = TL.on and TL.plr or nil
    local pick = selectBest(AB, cam, lockPlr)
    if AB.curPlr and (not pick or pick.plr ~= AB.curPlr) and targetDead(AB.curPlr) then
        AB.killT, AB.curPlr, AB.pick = now, nil, nil
        resetAcq(AB); AB.svx, AB.svy = 0, 0
        glideOut(cam, dt)
        return
    end
    if not pick then
        AB.curPlr, AB.pick = nil, nil
        resetAcq(AB); AB.svx, AB.svy = 0, 0
        glideOut(cam, dt)
        return
    end
    AB.pick = pick
    do
        local rootP = pick.char:FindFirstChild("HumanoidRootPart")
        if rootP then
            local want = pick.point - rootP.Position
            if AB.offPlr ~= pick.plr or not AB.curOff then AB.curOff = want; AB.offPlr = pick.plr
            else AB.curOff = AB.curOff:Lerp(want, 1 - math.exp(-16 * dt)) end
            pick = setmetatable({point = rootP.Position + AB.curOff}, {__index = pick})
        end
    end
    if TL.on then
        if TL.mode == "Auto Lock" and not TL.plr then TL.plr = pick.plr end
        if TL.mode == "Manual Only" and not TL.plr then return end
    end
    if not acquire(AB, now, pick.plr) then return end
    if AB.curPlr ~= pick.plr then AB.engT = now end
    AB.curPlr = pick.plr
    local scoped = isScoped(cam)
    local ramp = 1
    if AB.killT then -- first target after a kill: ease the aim in instead of snapping onto it
        local x = math.clamp((now - AB.killT - KILL_PAUSE) / EASE_IN, 0, 1)
        ramp = x * x * (3 - 2 * x)
        if x >= 1 then AB.killT = nil end
    end
    if scoped then
        -- scoped in the game ignores Rotation writes, so aim the way sleepy does: lerp the camera CFrame toward a CFrame facing the target
        local old = cam.CFrame
        local alpha = 1
        if AB.aimType ~= "Lock" then
            local sp = math.clamp(AB.spd[AB.aimType] or 0.5, 0.01, 1)
            local a60 = math.clamp(0.67 * sp * sp, 0.01, 1) * ramp
            if AB.aimType == "Humanized" then
                local engage = math.clamp((now - (AB.engT or now)) / 0.35, 0, 1)
                a60 = a60 * (0.35 + 0.65 * engage)
            end
            alpha = 1 - (1 - a60) ^ (dt * 60)
        else
            alpha = ramp
        end
        local new = old:Lerp(CFrame.new(old.Position, pick.point), alpha)
        cam.CFrame = new
        syncViewModel(new * old:Inverse(), cam)
        AB.glide = nil
        return
    end
    local rot = rotGet(cam)
    local d = aimDelta(aimOrigin(cam, rot), toScreen(cam, pick.point), dt)
    if d then
        d = d * ramp
        moveBy(cam, rot, d)
    end
    AB.glide = (AB.glide or Vector2.zero):Lerp(d or Vector2.zero, 0.4)
end
-- "targeting: playername" text under the crosshair (same style as the ragebot status text)
do
local tgtLbl = Instance.new("TextLabel")
tgtLbl.Name = "AimbotTarget"; tgtLbl.BackgroundTransparency = 1; tgtLbl.AnchorPoint = Vector2.new(0.5, 0)
tgtLbl.Position = UDim2.new(0.5, 0, 0.5, 52); tgtLbl.Size = UDim2.fromOffset(300, 20); tgtLbl.Text = ""
tgtLbl.Font = Enum.Font.Code; pcall(function() if Core and Core.Body then tgtLbl.FontFace = Core.Body end end)
tgtLbl.TextSize = 14; tgtLbl.TextColor3 = Color3.new(1, 1, 1); tgtLbl.TextStrokeColor3 = Color3.new(0, 0, 0)
tgtLbl.TextStrokeTransparency = 0.25; tgtLbl.Visible = false; tgtLbl.ZIndex = 5; tgtLbl.Parent = aimGui
AB.tgtLbl = tgtLbl
local function updateTargetLbl()
    local plr = AB.curPlr
    local show = AB.on and AB.showName and plr ~= nil and AB.pick ~= nil and not AB.gone and actOn(AB)
    tgtLbl.Visible = show == true
    if show then
        tgtLbl.Text = "targeting: " .. plr.Name
        tgtLbl.TextColor3 = AB.fovCol:Lerp(Color3.new(1, 1, 1), 0.55)
    end
end
pcall(function() RunService:UnbindFromRenderStep("AspenAimbot") end)
RunService:BindToRenderStep("AspenAimbot", Enum.RenderPriority.Camera.Value + 1, function(dt)
    local ok, e = pcall(AB.step, dt)
    if not ok and e ~= AB.lastErr then AB.lastErr = e; notify("Aimbot error", tostring(e):sub(1, 140), 8, "danger") end
    pcall(updateTargetLbl)
end)
end

-- ---------------------------------------------------------------- Silent Aim (packet rewrite)
function SA.active() return SA.on and actOn(SA) end
local function silentStep()
    if SA.dead then return end
    if SA.on and SA.hooked == nil and os.clock() - (SA.hookTry or 0) > 1 then SA.hookTry = os.clock(); SA.hook() end
    if not SA.active() then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    local cam = Workspace.CurrentCamera
    local eq = cam and curGun()
    if not eq or blocked(SA, eq, cam) then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    local pick = selectBest(SA, cam, nil)
    if not pick then SA.cur = nil; SA.tScreen = nil; resetAcq(SA); return end
    SA.tScreen = pick.screen
    if not acquire(SA, os.clock(), pick.plr) then return end
    SA.cur = pick
end
-- called from the namecall hook with the packet table the game is about to send
function SA.onShot(objId, pkt)
    local pick = SA.cur
    if not pick or not SA.active() then return end
    do -- re-evaluate right now so the shot uses this frame's position, not the last step's
        local cam0 = Workspace.CurrentCamera
        local okF, fresh = pcall(function() return cam0 and selectBest(SA, cam0, nil) end)
        if okF and fresh and fresh.part and fresh.part.Parent then
            if not pick.plr or fresh.plr == pick.plr or not pick.part or not pick.part.Parent or not pick.char.Parent then pick = fresh end
        elseif okF and not fresh then return end
    end
    local sh = pkt["\1"]
    if type(sh) ~= "table" then return end
    if (SA.chance or 100) < 100 and math.random() * 100 > SA.chance then return end
    local part = pick.part
    if not part or not part.Parent or not pick.char.Parent then return end
    local cf0, cf1 = cfDec(sh["\0"]), cfDec(sh["\1"])
    if not cf0 or not cf1 then return end
    local cam = Workspace.CurrentCamera
    local point = aimPoint(SA, cam, part)
    local o0, o1 = cf0.Position, cf1.Position
    if pick.org then o0, o1 = pick.org, pick.org end
    local lp = hitLocal(o0, part, point) or part.CFrame:PointToObjectSpace(point)
    if lp == Vector3.zero then return end
    sh["\0"] = cfEnc(CFrame.lookAt(o0, point))
    sh["\1"] = cfEnc(CFrame.lookAt(o1, point))
    sh["\2"] = part
    sh["\3"] = cfEnc(CFrame.new(lp))
end
-- The game fires shots through a cached FireServer, so a __namecall hook never sees them. Kicia swaps the ReplicatedStorage upvalue
-- inside ClientItem.Input for a stand-in whose UseItem:FireServer we control; we do the same, with __namecall kept as a backup.
local seenPkt = setmetatable({}, {__mode = "k"})
local function handlePacket(objId, pkt)
    if type(pkt) ~= "table" or seenPkt[pkt] then return end
    seenPkt[pkt] = true
    if SA.on and not Core.rageFiring then pcall(SA.onShot, objId, pkt) end
end
local function installInputHook(rem, en)
    local RSv = game:GetService("ReplicatedStorage")
    local ok, installed = pcall(function()
        local ci = require(player.PlayerScripts.Modules.ClientReplicatedClasses.ClientFighter.ClientItem)
        local input = rawget(ci, "Input")
        if type(input) ~= "function" or not debug or not debug.getupvalues then return false end
        local fire = Instance.new("RemoteEvent").FireServer
        if type(clonefunction) == "function" then fire = clonefunction(fire) end
        local realRem = RSv:FindFirstChild("Remotes")
        local realRep = realRem and realRem:FindFirstChild("Replication")
        local realFighter = realRep and realRep:FindFirstChild("Fighter")
        local useItem = {FireServer = function(_, objId, enc, args, ...)
            if type(SA.mods) == "function" then pcall(SA.mods, objId, enc, args) end
            if enc == en then
                handlePacket(objId, args)
                if Core.onShotSent then pcall(Core.onShotSent) end
            end
            return fire(rem, objId, enc, args, ...)
        end}
        local function wrap(real, over) return setmetatable(over, {__index = function(_, key) return real and real[key] end}) end
        local fake = wrap(RSv, {Remotes = wrap(realRem, {Replication = wrap(realRep, {Fighter = wrap(realFighter, {UseItem = useItem})})})})
        for _, up in pairs(debug.getupvalues(input)) do
            if type(up) == "table" then
                for key, v in pairs(up) do
                    if v == RSv then up[key] = fake; return true end
                end
            end
        end
        return false
    end)
    return ok and installed == true
end
function SA.hook()
    if SA.hooked ~= nil then return SA.hooked end
    SA.hooked = false
    local rem = Core.Shot and Core.Shot.remote()
    local en = Core.Shot and Core.Shot.enum("StartShooting")
    if not rem or not en then SA.hooked = nil; return false end
    local okI = installInputHook(rem, en)
    local okN = false
    if type(hookmetamethod) == "function" and type(getnamecallmethod) == "function" then
        local old
        okN = pcall(function()
            local fn = function(self, ...)
                if self == rem and getnamecallmethod() == "FireServer" then
                    local a, action, packet = ...
                    if type(SA.mods) == "function" then pcall(SA.mods, a, action, packet) end
                    if action == en then handlePacket(a, packet) end
                end
                return old(self, ...)
            end
            if type(newcclosure) == "function" then fn = newcclosure(fn) end
            old = hookmetamethod(game, "__namecall", fn)
        end)
    end
    SA.hooked = (okI or okN) and true or false
    SA.inputHook = okI
    if not SA.hooked then notify("Silent Aim", "Couldn't hook the shot packet, so Silent Aim fires its own shot while you hold fire.", 8, "danger") end
    return SA.hooked
end
-- no hook support in the executor: send the game's shot ourselves while fire is held
local saLast = 0
local function silentFallback()
    if SA.hooked ~= false or not SA.cur or not SA.active() then return end
    if not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then return end
    local now = os.clock()
    if now - saLast < 0.1 then return end
    if (SA.chance or 100) < 100 and math.random() * 100 > SA.chance then return end
    local eq = curGun()
    if not eq then return end
    saLast = now
    pcall(Core.Shot.shoot, eq, SA.cur.part)
end
track(RunService.Heartbeat:Connect(function()
    local ok, e = pcall(function() silentStep(); silentFallback() end)
    if not ok and e ~= SA.lastErr then SA.lastErr = e; notify("Silent aim error", tostring(e):sub(1, 140), 8, "danger") end
end))

-- ---------------------------------------------------------------- Aimbot UI
local HBOPT = {"Head", "Body"}
local FILT = {"Visible", "Vulnerable", "Not Deflecting", "Not Shielded", "Within FOV"}
local FKEY = {["Visible"] = "Visible", ["Vulnerable"] = "Vulnerable", ["Not Deflecting"] = "NotDeflecting", ["Not Shielded"] = "NotShielded", ["Within FOV"] = "WithinFov"}
local RULES = {"Not Reloading", "Scoped In"}
local function filterCb(c) return function(arr)
    local s = toSet(arr)
    for lbl, k in pairs(FKEY) do c.filters[k] = s[lbl] == true end
end end
local function rulesCb(c) return function(arr)
    local s = toSet(arr)
    c.rules.NotReloading, c.rules.ScopedIn = s["Not Reloading"] == true, s["Scoped In"] == true
end end
local function hbCb(c) return function(arr)
    local s = toSet(arr)
    c.hitboxes.Head, c.hitboxes.Body = s["Head"] == true, s["Body"] == true
end end
local function targeting(ui, c)
    ui.Section("Targeting")
    ui.MultiDropdown("Target Filters", FILT, FILT, filterCb(c))
    ui.MultiDropdown("Allowed Hitboxes", HBOPT, HBOPT, hbCb(c))
    ui.Dropdown("Aim Point", {"Center", "Closest Point"}, "Center", function(v) c.ptype = v end)
    ui.Slider("Surface Reduction (%)", 0, 100, 0, function(v) c.surfRed = v end, 1)
    ui.Toggle("Preserve Depth", false, function(v) c.keepDepth = v == true end)
    ui.Dropdown("Hitbox Selection", {"Closest to Crosshair", "Weighted Random"}, "Closest to Crosshair", function(v) c.hsel = v end)
    ui.Slider("Head %", 0, 100, 50, function(v) c.headPct = v end, 1)
end

