-- ===== ESP extras =====
do
local X = {dot = false, dotCol = hexc("#FFFFFF"), dotSize = 1, look = false, lookCol = hexc("#FFA0BE"), lookLen = 8, arrow = false,
arrowCol = hexc("#FFA0BE"), arrowR = 260, arrowTxt = true, maxd = 1500, team = true, pool = {}}
function X.get(plr)
local o = X.pool[plr]
if o then return o end
o = {}
local d = Instance.new("Frame"); d.AnchorPoint = Vector2.new(0.5, 0.5); d.BorderSizePixel = 0; d.Visible = false; d.ZIndex = 3
local dc = Instance.new("UICorner"); dc.CornerRadius = UDim.new(1, 0); dc.Parent = d
local ds = Instance.new("UIStroke"); ds.Thickness = 1; ds.Color = Color3.new(0, 0, 0); ds.Transparency = 0.3; ds.Parent = d
d.Parent = aimGui
local l = Instance.new("Frame"); l.AnchorPoint = Vector2.new(0.5, 0.5); l.BorderSizePixel = 0; l.Visible = false; l.ZIndex = 3; l.Parent = aimGui
local a = Instance.new("TextLabel"); a.BackgroundTransparency = 1; a.AnchorPoint = Vector2.new(0.5, 0.5); a.Size = UDim2.fromOffset(26, 26)
a.Text = "▲"; a.TextSize = 24; a.FontFace = Core.Body; a.TextStrokeTransparency = 0.3; a.Visible = false; a.ZIndex = 3; a.Parent = aimGui
local t = Instance.new("TextLabel"); t.BackgroundTransparency = 1; t.AnchorPoint = Vector2.new(0.5, 0.5); t.Size = UDim2.fromOffset(60, 14)
t.TextSize = 13; t.FontFace = Core.Body; t.TextStrokeTransparency = 0.4; t.Visible = false; t.ZIndex = 3; t.Parent = aimGui
o.d, o.l, o.a, o.t = d, l, a, t
X.pool[plr] = o
return o
end
function X.hide(o) if o then o.d.Visible = false; o.l.Visible = false; o.a.Visible = false; o.t.Visible = false end end
function X.step()
if X.gone then return end
local cam = Workspace.CurrentCamera
if not cam then return end
local on = X.dot or X.look or X.arrow
local vp, cpos = cam.ViewportSize, cam.CFrame.Position
for _, plr in ipairs(Players:GetPlayers()) do
if plr ~= player then
local o = X.pool[plr]
local char = on and plr.Character
local hum = char and char:FindFirstChildOfClass("Humanoid")
local head = char and char:FindFirstChild("Head")
local hrp = char and char:FindFirstChild("HumanoidRootPart")
local ok = hum ~= nil and head ~= nil and hrp ~= nil and hum.Health > 0
local dist = hrp and (cpos - hrp.Position).Magnitude or 0
if ok and dist > X.maxd then ok = false end
if ok and X.team and Core.sameTeam(plr) then ok = false end
if not ok then X.hide(o)
else
o = o or X.get(plr)
local sp = cam:WorldToViewportPoint(head.Position)
local inView = sp.Z > 0 and sp.X >= 0 and sp.X <= vp.X and sp.Y >= 0 and sp.Y <= vp.Y
if X.dot and inView then
local s = math.clamp(1800 / (dist + 15), 3, 16) * X.dotSize
o.d.Size = UDim2.fromOffset(s, s); o.d.Position = UDim2.fromOffset(sp.X, sp.Y); o.d.BackgroundColor3 = X.dotCol; o.d.Visible = true
else o.d.Visible = false end
if X.look and inView then
local e = cam:WorldToViewportPoint(head.Position + head.CFrame.LookVector * X.lookLen)
if e.Z > 0 then
local dx, dy = e.X - sp.X, e.Y - sp.Y
o.l.Size = UDim2.fromOffset(math.sqrt(dx * dx + dy * dy), 1.5); o.l.Position = UDim2.fromOffset((sp.X + e.X) / 2, (sp.Y + e.Y) / 2)
o.l.Rotation = math.deg(math.atan2(dy, dx)); o.l.BackgroundColor3 = X.lookCol; o.l.Visible = true
else o.l.Visible = false end
else o.l.Visible = false end
if X.arrow and not inView then
local rel = cam.CFrame:PointToObjectSpace(hrp.Position)
local dir = Vector2.new(rel.X, rel.Z)
if dir.Magnitude < 1e-3 then dir = Vector2.new(0, 1) end
dir = dir.Unit
local r = math.min(X.arrowR, math.min(vp.X, vp.Y) / 2 - 24)
local p = Vector2.new(vp.X / 2, vp.Y / 2) + dir * r
o.a.Position = UDim2.fromOffset(p.X, p.Y); o.a.Rotation = math.deg(math.atan2(dir.X, -dir.Y)); o.a.TextColor3 = X.arrowCol; o.a.Visible = true
if X.arrowTxt then
local tpos = p - dir * 22
o.t.Position = UDim2.fromOffset(tpos.X, tpos.Y); o.t.Text = math.floor(dist) .. "m"; o.t.TextColor3 = X.arrowCol; o.t.Visible = true
else o.t.Visible = false end
else o.a.Visible = false; o.t.Visible = false end
end
end
end
end
track(Players.PlayerRemoving:Connect(function(p)
local o = X.pool[p]
if o then for _, v in pairs(o) do pcall(function() v:Destroy() end) end; X.pool[p] = nil end
end))
pcall(function() RunService:UnbindFromRenderStep("AspenExtras") end)
RunService:BindToRenderStep("AspenExtras", Enum.RenderPriority.Last.Value, X.step)
gui.Destroying:Connect(function() X.gone = true; pcall(function() RunService:UnbindFromRenderStep("AspenExtras") end) end)
vis.Section("Extras")
vis.Slider("Extras Max Range", 50, 5000, 1500, function(v) X.maxd = v end, 10)
vis.Toggle("Extras Team Check", true, function(v) X.team = v == true end)
vis.Toggle("Head Dot", false, function(v) X.dot = v == true end)
vis.ColorWheel("Head Dot Colour", "#FFFFFF", function(h) X.dotCol = hexc(h) end)
vis.Slider("Head Dot Size", 0.5, 3, 1, function(v) X.dotSize = v end, 0.1)
vis.Toggle("Look Direction", false, function(v) X.look = v == true end)
vis.ColorWheel("Look Colour", "#FFA0BE", function(h) X.lookCol = hexc(h) end)
vis.Slider("Look Length", 2, 30, 8, function(v) X.lookLen = v end, 1)
vis.Toggle("Off-screen Arrows", false, function(v) X.arrow = v == true end)
vis.ColorWheel("Arrow Colour", "#FFA0BE", function(h) X.arrowCol = hexc(h) end)
vis.Slider("Arrow Radius", 80, 600, 260, function(v) X.arrowR = v end, 10)
vis.Toggle("Arrow Distance Text", true, function(v) X.arrowTxt = v == true end)
end

do
local TB = {on = false, act = "Always", held = false, toggled = false, react = 0.05, rel = 0.08, radius = 0, hit = "Any", scoped = false,
noreload = true, team = true, maxd = 1000, gap = 0, elapsed = nil, left = 0, lastFire = 0}
Core.Shot = {}
do
    local RSv = game:GetService("ReplicatedStorage")
    local S = Core.Shot
    local pi = math.pi
    local function enc(x, y, z, a, b, c) return {["\0"] = x, ["\1"] = y, ["\2"] = z, ["\3"] = a, ["\4"] = b, ["\5"] = c} end
    S.ORIG, S.DIR, S.OFF = enc(-9e37, 0, 0, -pi / 2, pi, pi), enc(0, -90000000, 0, -pi / 2, pi, pi), enc(0, 1, 0, 0, 0, 0)
    local remote, enums
    function S.remote()
        if remote and remote.Parent then return remote end
        local ok, r = pcall(function() return RSv.Remotes.Replication.Fighter.UseItem end)
        remote = ok and r or nil
        return remote
    end
    function S.enum(name)
        if not enums then
            local ok, lib = pcall(function() return require(RSv.Modules.EnumLibrary) end)
            if ok and type(lib) == "table" then enums = rawget(lib, "_to_enum") end
        end
        return enums and enums[name]
    end
    function S.objectId(eq)
        local d = rawget(eq, "Data")
        local id
        if type(d) == "table" then pcall(function() id = d.ObjectID end) end
        if id then return id end
        for _, tbl in ipairs({eq, type(d) == "table" and d or {}}) do
            for k, v in pairs(tbl) do
                if type(k) == "string" and k:lower():find("objectid") and v ~= nil then return v end
            end
        end
        return nil
    end
    function S.hitbox(ch, kind)
        if not ch then return nil end
        if kind == "Head" then return ch:FindFirstChild("HitboxHead") or ch:FindFirstChild("Head") end
        return ch:FindFirstChild("HitboxBody") or ch:FindFirstChild("HumanoidRootPart")
    end
    -- the game's own encoded shot (same packet newo/sleepy ragebot sends)
    function S.shoot(eq, part, realOrigin)
        local rem, id, en = S.remote(), S.objectId(eq), S.enum("StartShooting")
        if not rem then return false, "UseItem remote not found" end
        if not en then return false, "EnumLibrary StartShooting not found" end
        if not id then return false, "gun object id not found" end
        if not part then return false, "hitbox part not found" end
        local info = rawget(eq, "Info")
        local t = {["\0"] = S.ORIG, ["\1"] = S.DIR, ["\2"] = part, ["\3"] = S.OFF}
        local p = (type(info) == "table" and info.IsRaycast) and {["\1"] = t, ["\2"] = true} or {["\1"] = t}
        return pcall(rem.FireServer, rem, id, en, p, nil)
    end
end
local tb = addSub(mCombat, "Triggerbot", "Fires when an enemy hitbox is under your crosshair.")
tb.Section("Triggerbot")
tb.Toggle("Triggerbot", false, function(v) TB.on = v end)
tb.Dropdown("Activation", {"Always", "Hold Right Mouse", "Key Hold", "Key Toggle"}, "Always", function(v) TB.act = v end)
local tbKey = tb.Keybind("Trigger Key", "T")
tb.Section("Timing")
tb.Slider("Reaction Delay (s)", 0, 1, 0.05, function(v) TB.react = v end, 0.01)
tb.Slider("Release Delay (s)", 0, 1, 0.08, function(v) TB.rel = v end, 0.01)
tb.Slider("Min Time Between Shots (s)", 0, 0.5, 0, function(v) TB.gap = v end, 0.01)
tb.Section("Targeting")
tb.Dropdown("Hitbox", {"Any", "Head Only", "Body Only"}, "Any", function(v) TB.hit = v end)
tb.Slider("Trigger Radius (px)", 0, 40, 0, function(v) TB.radius = v end, 1)
tb.Slider("Max Distance", 20, 5000, 1000, function(v) TB.maxd = v end, 10)
tb.Toggle("Team Check", true, function(v) TB.team = v end)
tb.Section("Conditions")
tb.Toggle("Scoped In Only", false, function(v) TB.scoped = v end)
tb.Toggle("Not Reloading", true, function(v) TB.noreload = v end)
tb.Hint("Reaction Delay is how long the crosshair must stay on a target before firing. Release Delay keeps the trigger held briefly after you leave the target. Trigger Radius also fires when a target is within that many pixels of the crosshair.")
local function tbMatch(i)
    local b = tbKey.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
track(UIS.InputBegan:Connect(function(i, gp) if gp or not tbMatch(i) then return end TB.held = true; TB.toggled = not TB.toggled end))
track(UIS.InputEnded:Connect(function(i) if tbMatch(i) then TB.held = false end end))
local function tbActive()
    if not TB.on then return false end
    local m = TB.act
    if m == "Always" then return true end
    if m == "Hold Right Mouse" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) or UIS:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, Enum.KeyCode.ButtonL2) end
    if m == "Key Hold" then return TB.held end
    return TB.toggled
end
local trp = RaycastParams.new()
trp.FilterType = Enum.RaycastFilterType.Exclude
local function look(cam, px, py)
    local ray = cam:ViewportPointToRay(px, py)
    local ign = {player.Character, cam}
    for _ = 1, 16 do
        trp.FilterDescendantsInstances = ign
        local r = Workspace:Raycast(ray.Origin, ray.Direction * 2000, trp)
        if not r then return false end
        local inst = r.Instance
        local model = inst:FindFirstAncestorOfClass("Model")
        local plr = model and Players:GetPlayerFromCharacter(model)
        if plr and plr ~= player then
            if inst.Name:sub(1, 6) ~= "Hitbox" then
                ign[#ign + 1] = inst
            else
                local hum = model:FindFirstChildOfClass("Humanoid")
                local okHit = hum ~= nil and hum.Health > 0
                if okHit and TB.team and Core.sameTeam(plr) then okHit = false end
                if okHit and (r.Position - cam.CFrame.Position).Magnitude > TB.maxd then okHit = false end
                if okHit and TB.hit == "Head Only" and not inst.Name:find("Head") then okHit = false end
                if okHit and TB.hit == "Body Only" and not inst.Name:find("Body") then okHit = false end
                return okHit
            end
        elseif inst.CanCollide == false or inst.Transparency >= 0.95 then
            ign[#ign + 1] = inst
        else
            return false
        end
    end
    return false
end
local function onTarget(cam)
    local c = cam.ViewportSize * 0.5
    if look(cam, c.X, c.Y) then return true end
    local rd = TB.radius
    if rd > 0 then
        for _, o in ipairs({Vector2.new(rd, 0), Vector2.new(-rd, 0), Vector2.new(0, rd), Vector2.new(0, -rd)}) do
            if look(cam, c.X + o.X, c.Y + o.Y) then return true end
        end
    end
    return false
end
local function gun()
    local f = Core.myFighter and Core.myFighter()
    local eq = f and rawget(f, "EquippedItem")
    if type(eq) ~= "table" then return nil end
    local info = rawget(eq, "Info")
    if type(info) ~= "table" or info.Type == "Melee" or info.Type == "Throwable" then return nil end
    return f, eq
end
local function fire(f, eq)
    local now = os.clock()
    if now - TB.lastFire < TB.gap then return end
    TB.lastFire = now
    local ok = type(f.Input) == "function" and pcall(f.Input, f, "StartShooting")
    if not ok and type(eq.Input) == "function" then ok = pcall(eq.Input, eq, "StartShooting") end
    task.delay(0.03, function()
        local ok2 = type(f.Input) == "function" and pcall(f.Input, f, "StopShooting")
        if not ok2 and type(eq.Input) == "function" then pcall(eq.Input, eq, "StopShooting") end
    end)
end
local function tbStep(dt)
    if not tbActive() then TB.elapsed = nil; TB.left = 0; return end
    local cam = Workspace.CurrentCamera
    local f, eq = gun()
    if not cam or not f then TB.elapsed = nil; TB.left = 0; return end
    local data = rawget(eq, "Data")
    if TB.scoped and not (type(data) == "table" and data.IsAiming == true) then TB.elapsed = nil; TB.left = 0; return end
    if TB.noreload then
        local okR, rl = pcall(function() return type(eq.IsReloading) == "function" and eq:IsReloading() end)
        if okR and rl == true then TB.elapsed = nil; TB.left = 0; return end
    end
    if onTarget(cam) then
        TB.elapsed = (TB.elapsed or 0) + (TB.elapsed and dt or 0)
        if TB.elapsed >= TB.react then TB.left = TB.rel; fire(f, eq); return end
    else
        TB.elapsed = nil
    end
    TB.left = math.max(0, TB.left - dt)
    if TB.left > 0 then fire(f, eq) end
end
pcall(function() RunService:UnbindFromRenderStep("AspenTrigger") end)
RunService:BindToRenderStep("AspenTrigger", Enum.RenderPriority.Camera.Value + 3, function(dt) pcall(tbStep, dt) end)
gui.Destroying:Connect(function() pcall(function() RunService:UnbindFromRenderStep("AspenTrigger") end) end)
end

do (function()
-- ===================== RAGEBOT (ported from Kaze hub's rage + Kicia transport settings) =====================
-- loop (Heartbeat): pick target -> make sure the chosen gun is equipped -> when the gun is ready, sit at the shot position (head based) for a
-- moment, fire the shot packet from there, hold, then teleport back to where you were before the shooting started.
-- RenderStepped(First) puts your real character back so you never see any of it.
local RS = game:GetService("ReplicatedStorage")
local RG = {on = false, act = "Always", held = false, toggled = false, tprio = "Closest", maxd = 5000, team = true, noFF = true,
    weapon = "Primary", hit = "Head", pos = "Inside", rndWait = 1, rndPos = "Inside", rndAt = 0, dist = 5, inY = -0.7, orbit = 8, face = false,
    autoReload = true, autoEquip = true, evade = "Random", evR = 1000000, evF = 0.5, trOff = 0, shootFrames = 2, onEmpty = "SwapOrReload", use = {Primary = true, Secondary = true, Melee = false}, kLock = nil, park = true, retMode = "Start Position", home = nil, roundAt = -100, roundDelay = 0.5, sawRound = false, spawnAt = -100, settle = 0, hold = 0.12, gap = 0, multi = 1, phys = true, eqWait = 0.18, mDelay = 0.4,
    target = nil, state = nil, oldCF = nil, root = nil, lastCF = nil, posSince = nil, shotAt = -100, lockUntil = 0, nextShot = 0, nextReload = 0,
    nextEquip = 0, nextMelee = 0, eqSeen = nil, eqAt = 0, physOn = false, physH = nil, dead = false, rt = nil, ammoId = nil, ammoSeen = nil, shotsSince = 0,
    eqWait = 0.1, mDelay = 0.4, phys = true, sticky = true, predict = false, predT = 0.1, listAt = -100, list = nil, listFor = nil,
    ind = true, indCol = Color3.fromRGB(255, 255, 255), spin = 0, barLen = 6, barTh = 1, barGap = 3, txtSize = 14, indY = 0, indName = true,
    }
local MODES = {"Inside", "Above", "Under", "Behind", "Front", "Orbit"}

-- ---- game plumbing (same lookups kaze / kicia use) ----
local NET = {}
local function ensureNet()
    if NET.fire and NET.remote and NET.to then return true end
    pcall(function()
        local lib = require(RS:WaitForChild("Modules", 3):WaitForChild("EnumLibrary", 3))
        NET.to = rawget(lib, "_to_enum") or lib._to_enum
        local rem = RS:WaitForChild("Remotes", 3):WaitForChild("Replication", 3):WaitForChild("Fighter", 3):WaitForChild("UseItem", 3)
        local fire = rem.FireServer
        if type(clonefunction) == "function" then fire = clonefunction(fire) end
        NET.remote, NET.fire = rem, fire
    end)
    return NET.fire and NET.remote and NET.to and true or false
end
local FC
local function myFighter()
    if not FC then
        local ok, m = pcall(function()
            local c = player:WaitForChild("PlayerScripts", 3):WaitForChild("Controllers", 3):WaitForChild("FighterController", 3)
            return require(c)
        end)
        FC = ok and m or nil
    end
    local objs = FC and rawget(FC, "Objects")
    if type(objs) ~= "table" then return nil end
    for _, o in pairs(objs) do
        if type(o) == "table" and rawget(o, "Player") == player then return o end
    end
end
Core.myFighter = myFighter
local function weaponList(f)
    local list, gi = {}, 0
    local its = rawget(f, "Items")
    if type(its) ~= "table" then return list end
    for _, it in pairs(its) do
        local info, data = rawget(it, "Info"), rawget(it, "Data")
        if type(info) == "table" and type(data) == "table" and data.ObjectID then
            local slot
            if info.Type == "Melee" then slot = "Melee"
            elseif info.Type == "Throwable" then slot = "Utility"
            else
                gi = gi + 1
                slot = tostring(info.Slot or info.Category or "")
                if slot ~= "Primary" and slot ~= "Secondary" then slot = gi == 1 and "Primary" or "Secondary" end
            end
            list[#list + 1] = {item = it, id = data.ObjectID, name = data.Name, ty = info.Type, slot = slot, ammo = data.Ammo, reserve = data.AmmoReserve, ray = info.IsRaycast, info = info}
        end
    end
    return list
end
local function cfEnc(cf)
    local rx, ry, rz = cf:ToOrientation()
    return {["\0"] = cf.X, ["\1"] = cf.Y, ["\2"] = cf.Z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz}
end
local hitRP = RaycastParams.new()
hitRP.FilterType = Enum.RaycastFilterType.Include
local function shotLocal(origin, part)
    hitRP.FilterDescendantsInstances = {part}
    local r = Workspace:Raycast(origin, part.Position - origin, hitRP)
    local l = r and part.CFrame:PointToObjectSpace(r.Position)
    if l and l ~= Vector3.zero then return l end
    local l2 = part.CFrame:PointToObjectSpace(part:GetClosestPointOnSurface(origin))
    if l2 == Vector3.zero then return nil end
    return l2
end
-- Kicia's hitscan packet: fixed encoded origin/direction, the target's HitboxHead as the hit part, fan-fired guns (Revolver) flagged
local K_PI = math.pi
local function kenc(x, y, z, rx, ry, rz) return {["\0"] = x, ["\1"] = y, ["\2"] = z, ["\3"] = rx, ["\4"] = ry, ["\5"] = rz} end
local K_ORG = kenc(-9e37, 0, 0, -K_PI / 2, K_PI, K_PI)
local K_DIR = kenc(0, -90000000, 0, -K_PI / 2, K_PI, K_PI)
local K_HIT = kenc(0, 1, 0, 0, 0, 0)
local function fireGun(w, t, org)
    if not ensureNet() then return false end
    local part = (RG.hit == "Body" and (t.hbody or t.root)) or t.head
    local sh = {["\0"] = K_ORG, ["\1"] = K_DIR, ["\2"] = part, ["\3"] = K_HIT, ["\4"] = (w.name == "Revolver") or nil}
    local args = w.ray and {["\1"] = sh, ["\2"] = true} or {["\1"] = sh}
    Core.rageFiring = true
    pcall(NET.fire, NET.remote, w.id, NET.to["StartShooting"], args, nil)
    Core.rageFiring = false
    return true
end
local mAnim = 1
local function attackMelee(w, t, org)
    if not ensureNet() then return false end
    local to = NET.to
    local part = RG.hit == "Body" and t.root or t.head
    local lh = shotLocal(org, part) or Vector3.zero
    local cf = cfEnc((part.Position - org).Magnitude > 0.01 and CFrame.lookAt(org, part.Position) or CFrame.new(org))
    local sh = {["\0"] = cf, ["\1"] = cf, ["\2"] = part, ["\3"] = cfEnc(CFrame.new(lh))}
    local an = to["AttackAnimation" .. mAnim] or to["Attack" .. mAnim] or to["AttackAnimation1"] or to["Attack1"]
    Core.rageFiring = true
    pcall(NET.fire, NET.remote, w.id, to["StartShooting"], {["\1"] = sh, ["\2"] = an}, nil)
    Core.rageFiring = false
    mAnim = mAnim % 3 + 1
    if not (to["AttackAnimation" .. mAnim] or to["Attack" .. mAnim]) then mAnim = 1 end
    return true
end
local function reload(w)
    local now = tick()
    if now < RG.nextReload or not ensureNet() then return false end
    RG.nextReload = now + 0.7
    local r = NET.to["Reload"]
    NET.fire(NET.remote, w.id, NET.to["StartReloading"], {["\1"] = r, ["\2"] = r}, nil)
    return true
end
local function equip(w)
    local now = tick()
    if now < RG.nextEquip then return end
    RG.nextEquip = now + 0.12
    pcall(function() local fn = w.item.Equip; if type(fn) == "function" then fn(w.item) end end)
end
-- fast physics replication while the rage is on
local function physSync(on)
    if RG.physOn == on then return end
    RG.physOn = on
    pcall(function()
        if RG.fallH == nil then RG.fallH = Workspace.FallenPartsDestroyHeight end
        Workspace.FallenPartsDestroyHeight = on and (0 / 0) or RG.fallH
        if RG.fallE == nil then RG.fallE = Workspace.FallHeightEnabled end
        Workspace.FallHeightEnabled = on and false or RG.fallE
    end)
    local sf = setfflag or (syn and syn.setfflag)
    if type(sf) == "function" then
        pcall(sf, "DFIntS2PhysicsSenderRate", on and "120" or "15")
        pcall(sf, "DFIntAssemblyHistoryBufferSize", on and "2147483648" or "15")
        pcall(sf, "DFIntAssemblyHistorySkipSize", on and "0" or "8")
    end
end


local function safeLand(hrp)
    if not hrp or not hrp.Parent then return end
    pcall(function()
        local cf = RG.home or RG.oldCF
        if cf then hrp.CFrame = cf end
        hrp.AssemblyLinearVelocity = Vector3.zero; hrp.AssemblyAngularVelocity = Vector3.zero
    end)
    RG.oldCF = nil; RG.zeroUntil = os.clock() + 0.8
end
-- Kicia: while the rage is on, the root part replicates through Terrain (PhysicsRepRootPart) so nothing ties the server-side position to your character
track(RunService.Heartbeat:Connect(function()
    local c = player.Character
    local hrp = c and c:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    if RG.on and RG.phys then
        RG.prrSet = true
        pcall(function() if setthreadidentity then setthreadidentity(8) end; hrp.PhysicsRepRootPart = Workspace.Terrain end)
    elseif RG.prrSet then
        RG.prrSet = false
        pcall(function() if setthreadidentity then setthreadidentity(8) end; hrp.PhysicsRepRootPart = nil end)
    end
end))
-- ---- round start detection: the game replicates its round status as a plain "RoundStarted" string; watch the replication remotes for it ----
do
    local function scanEnd(v, depth)
        if type(v) == "string" then
            local l = v:lower()
            return l == "roundended" or l == "roundend" or l == "roundover" or l == "intermission" or l == "matchended" or l == "gameended"
        end
        if type(v) == "table" and depth < 3 then
            for _, x in pairs(v) do if scanEnd(x, depth + 1) then return true end end
        end
        return false
    end
    local function scan(v, depth)
        if v == "RoundStarted" then return true end
        if type(v) == "table" and depth < 3 then
            for _, x in pairs(v) do if scan(x, depth + 1) then return true end end
        end
        return false
    end
    local hooked = setmetatable({}, {__mode = "k"})
    local function watch(r)
        if hooked[r] or not r:IsA("RemoteEvent") then return end
        hooked[r] = true
        track(r.OnClientEvent:Connect(function(...)
            for k = 1, select("#", ...) do
                local a_ = select(k, ...)
                if scan(a_, 0) then RG.roundAt = os.clock(); RG.sawRound = true; RG.home = nil; RG.endAt = nil; return end
                if scanEnd(a_, 0) then RG.endAt = os.clock(); return end
            end
        end))
    end
    pcall(function()
        local folder = RS:WaitForChild("Remotes", 5)
        if not folder then return end
        for _, d in ipairs(folder:GetDescendants()) do watch(d) end
        track(folder.DescendantAdded:Connect(watch))
    end)
    -- fallback for modes that never send a round status: a fresh spawn counts as the start of the round
    track(player.CharacterAdded:Connect(function() RG.spawnAt = os.clock(); RG.home = nil end))
end

