local function kmatch(i)
    local b = rgKey.Get()
    if not b or b == "None" then return false end
    return (i.UserInputType == Enum.UserInputType.Keyboard and i.KeyCode.Name == b) or i.UserInputType.Name == b or (i.UserInputType.Name:sub(1, 7) == "Gamepad" and i.KeyCode.Name == b)
end
track(UIS.InputBegan:Connect(function(i, gp) if gp or not kmatch(i) then return end RG.held = true; RG.toggled = not RG.toggled end))
track(UIS.InputEnded:Connect(function(i) if kmatch(i) then RG.held = false end end))
local function active()
    if not RG.on then return false end
    if RG.act == "Always" then return true end
    if RG.act == "Hold" then return RG.held end
    return RG.toggled
end

-- ---- targeting + position ----
local function pickTarget(hrp)
    -- Kicia-style tiers (voided players first) + Kaze-style filters (fast movers, only if healthier), then the chosen sort
    local best, bs
    local cam = Workspace.CurrentCamera
    local myHp = math.huge
    local mc = player.Character
    local mh = mc and mc:FindFirstChildOfClass("Humanoid")
    if mh then myHp = mh.Health end
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player and not (RG.team and Core.sameTeam(plr)) then
            local c = plr.Character
            local h = c and c:FindFirstChildOfClass("Humanoid")
            local r = c and c:FindFirstChild("HumanoidRootPart")
            local head = c and (c:FindFirstChild("HitboxHead") or c:FindFirstChild("Head"))
            if h and r and head and h.Health > 0 and not (RG.noFF and c:FindFirstChildOfClass("ForceField")) and not (RG.lead and myHp < h.Health) then
                local d = (r.Position - hrp.Position).Magnitude
                local voided = RG.voidPrio and r.Position.Magnitude > 1000000
                if d <= RG.maxd or voided then
                    local score = d
                    if RG.tprio == "Lowest Health" then score = h.Health * 1000 + d
                    elseif RG.tprio == "Highest Health" then score = -h.Health * 1000 + d
                    elseif RG.tprio == "Fastest" then score = -r.AssemblyLinearVelocity.Magnitude * 1000 + d
                    elseif RG.tprio == "Closest To Crosshair" and cam then
                        local dir = head.Position - cam.CFrame.Position
                        if dir.Magnitude > 0.01 then score = math.acos(math.clamp(cam.CFrame.LookVector:Dot(dir.Unit), -1, 1)) * 1000 + d * 0.001 end
                    end
                    if voided then score = score - 1e12 end
                    if RG.hackers and r.AssemblyLinearVelocity.Magnitude > 120 then score = score - 1e9 end
                    if RG.sticky and RG.target and RG.target.plr == plr then score = score - 1e9 end
                    if not bs or score < bs then best, bs = {plr = plr, char = c, hum = h, root = r, head = head, hbody = c:FindFirstChild("HitboxBody"), dist = d}, score end
                end
            end
        end
    end
    return best
end
local function baseCF(t, now)
    local hp, d = t.head.Position, RG.dist
    if RG.predict then
        local v = t.root.AssemblyLinearVelocity
        if v.Magnitude > 120 then v = v.Unit * 120 end
        hp = hp + v * RG.predT
    end
    local mode = RG.pos
    if mode == "Random" then
        if now >= RG.rndAt then RG.rndPos = MODES[math.random(1, #MODES)]; RG.rndAt = now + RG.rndWait end
        mode = RG.rndPos
    end
    local look = t.root.CFrame.LookVector
    local p
    if mode == "Above" then p = hp + Vector3.new(0, d, 0)
    elseif mode == "Under" then p = hp - Vector3.new(0, d, 0)
    elseif mode == "Behind" then p = hp - look * d
    elseif mode == "Front" then p = hp + look * d
    elseif mode == "Orbit" then local a = now * RG.orbit; p = hp + Vector3.new(math.cos(a) * d, 0, math.sin(a) * d)
    else p = hp + Vector3.new(0, RG.inY, 0.05) end
    if RG.face and (hp - p).Magnitude > 0.05 then
        local dir = (hp - p).Unit
        return CFrame.lookAt(p, hp, math.abs(dir.Y) > 0.99 and Vector3.new(0, 0, 1) or Vector3.yAxis)
    end
    return CFrame.new(p)
end

-- ---- Kicia's safe-position rings: server-accepted far spots (normal ring + immune ring) ----
local KRING = (function()
    local rnd = Random.new()
    local function u32() return rnd:NextInteger(0, 65535) * 65536 + rnd:NextInteger(0, 65535) end
    local k1, k2, k3, k4 = u32(), u32(), u32(), u32()
    local bxor, lrot, rrot, lsh = bit32.bxor, bit32.lrotate, bit32.rrotate, bit32.lshift
    local function mix(a, b)
        local n1 = (bxor(a, b, k1) + k2) % 4294967296
        local n2 = (bxor(n1, lrot(n1, 7)) + k3) % 4294967296
        local n3 = (bxor(n2, rrot(n2, 11)) + k4) % 4294967296
        return bxor(n3, lrot(n3, 17))
    end
    local function mk(min, max)
        local ymin = min + 400 + 64
        return {Min = min, Max = max, Cells = (max - min) / 2048, YMin = ymin, YSpan = max - 400 - 64 - ymin + 1, Salt = u32()}
    end
    local function hsh(r, x, z, c) return mix(bxor(x, lsh(z, 16)), bxor(c, r.Salt)) end
    local function jit(r, x, z, c) return hsh(r, x, z, c) % 1121 - 560 end
    local function cell(r, x, z)
        local b = r.Min + 1024
        return Vector3.new(b + x * 2048 + jit(r, x, z, 324508639), r.YMin + hsh(r, x, z, 826366246) % r.YSpan, b + z * 2048 + jit(r, x, z, 610839776))
    end
    local function pick(r)
        local top = r.Cells - 1
        local p = cell(r, rnd:NextInteger(0, top), rnd:NextInteger(0, top))
        local d = 200 * rnd:NextNumber() ^ (1 / 3)
        local y = rnd:NextNumber(-1, 1)
        local q = math.sqrt(1 - y * y)
        local a = rnd:NextNumber(0, math.pi * 2)
        return p + Vector3.new(d * q * math.cos(a), d * y, d * q * math.sin(a))
    end
    local function rot(v) return CFrame.new(v) * CFrame.fromOrientation(rnd:NextNumber(-math.pi, math.pi), rnd:NextNumber(-math.pi, math.pi), rnd:NextNumber(-math.pi, math.pi)) end
    local normal, immune = mk(65536, 524288), mk(134217728, 1073741824)
    return {getNormal = function() return rot(pick(normal)) end, getImmune = function() return rot(pick(immune)) end}
end)()
local function immuneCF() return KRING.getImmune() end
local function inLimit(p) return math.abs(p.X) >= 4194304 or math.abs(p.Y) >= 4194304 or math.abs(p.Z) >= 4194304 end
local function ringAround(pos, r0, r1)
    local a, r = math.random() * math.pi * 2, r0 + (r1 - r0) * math.random()
    return CFrame.new(pos + Vector3.new(math.cos(a) * r, 0, math.sin(a) * r)) * CFrame.fromOrientation(math.random() * 6.28, math.random() * 6.28, math.random() * 6.28)
end
local CollectionSvc = game:GetService("CollectionService")
-- where the server sees you while you are not shooting (nil = stay where you are)
local function evadeCF(hrp)
    local m = RG.evade
    if m == "Off" then return nil end
    if m == "Home" then
        if RG.retMode == "Live Position" or not RG.home then return hrp.CFrame end
        return RG.home
    end
    if m == "Immune Ring" then return immuneCF() end
    if m == "Translocate" then
        for _, p in ipairs(CollectionSvc:GetTagged("OutOfBoundsPart")) do
            if p:IsA("BasePart") and p:GetAttribute("KillDelay") == 0 then return p.CFrame * CFrame.new(0, -p.Size.Y / 2 + RG.trOff, 0) end
        end
        return ringAround(hrp.Position, 10000, 1e9)
    end
    -- Random: far spot where one axis is pushed out to 2^30
    local pos = hrp.Position
    local base = RG.evR
    local cf = ringAround(Vector3.new(0, pos.Y, 0), base, base + base * RG.evF)
    local p = cf.Position
    local ax = math.random(1, 3)
    local nx, ny, nz = p.X, p.Y, p.Z
    if ax == 1 then nx = 1073741824 elseif ax == 2 then ny = 1073741824 else nz = 1073741824 end
    return cf - p + Vector3.new(nx, ny, nz)
end

local function step(dt)
    if RG.dead then return end
    local ch = player.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    local cam = Workspace.CurrentCamera
    if RG.endAt and os.clock() < RG.endAt + 5 and active() then
        -- round over: stop everything, put you back on your own spot, no velocity, no more moving
        if hrp and hum and hum.Health > 0 then safeLand(hrp) end
        RG.state = "round ended"; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.hadTarget = false; physSync(false)
        return
    end
    if hrp and hum and hum.Health > 0 and RG.zeroUntil and os.clock() < RG.zeroUntil then
        pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero; hrp.AssemblyAngularVelocity = Vector3.zero end)
    end
    if not active() then
        if RG.home and hrp and hum and hum.Health > 0 then
            -- put you back on your original spot, safely, and kill any leftover velocity
            pcall(function() RG.oldCF = nil; hrp.CFrame = RG.home; hrp.AssemblyLinearVelocity = Vector3.zero; hrp.AssemblyAngularVelocity = Vector3.zero end)
            RG.zeroUntil = os.clock() + 0.6
        end
        RG.state = nil; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil; physSync(false); return
    end
    if not (hum and hrp and hum.Health > 0 and cam) then RG.state = "waiting for spawn..."; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil; physSync(false); return end
    physSync(true)
    ensureNet()
    local now = os.clock()
    -- round start: wait Round Start Delay seconds (default 1s) before any shooting begins
    local gate = RG.sawRound and RG.roundAt or RG.spawnAt
    if now < gate + RG.roundDelay then
        RG.state = "waiting..."; RG.target = nil; RG.lastCF = nil; RG.rt = nil; RG.home = nil
        return
    end
    local t = pickTarget(hrp)
    RG.target = t
    if t then RG.hadTarget = true; RG.noTgtSince = nil end
    if not t and not RG.rt then
        -- targets gone (round ended / everyone dead): land safely before idling
        if RG.hadTarget then RG.noTgtSince = RG.noTgtSince or now end
        if RG.hadTarget and RG.noTgtSince and now - RG.noTgtSince > 0.3 then safeLand(hrp); RG.hadTarget = false end
        RG.state = "waiting..."; RG.lastCF = nil
        if not RG.hadTarget then RG.home = nil end
        return
    end
    -- the spot you stood on before the shooting started; every "waiting" frame sends you back here
    if not RG.home then RG.home = hrp.CFrame end
    local function homeCF()
        if RG.retMode == "Live Position" or not RG.home then return hrp.CFrame end
        return RG.home
    end
    local fighter = myFighter()
    if not fighter then RG.rt = nil; RG.state = "fighter not found"; return end
    local list = RG.list
    if not list or RG.listFor ~= fighter or now - RG.listAt > 0.3 then
        list = weaponList(fighter); RG.list, RG.listFor, RG.listAt = list, fighter, now
    end
    local eq = rawget(fighter, "EquippedItem")
    local eqData = type(eq) == "table" and rawget(eq, "Data")
    local eqId = type(eqData) == "table" and eqData.ObjectID or nil
    local chosen, top
    do
        local order = {RG.weapon}
        for _, sl in ipairs({"Primary", "Secondary", "Melee"}) do if sl ~= RG.weapon then order[#order + 1] = sl end end
        for _, sl in ipairs(order) do
            if RG.use[sl] or sl == RG.weapon then
                for _, w in ipairs(list) do
                    if w.slot == sl then
                        top = top or w
                        local d2 = rawget(w.item, "Data")
                        local am = type(d2) == "table" and d2.Ammo or nil
                        if not chosen and (w.ty == "Melee" or type(am) ~= "number" or am > 0) then chosen = w end
                        break
                    end
                end
            end
        end
        if RG.onEmpty == "Reload" then chosen = top else chosen = chosen or top end
    end
    if not chosen then RG.list = nil; RG.rt = nil; RG.state = "no " .. RG.weapon:lower() .. " weapon"; return end
    do
        local d2 = rawget(chosen.item, "Data")
        if type(d2) == "table" then chosen.ammo = d2.Ammo; chosen.reserve = d2.AmmoReserve end
    end

    -- ---- Kicia reload transport: from the moment the last bullet is shot until the mag is full again you sit in the immune ring ----
    local ping = player:GetNetworkPing() * 0.5
    local repDelay, remDelay = ping + 0.05, ping + 1 / 60
    local ammo = type(chosen.ammo) == "number" and chosen.ammo or nil
    local reserveOk = type(chosen.reserve) ~= "number" or chosen.reserve > 0
    if RG.ammoId ~= chosen.id or RG.ammoSeen ~= ammo then RG.ammoId, RG.ammoSeen, RG.shotsSince = chosen.id, ammo, 0 end
    local isR = false
    pcall(function() local f = chosen.item.IsReloading; if type(f) == "function" then isR = f(chosen.item) == true end end)
    local rt = RG.rt
    if rt and (rt.id ~= chosen.id or eqId ~= chosen.id or now - rt.start > 8) then RG.rt = nil; rt = nil end
    if rt then
        if rt.pending then
            if ammo and ammo <= 0 then rt.pending = false; rt.ack = 0
            elseif now >= rt.ack or (ammo and ammo - RG.shotsSince > 0) then RG.rt = nil; rt = nil end
        elseif not reserveOk or (ammo and ammo > 0 and not isR) then RG.rt = nil; rt = nil
        elseif RG.autoReload and not isR and now >= rt.ready and now >= rt.ack and reload(chosen) then rt.ack = now + remDelay + repDelay end
    end
    if RG.rt then
        RG.state = "reloading..."
        local rcf = immuneCF()
        RG.lastCF = rcf
        if not RG.oldCF then RG.oldCF = hrp.CFrame end
        RG.root = hrp
        hrp.CFrame = rcf
        return
    end
    if not t then RG.state = "waiting..."; RG.lastCF = nil; return end

    local base = baseCF(t, now)
    local org = base.Position
    local function settled(pos)
        local last = RG.lastCF
        if not RG.posSince or not last or (pos - last.Position).Magnitude > 3 then RG.posSince = now end
        return now - RG.posSince >= RG.settle
    end
    -- Kicia shoot lock: keep firing for Shoot Frames frames after the last valid frame; targets pushed out of the world can't be hit
    local canFire = not inLimit(t.root.Position)
    local locked = RG.kLock ~= nil and now < RG.kLock
    if canFire then RG.kLock = now + RG.shootFrames * math.max(dt or 0, 1 / 240) end
    local fireOk = locked or canFire
    local ready, state = false, nil
    if eqId ~= chosen.id then
        RG.eqSeen = nil
        if RG.autoEquip then equip(chosen); state = "equipping..." else state = "weapon not equipped" end
    else
        if RG.eqSeen ~= chosen.id then RG.eqSeen = chosen.id; RG.eqAt = now end
        if now - RG.eqAt < RG.eqWait then state = "equipping..."
        elseif not fireOk then state = "target out of range..."
        elseif chosen.ty == "Melee" then
            ready = tick() >= RG.nextMelee
            if ready and settled(org) then
                if not RG.oldCF then RG.oldCF = hrp.CFrame end
                RG.root = hrp; hrp.CFrame = base
                if attackMelee(chosen, t, org) then RG.shotAt = now; RG.lockUntil = now + RG.hold; RG.nextMelee = tick() + RG.mDelay end
            end
        elseif ammo and ammo <= 0 then
            state = "reloading..."
            if RG.autoReload and reserveOk then RG.rt = {id = chosen.id, start = now, pending = false, ready = now + repDelay, ack = 0} end
        else
            local cd = rawget(chosen.item, "_shoot_cooldown")
            if type(cd) ~= "number" then cd = 0 end
            if tick() >= cd and tick() >= RG.nextShot then
                ready = true
                if settled(org) then
                    -- sit in their head first, then send the shot from there
                    if not RG.oldCF then RG.oldCF = hrp.CFrame end
                    RG.root = hrp; hrp.CFrame = base
                    RG.lockUntil = now + RG.hold; RG.shotAt = now; RG.nextShot = tick() + RG.gap
                    for _ = 1, RG.multi do fireGun(chosen, t, org) end
                    RG.shotsSince = RG.shotsSince + RG.multi
                    -- last bullet: straight into the immune ring until the mag is full again
                    if RG.autoReload and reserveOk and ammo and ammo - RG.shotsSince <= 0 then
                        RG.rt = {id = chosen.id, start = now, pending = true, ready = now + repDelay, ack = now + remDelay + repDelay}
                    end
                end
            end
        end
    end
    RG.state = state or ((now - RG.shotAt < 0.4) and "firing...") or (ready and "locking on...") or "cooldown..."
    local cf
    if RG.rt then cf = immuneCF()
    elseif ready or now < RG.lockUntil or not RG.park then cf = base
    else cf = evadeCF(hrp) end
    RG.lastCF = cf or base
    if cf then
        if not RG.oldCF then RG.oldCF = hrp.CFrame end
        RG.root = hrp
        hrp.CFrame = cf
    end
end
local function restore()
    if RG.oldCF and RG.root and RG.root.Parent then RG.root.CFrame = RG.oldCF end
    RG.oldCF = nil
end
track(RunService.Heartbeat:Connect(function(dt)
