    local spinner = make("Frame", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(120, 120), ZIndex = 120, Active = false, BorderSizePixel = 0}, box)
    local arms = {}
    for i = 1, 4 do
        local a = make("Frame", {BackgroundColor3 = RG.indCol, AnchorPoint = Vector2.new(0.5, 0.5), BorderSizePixel = 0, ZIndex = 121, Active = false}, spinner)
        make("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, a)
        arms[i] = a
    end
    local txt = make("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 20), Size = UDim2.fromOffset(300, 20),
        Text = "ragebot: waiting...", FontFace = Core.Body, TextSize = 14, TextColor3 = Color3.new(1, 1, 1),
        TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.25, ZIndex = 121, Active = false}, box)
    local rot = 0
    local shownState, pendingState, pendingSince = "waiting...", nil, 0
    track(RunService.RenderStepped:Connect(function(dt)
        local show = RG.ind and RG.state ~= nil and active()
        box.Visible = show
        if not show then return end
        rot = (rot + RG.spin * dt) % 360
        spinner.Rotation = rot
        local L, T, G = RG.barLen, RG.barTh, RG.barGap
        local off = G + L / 2
        arms[1].Size = UDim2.fromOffset(L, T); arms[1].Position = UDim2.new(0.5, off, 0.5, 0)
        arms[2].Size = UDim2.fromOffset(L, T); arms[2].Position = UDim2.new(0.5, -off, 0.5, 0)
        arms[3].Size = UDim2.fromOffset(T, L); arms[3].Position = UDim2.new(0.5, 0, 0.5, off)
        arms[4].Size = UDim2.fromOffset(T, L); arms[4].Position = UDim2.new(0.5, 0, 0.5, -off)
        for i = 1, 4 do arms[i].BackgroundColor3 = RG.indCol end
        box.Position = UDim2.new(0.5, 0, 0.5, RG.indY)
        txt.Position = UDim2.new(0.5, 0, 0.5, G + L + 8)
        txt.TextSize = RG.txtSize
        txt.TextColor3 = RG.indCol:Lerp(Color3.new(1, 1, 1), 0.55)
        local wantedState = RG.state or "waiting..."
        if wantedState == "round starting..." or wantedState == "searching..." then wantedState = "waiting..." end
        if wantedState ~= shownState then
            if pendingState ~= wantedState then pendingState, pendingSince = wantedState, os.clock() end
            if os.clock() - pendingSince >= 0.22 then shownState, pendingState = wantedState, nil end
        else
            pendingState = nil
        end
        local nm = (RG.indName and RG.target and RG.target.plr and (shownState == "firing..." or shownState == "locking on...")) and (" [" .. RG.target.plr.Name .. "]") or ""
        txt.Text = "ragebot: " .. shownState .. nm
    end))
end
