gui.Destroying:Connect(function()
    M.fire, M.aim, M.aimCd, M.melee, M.dash, M.rec = false, false, false, false, false, false
    M.auto, M.jumps, M.spread, M.fuse, M.noFuse = false, false, false, false, false
    SA.mm.back, SA.mm.range = false, false
    pcall(setNoFuse, false)
    for it, snapshot in pairs(orig) do
        local info = type(it) == "table" and rawget(it, "Info")
        if type(info) == "table" then
            for key, savedValue in pairs(snapshot) do
                if type(savedValue) == "table" then pcall(rawset, info, key, savedValue[1]) end
            end
        end
    end
    for it in pairs(eqHook) do pcall(unhookEquip, it) end
    if SA.refreshHook then pcall(SA.refreshHook) end
end)
end)() end


