local cRoot = mk("Frame", {Name = "AspenCrosshair", BackgroundTransparency = 1, BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), Visible = false, ZIndex = 3}, aimGui)
local cHold = mk("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(0, 0), ZIndex = 3}, cRoot)
local cBars, cStrokes = {}, {}
do
local cScale = mk("UIScale", {Scale = 1}, cHold)
local cDotF = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(0, 0), Visible = false, ZIndex = 5}, cHold)
local cDotC = mk("UICorner", {CornerRadius = UDim.new(1, 0)}, cDotF)
local cDotS = mk("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 1, Enabled = false, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, cDotF)
local conn = RunService.RenderStepped:Connect(function()
cScale.Scale = C.scale or 1
local on = C.on and C.cdot
cDotF.Visible = on == true
if on then
cDotF.Size = UDim2.fromOffset(C.cdotSz or 3, C.cdotSz or 3)
cDotF.BackgroundColor3 = C.cdotCol or WHITE
cDotF.BackgroundTransparency = C.cdotT or 0
cDotC.CornerRadius = UDim.new((C.cdotRound == false) and 0 or 1, 0)
cDotS.Enabled = C.cdotOut == true
end
end)
if track then track(conn) end
end
for i = 1, 4 do
cBars[i] = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 4}, cHold)
cStrokes[i] = mk("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 1, Enabled = false, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, cBars[i])
end
local cRings, cRingStrokes = {}, {}
for i = 1, 3 do
cRings[i] = mk("Frame", {BackgroundTransparency = 1, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Visible = false, ZIndex = 4}, cHold)
mk("UICorner", {CornerRadius = UDim.new(1, 0)}, cRings[i])
cRingStrokes[i] = mk("UIStroke", {Thickness = 2, Color = WHITE, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, cRings[i])
end
local cGlow = mk("UIStroke", {Thickness = 4, Color = WHITE, Transparency = 0.6, Enabled = false, ApplyStrokeMode = Enum.ApplyStrokeMode.Border}, cRings[1])
local cDot = mk("Frame", {BackgroundColor3 = WHITE, BorderSizePixel = 0, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(4, 4), ZIndex = 4}, cHold)
mk("UICorner", {CornerRadius = UDim.new(1, 0)}, cDot)
local cImg = mk("ImageLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Visible = false, ZIndex = 4}, cHold)
local cText = mk("TextLabel", {BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), AutomaticSize = Enum.AutomaticSize.XY, Text = "Aspen",
FontFace = Core.fontOf and Core.fontOf("Inconsolata") or Core.Body, TextSize = 14, TextColor3 = WHITE, ZIndex = 4}, cRoot)
local cTextStroke = mk("UIStroke", {Color = Color3.new(0, 0, 0), Thickness = 1, ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual}, cText)
local cT, cPos, cAng = 0, nil, 0
local function cFrame(dt)
local cam = Workspace.CurrentCamera
cRoot.Visible = C.on and cam ~= nil
if not cRoot.Visible then cPos = nil; return end
cT = cT + (dt)
local center = cam.ViewportSize / 2
local goal = center
if C.follow then
local sp = SA.tScreen
if not sp then
local rt = Core.rbTarget and Core.rbTarget()
if rt and rt.head then local v, on = cam:WorldToViewportPoint(rt.head.Position); if on then sp = Vector2.new(v.X, v.Y) end end
end
if sp then goal = sp end
end
if C.follow then
cPos = cPos or center
local d = (goal - cPos).Magnitude
if d <= C.fSnap then cPos = goal
else cPos = cPos:Lerp(goal, 1 - math.exp(-dt * C.fSpd / (1 + C.fDamp))) end
else cPos = center end
cHold.Position = UDim2.fromOffset(math.round(cPos.X), math.round(cPos.Y))
if C.rot then cAng = (cAng + dt * C.rotSpd) % 360 else cAng = 0 end
cHold.Rotation = C.angle + cAng
local gap = C.gap
if C.spread then gap = C.sMin + (C.sMax - C.sMin) * (0.5 + 0.5 * math.sin(cT * C.sSpd)) end
local st = C.style
local lines = st == "Lines" or st == "Lines + Circle" or st == "Lines + Diamond"
if C.pulse then gap = gap + math.abs(math.sin(cT * 3)) * C.pulseAmt end
local ccol = C.col
if C.cm == "Rainbow" then ccol = Color3.fromHSV((cT * C.cSpd * 0.2) % 1, 0.85, 1)
elseif C.cm == "Wave" then ccol = C.col:Lerp(C.colB, 0.5 + 0.5 * math.sin(cT * C.cSpd * 2))
elseif C.cm == "Pulse" then ccol = C.col:Lerp(Color3.new(0, 0, 0), 0.5 - 0.5 * math.sin(cT * C.cSpd * 4)) end
local ringOn = st == "Circle" or st == "Diamond" or st == "Lines + Circle" or st == "Lines + Diamond" or st == "Triple Ring"
local dia = st == "Diamond" or st == "Lines + Diamond"
local rr = C.rr + (C.pulse and math.abs(math.sin(cT * 3)) * C.pulseAmt or 0)
for i = 1, 3 do
local on = ringOn and (i == 1 or st == "Triple Ring")
cRings[i].Visible = on
if on then
local r = rr * (i == 1 and 1 or (i == 2 and 1.6 or 2.2))
cRings[i].Size = UDim2.fromOffset(r * 2, r * 2)
cRings[i].Rotation = dia and 45 or 0
local cr = cRings[i]:FindFirstChildOfClass("UICorner"); if cr then cr.CornerRadius = dia and UDim.new(0, 0) or UDim.new(1, 0) end
cRingStrokes[i].Color = ccol; cRingStrokes[i].Thickness = C.rth; cRingStrokes[i].Transparency = math.clamp(C.tr + (i - 1) * 0.25, 0, 1)
end
end
cGlow.Enabled = C.glow and ringOn; cGlow.Color = ccol; cGlow.Thickness = C.glowTh
local L, Th = C.len, C.th
local mid = gap + L / 2
local sh = {C.top, C.bot, C.left, C.right}
cBars[1].Size = UDim2.fromOffset(Th, L); cBars[1].Position = UDim2.fromOffset(0, -mid)
cBars[2].Size = UDim2.fromOffset(Th, L); cBars[2].Position = UDim2.fromOffset(0, mid)
cBars[3].Size = UDim2.fromOffset(L, Th); cBars[3].Position = UDim2.fromOffset(-mid, 0)
cBars[4].Size = UDim2.fromOffset(L, Th); cBars[4].Position = UDim2.fromOffset(mid, 0)
for i = 1, 4 do
cBars[i].Visible = lines and sh[i]
cBars[i].BackgroundColor3 = ccol; cBars[i].BackgroundTransparency = C.tr
cStrokes[i].Enabled = C.outline; cStrokes[i].Thickness = C.outTh
end
cDot.Visible = st == "Dot" or (lines and C.dot)
cDot.BackgroundColor3 = ccol; cDot.BackgroundTransparency = C.tr; cDot.Size = UDim2.fromOffset(C.dotSz, C.dotSz)
cImg.Visible = st == "Image" and C.img ~= ""
if cImg.Visible then cImg.Image = C.img; cImg.Size = UDim2.fromOffset(C.imgSize, C.imgSize); cImg.ImageTransparency = C.imgT; cImg.ImageColor3 = C.col end
cText.Visible = C.txtOn
if C.txtOn then
cText.Text = C.txt; cText.TextSize = C.txtSize; cText.TextColor3 = C.txtCM and ccol or C.txtCol; cText.TextTransparency = C.txtTr; cTextStroke.Enabled = C.txtOut; cTextStroke.Thickness = C.txtOutTh; cTextStroke.Color = C.txtOutCol
if Core.fontOf then cText.FontFace = Core.fontOf(C.txtFont) end
local tp = (C.follow and C.fMode == "Crosshair + Text") and cPos or center
local half = (lines and (gap + L) or (C.style == "Image" and C.imgSize / 2 or 4))
cText.Position = UDim2.fromOffset(math.round(tp.X), math.round(tp.Y + C.txtOff))
end
end
pcall(function() RunService:UnbindFromRenderStep("AspenCrosshair") end)
RunService:BindToRenderStep("AspenCrosshair", Enum.RenderPriority.Camera.Value + 5, function(dt) pcall(cFrame, dt) end)


