cs.Section("Motion Blur")
do
    local MBcfg = {on = false, strength = 40, max = 20}
    local mbFx, prevCF, smooth = nil, nil, 0
    local function getFx()
        if mbFx and mbFx.Parent == Lighting then return mbFx end
        for _, o in ipairs(Lighting:GetChildren()) do if o.Name == "AspenMotionBlur" then o:Destroy() end end
        mbFx = Instance.new("BlurEffect"); mbFx.Name = "AspenMotionBlur"; mbFx.Size = 0; mbFx.Enabled = false; mbFx.Parent = Lighting
        return mbFx
    end
    local function mbOff()
        MBcfg.on = false
        pcall(function() RunService:UnbindFromRenderStep("AspenMotionBlur") end)
        if mbFx then pcall(function() mbFx:Destroy() end); mbFx = nil end
        prevCF, smooth = nil, 0
    end
    Core.MotionBlurOff = mbOff
    local function mbStep(dt)
        local cam = workspace.CurrentCamera
        if not cam then return end
        local cf = cam.CFrame
        if prevCF then
            local d = math.max(dt, 1 / 240)
            local ang = math.acos(math.clamp(prevCF.LookVector:Dot(cf.LookVector), -1, 1)) / d
            local lin = (cf.Position - prevCF.Position).Magnitude / d
            if ang < 25 and lin < 300 then -- ignore camera cuts and teleports
                local target = math.clamp((ang * 3.2 + lin * 0.05) * (MBcfg.strength / 100), 0, MBcfg.max)
                local rate = target > smooth and 18 or 7 -- fast attack, slower release
                smooth = smooth + (target - smooth) * math.min(1, dt * rate)
            end
            local f = getFx()
            f.Size = smooth
            f.Enabled = smooth > 0.4
        end
        prevCF = cf
    end
    cs.Toggle("Motion Blur", false, function(v)
        if v == true then
            if MBcfg.on then return end
            MBcfg.on = true
            prevCF, smooth = nil, 0
            pcall(function() RunService:UnbindFromRenderStep("AspenMotionBlur") end)
            RunService:BindToRenderStep("AspenMotionBlur", Enum.RenderPriority.Camera.Value + 2, function(dt) pcall(mbStep, dt) end)
        else
            mbOff()
        end
    end)
    cs.Slider("Motion Blur Strength", 5, 100, 40, function(v) MBcfg.strength = v end, 1)
    cs.Slider("Motion Blur Max Size", 4, 40, 20, function(v) MBcfg.max = v end, 1)
end
