local function idFrom(str)
    if type(str) ~= "string" or str == "" then return nil end
    return str:match("rbxassetid://(%d+)") or str:match("[?&]id=(%d+)") or str:match("^(%d+)$")
end
local function hideInst(inst, prop)
    if inst:IsA("MeshPart") and prop == "MeshId" then inst.Transparency = 1
    elseif inst:IsA("SpecialMesh") and prop == "MeshId" then inst.Scale = Vector3.new(0, 0, 0)
    elseif inst:IsA("Sound") then inst.Volume = 0
    elseif inst:IsA("Decal") or inst:IsA("Texture") then inst.Transparency = 1
    elseif inst:IsA("ImageLabel") or inst:IsA("ImageButton") then inst.ImageTransparency = 1
    elseif inst:IsA("ParticleEmitter") then inst.Enabled = false end
end

---------------------------------------------------------------- one profile = one running injection
local profiles = {}   -- [name] = {stop = fn, rules = n}

local function stopProfile(name)
    local p = profiles[name]
    if p then profiles[name] = nil; pcall(p.stop) end
end

local function startProfile(NAME, RULES)
    stopProfile(NAME)
    local conns, activeManual, ourTracks = {}, setmetatable({}, {__mode = "k"}), setmetatable({}, {__mode = "k"})
    local sourceCache, unknownCount = {}, 0
    local LOCAL_CANDIDATES = {DELTA_DIR .. "/" .. NAME .. "/", DELTA_DIR .. "/", ROOT .. "/Local/", ""}

    local function stopManual(animator) local s = activeManual[animator]; if s then activeManual[animator] = nil; s() end end
    local function playManual(animator, data)
        stopManual(animator)
        local motors, start = motorsFor(animator), os.clock()
        local conn = RunService.RenderStepped:Connect(function()
            local t = os.clock() - start
            if data.length > 0 then
                if data.loop then t = t % data.length elseif t > data.length then t = data.length end
            end
            for name, list in pairs(data.tracks) do
                local m = motors[name]
                if m and m.Parent then m.Transform = sample(list, t) end
            end
        end)
        local function stopFn()
            conn:Disconnect()
            for name in pairs(data.tracks) do local m = motors[name]; if m then pcall(function() m.Transform = CFrame.new() end) end end
        end
        activeManual[animator] = stopFn
        return function() if activeManual[animator] == stopFn then stopManual(animator) end end
    end
    local function tryRegistered(animator, asset)
        if not asset.regId or asset.regOK == false then return nil end
        local a = Instance.new("Animation"); a.AnimationId = asset.regId
        local ok, tr = pcall(function() return animator:LoadAnimation(a) end)
        if not ok or not tr then asset.regOK = false; return nil end
        ourTracks[tr] = true
        if asset.regOK == nil then
            local t0 = os.clock()
            while tr.Length == 0 and os.clock() - t0 < 0.6 do task.wait() end
            asset.regOK = tr.Length > 0
            if not asset.regOK then pcall(function() tr:Stop(0) end); return nil end
        end
        return tr
    end

    local function readLocal(rule, label)
        local base = rule.local_path:match("([^/\\]+)$")
        local function tryRead(p)
            local okF, ex = pcall(isfile, p)
            if okF and ex then
                local okR, c = pcall(readfile, p)
                if okR and c and #c > 0 then return c end
            end
        end
        for _, dir in ipairs(LOCAL_CANDIDATES) do
            local d = tryRead(dir .. base)
            if d then return d end
        end
        if listfiles then
            local want = base:lower()
            local function scan(dir, depth)
                local okL, items = pcall(listfiles, dir)
                if not okL or type(items) ~= "table" then return end
                for _, p in ipairs(items) do
                    local nm = p:match("([^/\\]+)$") or p
                    if nm:lower() == want then local c = tryRead(p); if c then return c end end
                    if depth < 3 and isfolder and isfolder(p) then local c = scan(p, depth + 1); if c then return c end end
                end
            end
            local d = scan(DELTA_DIR, 0)
            if d then return d end
        end
        warnf(NAME, "Local file not found for '" .. label .. "'. Put \"" .. base .. "\" in " .. DELTA_DIR .. "/" .. NAME .. "/")
    end

    local function buildAsset(rule)
        local key = (rule.mode == "cdn") and rule.cdn_url or rule.local_path
        if sourceCache[key] ~= nil then return sourceCache[key] or nil end
        local label = rule.name or key
        if not FS_OK then sourceCache[key] = false; return nil end
        local hint = extOf(key)
        local fileName, kind, data
        if rule.mode == "cdn" then
            local h = hashStr(key)
            for _, e in ipairs(EXTS) do
                local p = CACHE_DIR .. "/" .. h .. "." .. e
                local okF, ex = pcall(isfile, p)
                if okF and ex then fileName, kind = p, EXT_TO_KIND[e]; break end
            end
            if not fileName then
                data = httpGet(key)
                if not data then task.wait(0.4); data = httpGet(key) end
                if not data then warnf(NAME, "Download failed: " .. key); sourceCache[key] = false; return nil end
            end
        else
            data = readLocal(rule, label)
            if not data then sourceCache[key] = false; return nil end
        end
        if data then
            local k, ext, out = sniff(data, hint)
            if not k then
                unknownCount = unknownCount + 1
                if unknownCount <= 3 then warnf(NAME, "Skipping '" .. label .. "': " .. tostring(ext)) end
                sourceCache[key] = false; return nil
            end
            kind = k
            fileName = CACHE_DIR .. "/" .. hashStr(key) .. "." .. ext
            if not pcall(writefile, fileName, out) then warnf(NAME, "Couldn't write " .. fileName); sourceCache[key] = false; return nil end
        end
        local result = {kind = kind, label = label}
        if kind == "anim" then
            local okG, objs = pcall(function() return game:GetObjects(getcustomasset(fileName)) end)
            local ks = okG and type(objs) == "table" and findKeyframeSequence(objs) or nil
            if not ks then warnf(NAME, "Couldn't open animation '" .. label .. "'"); sourceCache[key] = false; return nil end
            local okD, pd = pcall(buildPoseData, ks)
            if okD and pd and next(pd.tracks) then result.data = pd end
            pcall(function() result.regId = KeyframeSequenceProvider:RegisterKeyframeSequence(ks) end)
            if not result.regId and AnimationClipProvider then pcall(function() result.regId = AnimationClipProvider:RegisterAnimationClip(ks) end) end
            if not result.regId and not result.data then sourceCache[key] = false; return nil end
        else
            local okC, asset = pcall(getcustomasset, fileName)
            if not okC or not asset then sourceCache[key] = false; return nil end
            result.content = asset
        end
        sourceCache[key] = result
        return result
    end

    -- rules -> actions keyed by asset id
    local actions = {}
    for _, rule in ipairs(RULES) do
        if rule.enabled ~= false and type(rule.replace_ids) == "table" then
            local act
            local mode = rule.mode or "id"
            if mode == "id" and rule.with_id then act = {asset = {kind = "any", content = "rbxassetid://" .. tostring(rule.with_id)}}
            elseif mode == "id" or mode == "remove" then act = {remove = true}
            elseif (mode == "cdn" and rule.cdn_url) or (mode == "local" and rule.local_path) then act = {rule = rule} end
            if act then for _, id in ipairs(rule.replace_ids) do actions[tostring(id)] = act end end
        end
    end

    local MAX_ACTIVE, queue, qHead, qTail, activeCount = 8, {}, 1, 0, 0
    local processProp
    local function pump()
        while activeCount < MAX_ACTIVE and qHead <= qTail do
            local act = queue[qHead]; queue[qHead] = nil; qHead = qHead + 1
            activeCount = activeCount + 1
            task.spawn(function()
                local ok, asset = pcall(buildAsset, act.rule)
                if not ok then warnf(NAME, "Error loading '" .. tostring(act.rule.name) .. "': " .. tostring(asset)) end
                act.asset = (ok and asset) or false
                activeCount = activeCount - 1
                local waiting = act.waiting
                act.waiting, act.waitSet = nil, nil
                if waiting and act.asset then for _, e in ipairs(waiting) do processProp(e[1], e[2], e[3], e[4]) end end
                pump()
            end)
        end
    end
    local function request(act)
        if act.state then return end
        act.state = "queued"; qTail = qTail + 1; queue[qTail] = act; pump()
    end
    local function ensure(act)
        if act.rule then
            if act.asset == nil then request(act); while act.asset == nil do task.wait(0.05) end end
            return act.asset or nil
        end
        return act.asset
    end

    processProp = function(inst, prop, kind, slot)
        local ok, value = pcall(function() return inst[prop] end)
        if not ok then return end
        local id = idFrom(value)
        if not id then return end
        local act = (slot and actions[id .. ":" .. slot]) or actions[id]
        if not act then return end
        if act.remove then
            pcall(hideInst, inst, prop)
        elseif act.rule and act.asset == nil then
            local set = act.waitSet
            if not set then set = setmetatable({}, {__mode = "k"}); act.waitSet = set; act.waiting = {} end
            local mine = set[inst]
            if not mine then mine = {}; set[inst] = mine end
            if not mine[prop] and #act.waiting < 3000 then mine[prop] = true; act.waiting[#act.waiting + 1] = {inst, prop, kind, slot} end
            request(act)
        else
            local a = act.asset
            if a and a.content and (a.kind == kind or a.kind == "any") then pcall(function() inst[prop] = a.content end) end
        end
    end
    local function process(inst)
        local list = PROPS_BY_CLASS[inst.ClassName]
        if list then for _, p in ipairs(list) do processProp(inst, p[2], p[3], p[4]) end end
    end

    local hooked = setmetatable({}, {__mode = "k"})
    local function hookAnimator(animator)
        if hooked[animator] then return end
        hooked[animator] = true
        animator.AnimationPlayed:Connect(function(track)
            if ourTracks[track] then return end
            local id = idFrom(track.Animation and track.Animation.AnimationId)
            local act = id and actions[id]
            if not act or act.remove then return end
            task.spawn(function()
                local asset = ensure(act)
                if not asset then return end
                if asset.kind == "any" then
                    local a = Instance.new("Animation"); a.AnimationId = asset.content
                    local ok, newTrack = pcall(function() return animator:LoadAnimation(a) end)
                    if ok and newTrack then
                        ourTracks[newTrack] = true
                        pcall(function() track:AdjustWeight(0, 0) end)
                        newTrack.Priority = track.Priority; newTrack.Looped = track.Looped
                        newTrack:Play(0.1)
                        local function stopNew() ourTracks[newTrack] = nil; pcall(function() newTrack:Stop(0.1) end) end
                        if track.Looped then track.Stopped:Connect(stopNew) end
                        track.Destroying:Connect(stopNew)
                    end
                elseif asset.kind == "anim" then
                    pcall(function() track:AdjustWeight(0, 0) end)
                    local stopOurs
                    local tr = tryRegistered(animator, asset)
                    if tr then
                        tr.Priority = track.Priority
                        if asset.data then tr.Looped = asset.data.loop end
                        tr:Play(0)
                        stopOurs = function() pcall(function() tr:Stop(0) end) end
                    elseif asset.data then stopOurs = playManual(animator, asset.data) end
                    if stopOurs then track.Stopped:Connect(stopOurs) end
                end
            end)
        end)
    end
    local function handle(inst)
        process(inst)
        if inst.ClassName == "Animator" then hookAnimator(inst) end
    end

    -- replace the asset id before the game's LoadAnimation sees it
    local hookOK = false
    if hookmetamethod and getnamecallmethod and checkcaller then
        pcall(function()
            local old
            old = hookmetamethod(game, "__namecall", function(self, ...)
                if getnamecallmethod() == "LoadAnimation" and not checkcaller() and profiles[NAME] and profiles[NAME].live then
                    local anim = ...
                    if typeof(anim) == "Instance" then
                        local okA, id = pcall(function() return idFrom(anim.AnimationId) end)
                        local act = okA and id and actions[id]
                        if act and not act.remove and act.asset and act.asset.kind == "any" then pcall(function() anim.AnimationId = act.asset.content end) end
                    end
                end
                return old(self, ...)
            end)
            hookOK = true
        end)
    end

    task.spawn(function()
        for _, inst in ipairs(game:GetDescendants()) do handle(inst) end
    end)
    table.insert(conns, game.DescendantAdded:Connect(function(inst) task.defer(handle, inst) end))
    local acc = 0
    table.insert(conns, RunService.Heartbeat:Connect(function(dt)
        acc = acc + dt
        if acc < 1 then return end
        acc = 0
        local cam = workspace.CurrentCamera
        if cam then for _, i in ipairs(cam:GetDescendants()) do process(i) end end
        local char = Players.LocalPlayer and Players.LocalPlayer.Character
        if char then for _, i in ipairs(char:GetDescendants()) do process(i) end end
    end))

    local idCount = 0
    for _ in pairs(actions) do idCount = idCount + 1 end
    if #RULES <= 150 then
        local seen = {}
        for _, act in pairs(actions) do if act.rule and not seen[act] then seen[act] = true; request(act) end end
    end
    local entry = {rules = #RULES, ids = idCount, live = true}
    entry.stop = function()
        entry.live = false
        for _, c in ipairs(conns) do c:Disconnect() end
        for animator in pairs(activeManual) do stopManual(animator) end
    end
    profiles[NAME] = entry
    return entry
end

---------------------------------------------------------------- JSON -> rules
local function safeName(s) return (tostring(s):gsub("[^%w_%-]", "_")) end
local function numStr(v) if type(v) == "number" then return string.format("%.0f", v) end return tostring(v) end
local function parseRules(text)
    local ok, data = pcall(function() return HttpService:JSONDecode(text) end)
    if not ok or type(data) ~= "table" then return nil, nil, "not valid JSON" end
    local list = data.replacement_rules or data.rules or (data[1] ~= nil and data) or nil
    if type(list) ~= "table" then return nil, nil, "no \"replacement_rules\" list found" end
    local rules = {}
    for _, r in ipairs(list) do
        if type(r) == "table" and type(r.replace_ids) == "table" then
            local ids = {}
            for _, id in ipairs(r.replace_ids) do ids[#ids + 1] = numStr(id) end
            local rule = {name = r.name, replace_ids = ids, mode = r.mode or "id", enabled = r.enabled ~= false}
            if r.with_id ~= nil then rule.with_id = numStr(r.with_id) end
            rule.cdn_url, rule.local_path = r.cdn_url, r.local_path
            rules[#rules + 1] = rule
        end
    end
    if #rules == 0 then return nil, nil, "no usable rules in JSON" end
    return rules, (type(data) == "table" and (data.name or data.Name)) or nil
end

---------------------------------------------------------------- UI
local inj = fleasionInjector
local pasteText, profName = "", ""
local statusLbl
local function status(t) if statusLbl then statusLbl:Set(t) end end
local function activeList()
    local names = {}
    for n in pairs(profiles) do names[#names + 1] = n end
    table.sort(names)
    return #names == 0 and "Active: none" or ("Active: " .. table.concat(names, ", "))
end
local function inject(text, nameHint)
    local rules, jsonName, err = parseRules(text)
    if not rules then status("Failed: " .. tostring(err)); return false end
    local name = safeName((nameHint and nameHint ~= "" and nameHint) or jsonName or "Injected")
    local e = startProfile(name, rules)
    status(string.format("Injected '%s': %d rules, %d ids. %s", name, e.rules, e.ids, activeList()))
    return true
end
local function loadDelta()
    if not (listfiles and readfile) then status("Executor has no listfiles/readfile"); return end
    local okL, items = pcall(listfiles, DELTA_DIR)
    if not okL or type(items) ~= "table" then status("Could not read " .. DELTA_DIR); return end
    local loaded, failed = 0, 0
    for _, p in ipairs(items) do
        if p:lower():match("%.json$") then
            local okR, c = pcall(readfile, p)
            local base = (p:match("([^/\\]+)$") or p):gsub("%.[jJ][sS][oO][nN]$", "")
            if okR and c and inject(c, base) then loaded = loaded + 1 else failed = failed + 1 end
        end
    end
    status(string.format("Delta folder: %d loaded, %d failed. %s", loaded, failed, activeList()))
end

