-- Actual touch controls for movement features. They mirror the desktop toggles,
-- so the same feature state is used regardless of input device.
local movement = Core.movementFeatures or {}
local function addMovementButton(field, label, x, y)
    local cfg = movement[field]
    if not cfg or not cfg.toggleControl then return end
    local o = MB.new("move_" .. field, label, x, y)
    o.kind = "toggle"
    o.want = function() return UIS.TouchEnabled end
    o.on = cfg.enabled == true
    o.sync = function()
        o.on = cfg.enabled == true
        o.refresh()
    end
    o.onUp = function()
        local control = cfg.toggleControl
        local modeControl = cfg.modeControl
        if control and type(control.Get) == "function" and type(control.Set) == "function" then
            if not control:Get() then
                o.previousMode = cfg.mode
                if modeControl and type(modeControl.Set) == "function" then modeControl:Set("Always") end
                control:Set(true)
            else
                control:Set(false)
                if o.previousMode and modeControl and type(modeControl.Set) == "function" then
                    modeControl:Set(o.previousMode)
                    o.previousMode = nil
                end
            end
        end
        o.on = cfg.enabled == true
        o.refresh()
    end
    return o
end

