refreshPreview = function()
local activeSky = Lighting:FindFirstChildOfClass("Sky")
for _, item in ipairs(faceNames) do
local key = item[2]
local source = customRes[key] or resolveAsset(custom[key])
if not source and on and SKY[cur] then source = SKY[cur][key] end
if not source and activeSky then pcall(function() source = activeSky[key] end) end
local parts = faceCards[key]
parts.Image.Image = type(source) == "string" and source or ""
parts.Image.ImageColor3 = previewColors[key] or Color3.new(1, 1, 1)
end
for key, parts in pairs(faceCards) do parts.Stroke.Color = key == activeFace and Color3.fromRGB(210, 65, 85) or Color3.fromRGB(55, 58, 68) end
end
