local o
local visualOriginals = setmetatable({}, {__mode = "k"})
local visualCreated = setmetatable({}, {__mode = "k"})
local function visualEffect(className, name, properties)
    local effect = Lighting:FindFirstChild(name)
    if effect and effect.ClassName == className then
        if not visualOriginals[effect] then
            local snapshot = {}
            for _, property in ipairs(properties) do
                pcall(function() snapshot[property] = effect[property] end)
            end
            visualOriginals[effect] = snapshot
        end
        return effect
    end
    effect = Instance.new(className)
    effect.Name = name
    effect.Parent = Lighting
    visualCreated[effect] = true
    return effect
end
local function releaseVisualEffect(name)
    local effect = Lighting:FindFirstChild(name)
    if not effect then return end
    if visualCreated[effect] then
        pcall(function() effect:Destroy() end)
        visualCreated[effect] = nil
    elseif visualOriginals[effect] then
        for property, value in pairs(visualOriginals[effect]) do
            pcall(function() effect[property] = value end)
        end
        visualOriginals[effect] = nil
    end
end
local visualConn = RunService.RenderStepped:Connect(function(dt)
if Core.unloaded then return end
if V.spin and V.ch then root.Rotation = (root.Rotation + dt * 180) % 360 else root.Rotation = 0 end
vg.Visible = V.vig
local anyL = V.fb or V.nf or V.rb
if anyL and not o then o = {}; for _, k in ipairs({"Brightness", "Ambient", "OutdoorAmbient", "FogEnd", "FogStart", "GlobalShadows"}) do pcall(function() o[k] = Lighting[k] end) end end
if V.fb then pcall(function() Lighting.Brightness = 3; Lighting.Ambient = Color3.new(1, 1, 1); Lighting.OutdoorAmbient = Color3.new(1, 1, 1); Lighting.GlobalShadows = false end) end
if V.nf then pcall(function() Lighting.FogEnd = 1e6; Lighting.FogStart = 1e6 end) end
if V.rb then pcall(function() local c = Color3.fromHSV((os.clock() * 0.1) % 1, 0.6, 1); Lighting.Ambient = c; Lighting.OutdoorAmbient = c end) end
if not anyL and o then for k, v in pairs(o) do pcall(function() Lighting[k] = v end) end; o = nil end
local cc = Lighting:FindFirstChild("AspenGrade")
if V.grade or V.night then
cc = visualEffect("ColorCorrectionEffect", "AspenGrade", {"TintColor", "Saturation", "Contrast", "Brightness"})
cc.TintColor = V.night and Color3.fromRGB(120, 255, 140) or V.gt; cc.Saturation = V.sat; cc.Contrast = V.night and 0.25 or V.ctr; cc.Brightness = V.night and 0.15 or V.gradeBright
elseif cc then releaseVisualEffect("AspenGrade") end
local bloom = Lighting:FindFirstChild("AspenVisualBloom")
if V.bloom then bloom = visualEffect("BloomEffect", "AspenVisualBloom", {"Intensity", "Size", "Threshold", "Enabled"}); bloom.Intensity = V.bloomI; bloom.Size = V.bloomSize; bloom.Threshold = 1
elseif bloom then releaseVisualEffect("AspenVisualBloom") end
local rays = Lighting:FindFirstChild("AspenVisualSunRays")
if V.rays then rays = visualEffect("SunRaysEffect", "AspenVisualSunRays", {"Intensity", "Spread", "Enabled"}); rays.Intensity = V.raysI; rays.Spread = V.raysSpread
elseif rays then releaseVisualEffect("AspenVisualSunRays") end
local bl = Lighting:FindFirstChild("AspenBlur")
if V.blur > 0 then bl = visualEffect("BlurEffect", "AspenBlur", {"Size", "Enabled"}); bl.Size = V.blur
elseif bl then releaseVisualEffect("AspenBlur") end
end)
local function restoreVisualExtras()
    V.ch, V.spin, V.fb, V.nf, V.night, V.rb, V.grade, V.vig, V.bloom, V.rays = false, false, false, false, false, false, false, false, false, false
    V.blur = 0
    if o then for k, value in pairs(o) do pcall(function() Lighting[k] = value end) end; o = nil end
    for _, name in ipairs({"AspenGrade", "AspenVisualBloom", "AspenVisualSunRays", "AspenBlur"}) do releaseVisualEffect(name) end
    pcall(function() visualConn:Disconnect() end)
    pcall(function() g:Destroy() end)
end
