local re = addSub(mWorld, "Realism", "Lighting, atmosphere and post processing.")
local function realismHex(h)
    local ok, color = pcall(Color3.fromHex, h)
    return ok and color or Color3.new(1, 1, 1)
end

local W = {
    on = false, bright = 2.2, exposure = 0.1, shadowSoft = 0.15, diffuse = 1, spec = 1,
    atm = true, atmDensity = 0.3, atmHaze = 1.4, atmGlare = 0.4, atmColor = Color3.fromRGB(199, 205, 215),
    bloom = true, bloomI = 0.35, bloomSize = 28,
    cc = true, contrast = 0.12, sat = 0.1,
    dof = false, dofFar = 0.25, dofFocus = 70, dofRadius = 60,
    sunrays = false, sunI = 0.12, sunSpread = 0.8,
    rays = false, count = 150000, react = true, rayBright = 7, rayLen = 140, rayArea = 90, rayStretch = 85,
    rayColor = Color3.fromRGB(255, 236, 214),
}

local function setP(o, k, v) pcall(function() o[k] = v end) end


local orig
local function capture()
    if orig then return end
    orig = {}
    for _, k in ipairs({"Brightness", "ExposureCompensation", "ShadowSoftness", "EnvironmentDiffuseScale", "EnvironmentSpecularScale", "GlobalShadows"}) do
        pcall(function() orig[k] = Lighting[k] end)
    end
end

local created = {}
local function fx(class, name)
    local o = Lighting:FindFirstChild(name)
    if o and o.ClassName == class then return o end
    o = Instance.new(class); o.Name = name; o.Parent = Lighting
    created[name] = o
    return o
end
local function kill(name)
    local o = Lighting:FindFirstChild(name); if o then o:Destroy() end
    created[name] = nil
end

local function applyRealism()
    if not W.on then
        if orig then for k, v in pairs(orig) do setP(Lighting, k, v) end end
        kill("AspenAtmos"); kill("AspenBloom"); kill("AspenCC"); kill("AspenDOF"); kill("AspenSunRays")
        return
    end
    capture()
    setP(Lighting, "Brightness", W.bright)
    setP(Lighting, "ExposureCompensation", W.exposure)
    setP(Lighting, "ShadowSoftness", W.shadowSoft)
    setP(Lighting, "EnvironmentDiffuseScale", W.diffuse)
    setP(Lighting, "EnvironmentSpecularScale", W.spec)
    setP(Lighting, "GlobalShadows", true)
    if W.atm then
        local a = fx("Atmosphere", "AspenAtmos")
        setP(a, "Density", W.atmDensity); setP(a, "Haze", W.atmHaze); setP(a, "Glare", W.atmGlare)
        setP(a, "Offset", 0.25); setP(a, "Color", W.atmColor); setP(a, "Decay", Color3.fromRGB(106, 112, 125))
    else kill("AspenAtmos") end
    if W.bloom then
        local b = fx("BloomEffect", "AspenBloom")
        setP(b, "Intensity", W.bloomI); setP(b, "Size", W.bloomSize); setP(b, "Threshold", 0.95)
    else kill("AspenBloom") end
    if W.cc then
        local c = fx("ColorCorrectionEffect", "AspenCC")
        setP(c, "Contrast", W.contrast); setP(c, "Saturation", W.sat)
    else kill("AspenCC") end
    if W.dof then
        local d = fx("DepthOfFieldEffect", "AspenDOF")
        setP(d, "FarIntensity", W.dofFar); setP(d, "NearIntensity", 0); setP(d, "FocusDistance", W.dofFocus); setP(d, "InFocusRadius", W.dofRadius)
    else kill("AspenDOF") end
    if W.sunrays then
        local r = fx("SunRaysEffect", "AspenSunRays")
        setP(r, "Intensity", W.sunI); setP(r, "Spread", W.sunSpread); setP(r, "Enabled", true)
    else kill("AspenSunRays") end
end


re.Section("Realism")
re.Toggle("Realism", false, function(v) W.on = v; applyRealism() end)
re.Slider("Brightness", 1, 5, 2.2, function(v) W.bright = v; if W.on then applyRealism() end end, 0.1)
