task.wait()
task.wait()
do
local op = addSub(mSet, "Optimisation", "Hide everything outside your view in first person.")
local OPT = {on = false, fov = 140}
local MAXFOV = 140
local partSet, fxSet, fxOwner = {}, {}, {}
local hiddenParts, hiddenFx, ignored = {}, {}, {}
local conns, active, bound = {}, false, false
local BIND = "AspenOptimise"
local function fxProp(i)
if i:IsA("Decal") or i:IsA("Texture") then return "Transparency" end
if i:IsA("ParticleEmitter") or i:IsA("Beam") or i:IsA("Trail") or i:IsA("Fire") or i:IsA("Smoke")
or i:IsA("Sparkles") or i:IsA("Light") or i:IsA("Highlight") or i:IsA("BillboardGui") or i:IsA("SurfaceGui") then
return "Enabled"
end
end
local function ownerOf(i)
local p = i:FindFirstAncestorWhichIsA("BasePart")
if p then return p end
local par = i.Parent
if par and par:IsA("Model") then return par.PrimaryPart or par:FindFirstChildWhichIsA("BasePart", true) end
if i:IsA("Highlight") and i.Adornee then
local a = i.Adornee
if a:IsA("BasePart") then return a end
return a:FindFirstChildWhichIsA("BasePart", true)
end
end
local function trackInst(i)
if i:IsA("BasePart") then
if i:IsA("Terrain") then return end
local c = workspace.CurrentCamera
if c and i:IsDescendantOf(c) then return end
partSet[i] = true
elseif fxProp(i) then
local c = workspace.CurrentCamera
if c and i:IsDescendantOf(c) then return end
fxSet[i] = true; fxOwner[i] = ownerOf(i)
end
end
local function untrack(i)
partSet[i] = nil; hiddenParts[i] = nil; ignored[i] = nil
fxSet[i] = nil; fxOwner[i] = nil; hiddenFx[i] = nil
end
local function restoreAll()
for p, orig in pairs(hiddenParts) do
pcall(function() p.LocalTransparencyModifier = orig end)
end
for i, st in pairs(hiddenFx) do
pcall(function() i[st[1]] = st[2] end)
end
hiddenParts, hiddenFx = {}, {}
active = false
end
local function firstPerson(c)
if player.CameraMode == Enum.CameraMode.LockFirstPerson then return true end
local char = player.Character
local head = char and char:FindFirstChild("Head")
if head and head:IsA("BasePart") then
return (c.CFrame.Position - head.Position).Magnitude < 1.6
end
return false
end
local function step()
local c = workspace.CurrentCamera
if not c or not firstPerson(c) then
if active then restoreAll() end
return
end
active = true
local cf = c.CFrame
local cp, look = cf.Position, cf.LookVector
local half = math.rad(math.clamp(OPT.fov, 20, MAXFOV) / 2)
local cosH, sinH = math.cos(half), math.sin(half)
local char = player.Character
for p in pairs(partSet) do
local d = p.Position - cp
local dist = d.Magnitude
local rad = p.Size.Magnitude * 0.5
local cull = false
if dist > rad + 1 then
local s = rad / dist
local cosM = math.sqrt(1 - s * s)
local limit = cosH * cosM - sinH * s
cull = (d:Dot(look) / dist) < limit
end
local was = hiddenParts[p] ~= nil
if cull and not was then
if ignored[p] or (char and p:IsDescendantOf(char)) then
ignored[p] = true
else
hiddenParts[p] = p.LocalTransparencyModifier
p.LocalTransparencyModifier = 1
end
elseif was and not cull then
p.LocalTransparencyModifier = hiddenParts[p]
hiddenParts[p] = nil
end
end
for i in pairs(fxSet) do
local o = fxOwner[i]
if o and not partSet[o] then o = nil end
local hide = o ~= nil and hiddenParts[o] ~= nil
local st = hiddenFx[i]
if hide and not st then
local prop = fxProp(i)
hiddenFx[i] = {prop, i[prop]}
i[prop] = (prop == "Transparency") and 1 or false
elseif st and not hide then
i[st[1]] = st[2]
hiddenFx[i] = nil
end
end
end
local function start()
if bound then return end
bound = true
for _, i in ipairs(workspace:GetDescendants()) do trackInst(i) end
conns[1] = workspace.DescendantAdded:Connect(trackInst)
conns[2] = workspace.DescendantRemoving:Connect(untrack)
RunService:BindToRenderStep(BIND, Enum.RenderPriority.Camera.Value + 3, function() pcall(step) end)
pcall(step)
end
local function stop()
if not bound then return end
bound = false
pcall(function() RunService:UnbindFromRenderStep(BIND) end)
for _, cn in ipairs(conns) do cn:Disconnect() end
conns = {}
restoreAll()
partSet, fxSet, fxOwner, ignored = {}, {}, {}, {}
end
op.Section("View Culling")
op.Toggle("Optimisation", false, function(v)
OPT.on = v
if v then start() else stop() end
end)
op.Slider("Culling FOV", 60, MAXFOV, 140, function(v)
OPT.fov = math.min(v, MAXFOV)
if bound then pcall(step) end
end, 1)
op.Hint("In first person, everything outside this view cone (max 140) is hidden: parts, meshes, decals, textures, players and effects. Updates every frame and restores instantly when turned off or when you leave first person.")
gui.Destroying:Connect(stop)
end
end, function(e) warn("[Aspen] section failed: " .. tostring(e)) end)
fit = function()
local vp = gui.AbsoluteSize
local s = math.min((vp.X - (IS_MOBILE and 16 or 2 * (SQ + 26))) / WIN_W, (vp.Y - (IS_MOBILE and 14 or 30)) / WIN_H, 1)
holderScale.Scale = math.max(IS_MOBILE and 0.25 or 0.35, s) * userScale * 0.84
local hsc = math.clamp(math.min(vp.X / 1100, vp.Y / 700), 0.6, 1)
if HUD and HUD.autoScales then for _, u in ipairs(HUD.autoScales) do u.Scale = hsc end end
if Core.notifScale then Core.notifScale.Scale = hsc end
end
track(gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit))
pcall(function() local cam = workspace.CurrentCamera; if cam then track(cam:GetPropertyChangedSignal("ViewportSize"):Connect(fit)) end end)
fit()
-- ===================== Touch cursor + drag motion blur =====================
-- Flags: Core.TouchCursor = false disables the cursor, Core.MotionBlur = false disables the trail,
-- Core.TouchCursorInset = false removes the topbar offset if the dot appears shifted.
do
    local GuiService = game:GetService("GuiService")
    local WHITE = Color3.new(1, 1, 1)

    -- Motion blur: translucent ghosts trailing the dragged panel
    local N = 5
    local blurRoot = make("Frame", {Name = "AspenMotionBlur", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 0, Active = false, Visible = false}, gui)
    local ghosts, hist = {}, {}
    for k = 1, N do
        local g = Instance.new("Frame")
        g.Name = "Ghost"; g.BorderSizePixel = 0; g.BackgroundColor3 = WHITE; g.Active = false; g.ZIndex = 0
        local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, 6); c.Parent = g
        local s = Instance.new("UIStroke"); s.Color = WHITE; s.Thickness = 1.2; s.ApplyStrokeMode = Enum.ApplyStrokeMode.Border; s.Parent = g
        g.Parent = blurRoot
        ghosts[k] = {f = g, s = s}
    end
    local active, alpha = nil, 0
    track(RunService.RenderStepped:Connect(function(dt)
        if active and active.Parent and Core.MotionBlur ~= false then
            alpha = math.min(1, alpha + dt * 14)
            table.insert(hist, 1, {active.AbsolutePosition, active.AbsoluteSize})
            if #hist > N + 1 then table.remove(hist) end
        else
            alpha = math.max(0, alpha - dt * 9)
        end
        if alpha <= 0.01 then
            blurRoot.Visible = false
            if not active then hist = {} end
            return
        end
        blurRoot.Visible = true
        local base = gui.AbsolutePosition
        for k = 1, N do
            local h = hist[k + 1] or hist[#hist]
            local e = ghosts[k]
            if h then
                e.f.Position = UDim2.fromOffset(h[1].X - base.X, h[1].Y - base.Y)
                e.f.Size = UDim2.fromOffset(h[2].X, h[2].Y)
                e.f.BackgroundTransparency = 1 - (1 - (0.84 + k * 0.026)) * alpha
                e.s.Transparency = 1 - (1 - (0.72 + k * 0.05)) * alpha
            end
        end
    end))
    Core.Blur = {
        start = function(t) active = t end,
        stop = function() active = nil end,
    }

    -- Touch cursor: small white logo shown under every finger
    local cgui = make("ScreenGui", {Name = "AspenCursor", ResetOnSpawn = false, IgnoreGuiInset = true,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling, DisplayOrder = 2147483001}, PG)
    gui.Destroying:Connect(function() pcall(function() cgui:Destroy() end) end)
    local SIZE = 18
    local touches = {}
    local function mkCursor()
        local c = Instance.new("Frame")
        c.Name = "TouchCursor"; c.BackgroundTransparency = 1; c.BorderSizePixel = 0; c.Active = false
        c.AnchorPoint = Vector2.new(0.5, 0.5); c.Size = UDim2.fromOffset(SIZE * 0.55, SIZE * 0.55)
        local logo = Core.curLogo and Core.curLogo() or ""
        local parts = {}
        for _, spec in ipairs({{"Shadow", Color3.new(0, 0, 0), 0.55, UDim2.fromOffset(1, 1), 9}, {"Logo", WHITE, 0.02, UDim2.new(), 10}}) do
            local img
            if logo ~= "" then
                img = Instance.new("ImageLabel"); img.Image = logo; img.ImageColor3 = spec[2]; img.ImageTransparency = spec[3]
                img.BackgroundTransparency = 1; img.ScaleType = Enum.ScaleType.Fit
            else
                img = Instance.new("ImageLabel"); img.Image = ""; img.BackgroundColor3 = spec[2]; img.BackgroundTransparency = spec[3]
                local uc = Instance.new("UICorner"); uc.CornerRadius = UDim.new(1, 0); uc.Parent = img
            end
            img.Name = spec[1]; img.BorderSizePixel = 0; img.Active = false; img.ZIndex = spec[5]
            img.Size = UDim2.fromScale(1, 1); img.Position = spec[4]
            img.Parent = c
            parts[#parts + 1] = img
        end
        return c, parts, logo ~= ""
    end
    local function place(c, p)
        local off = Vector2.new(0, 0)
        if Core.TouchCursorInset ~= false then
            local ok, v = pcall(function() return GuiService:GetGuiInset() end)
            if ok and v then off = v end
        end
        c.Position = UDim2.fromOffset(p.X + off.X, p.Y + off.Y)
    end
    track(UIS.InputBegan:Connect(function(i)
        if i.UserInputType ~= Enum.UserInputType.Touch or Core.TouchCursor == false then return end
        local c = mkCursor()
        c.Parent = cgui
        touches[i] = c
        place(c, i.Position)
        tween(c, 0.12, {Size = UDim2.fromOffset(SIZE, SIZE)})
    end))
    track(UIS.InputChanged:Connect(function(i)
        local c = touches[i]
        if c then place(c, i.Position) end
    end))
    track(UIS.InputEnded:Connect(function(i)
        local c = touches[i]
        if not c then return end
        touches[i] = nil
        tween(c, 0.14, {Size = UDim2.fromOffset(SIZE * 0.5, SIZE * 0.5)})
        for _, ch in ipairs(c:GetChildren()) do
            if ch:IsA("ImageLabel") then tween(ch, 0.14, {ImageTransparency = 1, BackgroundTransparency = 1}) end
        end
        task.delay(0.2, function() c:Destroy() end)
    end))
end
