{n = "Sunset", c1 = "ff9a3c", c2 = "ff3c6e", tx = "ffffff", sc = "ffe0b0", nm = "ffb070", r = 20},
{n = "Lava", c1 = "ff3b00", c2 = "ffb300", tx = "ffffff", sc = "ffe08a", fx = "pulse", ts = true, nm = "ffb300"},
