local function mkBubble(parent, text, s0)
local s = resolve(s0)
local b = make("Frame", {BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = s.a, AutomaticSize = Enum.AutomaticSize.XY, Size = UD(0, 0), BorderSizePixel = 0, LayoutOrder = 2}, parent)
