make("UIListLayout", {Padding = UDim.new(0, 3), HorizontalAlignment = right and Enum.HorizontalAlignment.Right or Enum.HorizontalAlignment.Left, SortOrder = Enum.SortOrder.LayoutOrder}, col)
if not grouped then make("TextLabel", {BackgroundTransparency = 1, AutomaticSize = Enum.AutomaticSize.XY, Size = UD(0, 0), Text = (m.n or "?") .. "  " .. os.date("%H:%M"), FontFace = F_HEAVY, TextSize = 15,
TextColor3 = hexc(resolve(s).nm), LayoutOrder = 1, ZIndex = 4}, col) end
local b = mkBubble(col, m.t, s)
