local LAST = {["Combat.Aim Assist.Aim Assist.Aim Assist"] = true, ["Combat.Aimbot.Aimbot.Aimbot"] = true, ["Combat.Silent Aim.Silent Aim.Silent Aim"] = true, ["Combat.Rage.Activation.Enable Rage"] = true, ["Combat.Rage.Rage.Rage"] = true, ["Combat.Rage.Activation.Enable Rage"] = true}
local late, n = {}, 0
for k, v in pairs(SAVED) do
if not gui.Parent then break end
if LAST[k] then late[#late + 1] = {k, v}
elseif CONFIG_VALUES[k] ~= v then
CONFIG_VALUES[k] = v
if registry[k] then pcall(registry[k], v) end
n = n + (1)
end
end
for _, kv in ipairs(late) do
if not gui.Parent then break end
if CONFIG_VALUES[kv[1]] ~= kv[2] then
CONFIG_VALUES[kv[1]] = kv[2]
if registry[kv[1]] then pcall(registry[kv[1]], kv[2]) end
end
end
LOADING = false
if arrayRefresh then pcall(arrayRefresh) end
SAVED = {}
CFG_READY = true
pcall(clearDirty)
pcall(badgeRefresh)
end
